window.ACADEMY_DATA.lessons.push(...[{"number":15,"stage":3,"minutes":105,"title":"Hình ảnh và đa phương thức để truyền đạt ý","subtitle":"Prompt hình, tham chiếu, chỉnh vùng và kiểm dữ kiện trong hình.","prerequisites":"Bài 3–4 và 13. Có mục tiêu truyền đạt cụ thể.","refs":[["prompt",54,54],["use-cases",18,21],["agents-companion",21,22],["prompt-book",559,734]],"objectives":["Viết brief hình ảnh có tiêu chí quan sát.","Chọn tạo mới, chỉnh ảnh hay mở rộng ảnh theo mục tiêu.","Kiểm tính chính xác, quyền và khả năng tiếp cận."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Hình ảnh do AI tạo giúp thử nhanh một ý tưởng nhưng không tự mang bằng chứng đúng. Một sơ đồ kỹ thuật có thể đẹp mà hướng mũi tên sai, một ảnh minh họa lịch sử có thể chứa chi tiết không đúng thời kỳ. Bắt đầu từ mục tiêu: người xem cần hiểu điều gì? Sau đó nêu chủ thể, bố cục, góc nhìn, nhãn bắt buộc, màu, kích thước và vùng để đặt chữ. Với sơ đồ hoặc biểu đồ, dữ kiện phải lấy từ nguồn riêng và kiểm từng nhãn.\n\nSách Prompt Engineering for Generative AI mô tả tạo ảnh, image-to-image, inpainting và outpainting cùng các cơ chế điều khiển theo bản đồ đường nét/độ sâu. Tên lệnh và cú pháp của từng sản phẩm thay đổi theo phiên bản; bài học nên tập trung vào quyết định thao tác: cần giữ gì, thay gì, và tiêu chí nào chứng minh chỉnh sửa đạt.","activity":{"task":"Mở sách Prompt Engineering for Generative AI trang PDF 583–734. Chọn một phương thức chỉnh ảnh và viết tình huống thật mà nó phù hợp hơn tạo mới.","hint":"Nêu phần ảnh phải giữ và phần được phép sửa.","sample":"Có ảnh poster đúng bố cục nhưng sai số sách: chỉnh vùng chứa sách, giữ chữ và màu; kiểm lại toàn ảnh."}},{"title":"Prompt đa phương thức: ảnh, âm thanh & biểu đồ","points":[["Đa phương thức","Multimodal nghĩa là sử dụng nhiều loại đầu vào hoặc đầu ra như văn bản, hình ảnh, âm thanh. Có hình không đồng nghĩa mô hình đọc chính xác mọi chữ nhỏ. Cần cung cấp nhiệm vụ, vùng quan tâm, đơn vị và chất lượng nguồn phù hợp."],["Tách quan sát khỏi suy luận","Với ảnh bảng số, yêu cầu chép số nhìn rõ rồi mới phân tích. Với âm thanh, tách bản chép lời khỏi nhận xét ngữ điệu. Với biểu đồ, kiểm tra trục, đơn vị, mốc bắt đầu và chú giải trước khi kết luận xu hướng."],["Đánh giá theo phương thức","Chép lời kiểm tra từ/người nói; biểu đồ kiểm tra số/trục; ảnh thiết kế kiểm tra bố cục theo tiêu chí. Mô phỏng người dùng từ ảnh chỉ tạo giả thuyết, không thay thử nghiệm với người thật. Không có ảnh hoặc âm thanh thì không được nhận đã quan sát chúng."]],"prompt":"Phân tích [ảnh/âm thanh] để [mục tiêu]. Trước tiên trích thông tin trực tiếp quan sát được, ghi vùng hoặc thời điểm. Đánh dấu chỗ không rõ. Sau đó nêu nhận xét, tách khỏi dữ kiện. Với biểu đồ, đọc trục, đơn vị, mốc và chú giải. Nếu thiếu nguồn hoặc không hỗ trợ loại dữ liệu, nói rõ, không giả vờ đã xem/nghe.","body":"Cách thực hiện: 1. Chọn nguồn rõ, chỉ định vùng hoặc mốc thời gian. 2. Yêu cầu trích nội dung quan sát trước. 3. Xác nhận điểm khó đọc, bổ sung dữ liệu dạng bảng khi cần. 4. Thực hiện phân tích và đối chiếu lại nguồn.\n\nVì sao cách này hữu ích: Hai lượt quan sát và phân tích giúp phát hiện lỗi đọc trước khi tạo kết luận.\n\nChuyển sang lĩnh vực khác: Luôn chọn cách kiểm tra phù hợp loại dữ liệu; ảnh là bằng chứng quan sát, không phải quyền suy diễn không giới hạn.","activity":{"task":"Mở nguồn của phần này và làm thử: Tự tạo biểu đồ để kiểm tra AI. Dữ liệu: Dữ liệu mẫu: tháng 1 = 80, tháng 2 = 100, tháng 3 = 90 lượt đăng ký. Tạo biểu đồ cột bằng công cụ bạn có rồi chụp ảnh; nếu không tạo được, làm phần thiết kế prompt và ghi chưa thử ảnh. Bước đầu: Yêu cầu AI chép lại số từ ảnh.","hint":"Tháng 3 giảm so với tháng 2 nhưng vẫn cao hơn tháng 1.","sample":"Tăng 25% từ tháng 1 đến 2, giảm 10% từ tháng 2 đến 3. Chưa có dữ liệu để kết luận chiến dịch nào gây ra thay đổi. Chỉ có bảng thì kết quả là thử văn bản, không phải thử thị giác."}},{"title":"Prompt hình ảnh: bố cục, tham chiếu & chỉnh sửa","points":[["Prompt hình ảnh có cấu trúc","Nêu mục tiêu, chủ thể, hành động, bố cục, góc nhìn, ánh sáng, bảng màu, tỷ lệ và điều không được sai. Ví dụ tham chiếu có thể giúp giữ phong cách, nhưng phải có quyền sử dụng. Từ phủ định và trọng số chỉ hoạt động theo cú pháp của từng công cụ, không có chuẩn chung."],["Chọn thao tác","Tạo mới khi chưa có ảnh nền; image-to-image khi muốn giữ một phần bố cục; inpainting sửa vùng được đánh dấu; outpainting mở rộng khung. Các kỹ thuật điều khiển bằng đường nét, độ sâu hoặc vùng phân đoạn như ControlNet/SAM trong sách minh họa kiểm soát hình; khả năng cụ thể phụ thuộc phiên bản công cụ."],["Đánh giá và lặp","So ảnh với yêu cầu: có đúng đối tượng, số lượng, vị trí, văn bản và quyền không. Sửa một lỗi nổi bật mỗi vòng, giữ bản gốc. Với sơ đồ hoặc biểu đồ, dữ liệu và nhãn chữ cần kiểm tra riêng; hình trông thuyết phục có thể sai."]],"prompt":"Tạo minh họa cho [mục đích]. Chủ thể [X] ở [vị trí], hành động [Y]. Bố cục [tỷ lệ/góc], phong cách [mô tả], màu [bảng màu]. Giữ vùng [Z] trống cho văn bản. Không thêm dữ kiện hoặc nhãn chưa cung cấp. Sau khi tạo, liệt kê ba tiêu chí tôi phải tự kiểm tra trên ảnh.","body":"Cách thực hiện: 1. Viết brief hình một câu và tiêu chí nhìn thấy được. 2. Chọn loại thao tác theo tài sản ban đầu. 3. Tạo bản nháp, liệt kê lỗi có thể chỉ trên ảnh. 4. Sửa prompt hoặc vùng ảnh từng lượt, so trước/sau. 5. Kiểm quyền sử dụng và dữ kiện trước khi xuất.\n\nVì sao cách này hữu ích: Prompt nêu thành phần quan sát được, điều kiện bố cục và vòng kiểm.\n\nChuyển sang lĩnh vực khác: Dùng cho bài học, poster, prototype sản phẩm hoặc minh họa báo cáo; tiêu chí hình và quyền thay theo sản phẩm.","activity":{"task":"Mở nguồn của phần này và làm thử: Brief và vòng sửa hình. Dữ liệu: Cần một poster “Ngày đọc sách” có tiêu đề rõ, 3 cuốn sách, tông xanh; hình đầu có 4 cuốn và chữ sai. Bước đầu: Viết brief đầu và tiêu chí.","hint":"Chữ trong ảnh tạo sinh thường cần lớp thiết kế riêng để kiểm chính tả.","sample":"Bản sửa cần giảm về 3 cuốn và xử lý tiêu đề bằng chữ biên tập riêng hoặc kiểm từng ký tự. Không chỉ thêm “chính xác hơn” vào prompt."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Dùng ảnh tham chiếu cần quyền phù hợp và sự tôn trọng đối tượng. Không tự động đưa ảnh người thật, bài làm học viên hoặc tài sản của khách hàng vào công cụ chưa được cấp quyền. Negative prompt và trọng số từ có thể hữu ích trong một số mô hình nhưng không phải cú pháp chung; nếu công cụ không hỗ trợ, hãy dùng mô tả dương tính rõ ràng và vòng kiểm sau tạo.\n\nĐánh giá hình theo bốn nhóm: nội dung chính xác, bố cục đúng brief, khả năng đọc/tiếp cận, và nguồn/quyền. Khi mục tiêu học tập là hiểu kiến thức, người học cần giải thích vì sao sơ đồ đúng chứ không chỉ nộp một hình đẹp. Có thể dùng storyboard bằng chữ nếu chưa có công cụ tạo ảnh.","activity":{"task":"Tạo bảng kiểm cho một hình minh họa kiến thức hoặc poster công việc: ba yếu tố bắt buộc, hai lỗi nghiêm trọng, quyền nguồn.","hint":"Một tiêu chí phải kiểm nội dung, không chỉ thẩm mỹ.","sample":"Sơ đồ chu trình nước: đúng bốn quá trình và hướng mũi tên; chữ đọc được; không dùng ảnh người thật thiếu quyền."}}],"cases":[{"domain":"Marketing","situation":"Tự tạo biểu đồ để kiểm tra AI","input":"Dữ liệu mẫu: tháng 1 = 80, tháng 2 = 100, tháng 3 = 90 lượt đăng ký. Tạo biểu đồ cột bằng công cụ bạn có rồi chụp ảnh; nếu không tạo được, làm phần thiết kế prompt và ghi chưa thử ảnh.","steps":["Yêu cầu AI chép lại số từ ảnh.","So với bảng gốc.","Yêu cầu nhận xét và kiểm tra có bịa nguyên nhân không."],"result":"Tăng 25% từ tháng 1 đến 2, giảm 10% từ tháng 2 đến 3. Chưa có dữ liệu để kết luận chiến dịch nào gây ra thay đổi. Chỉ có bảng thì kết quả là thử văn bản, không phải thử thị giác.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Đánh giá poster theo thông tin ưu tiên và khả năng đọc, không suy ra doanh số từ bố cục. Luôn chọn cách kiểm tra phù hợp loại dữ liệu; ảnh là bằng chứng quan sát, không phải quyền suy diễn không giới hạn."},{"domain":"Truyền thông","situation":"Brief và vòng sửa hình","input":"Cần một poster “Ngày đọc sách” có tiêu đề rõ, 3 cuốn sách, tông xanh; hình đầu có 4 cuốn và chữ sai.","steps":["Viết brief đầu và tiêu chí.","Phân loại hai lỗi của ảnh đầu.","Viết yêu cầu sửa vùng/chủ thể tương ứng."],"result":"Bản sửa cần giảm về 3 cuốn và xử lý tiêu đề bằng chữ biên tập riêng hoặc kiểm từng ký tự. Không chỉ thêm “chính xác hơn” vào prompt.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Ảnh bìa sự kiện theo bộ màu, vị trí tiêu đề và vùng trống cho chữ. Dùng cho bài học, poster, prototype sản phẩm hoặc minh họa báo cáo; tiêu chí hình và quyền thay theo sản phẩm."}],"practice":{"basic":{"title":"Tự tạo biểu đồ để kiểm tra AI","task":"Dữ liệu mẫu: tháng 1 = 80, tháng 2 = 100, tháng 3 = 90 lượt đăng ký. Tạo biểu đồ cột bằng công cụ bạn có rồi chụp ảnh; nếu không tạo được, làm phần thiết kế prompt và ghi chưa thử ảnh.","steps":["Yêu cầu AI chép lại số từ ảnh.","So với bảng gốc.","Yêu cầu nhận xét và kiểm tra có bịa nguyên nhân không."],"hint":"Tháng 3 giảm so với tháng 2 nhưng vẫn cao hơn tháng 1.","solution":"Tăng 25% từ tháng 1 đến 2, giảm 10% từ tháng 2 đến 3. Chưa có dữ liệu để kết luận chiến dịch nào gây ra thay đổi. Chỉ có bảng thì kết quả là thử văn bản, không phải thử thị giác."},"applied":{"title":"Brief và vòng sửa hình","task":"Cần một poster “Ngày đọc sách” có tiêu đề rõ, 3 cuốn sách, tông xanh; hình đầu có 4 cuốn và chữ sai.","steps":["Viết brief đầu và tiêu chí.","Phân loại hai lỗi của ảnh đầu.","Viết yêu cầu sửa vùng/chủ thể tương ứng."],"hint":"Chữ trong ảnh tạo sinh thường cần lớp thiết kế riêng để kiểm chính tả.","solution":"Bản sửa cần giảm về 3 cuốn và xử lý tiêu đề bằng chữ biên tập riêng hoặc kiểm từng ký tự. Không chỉ thêm “chính xác hơn” vào prompt."},"rubric":["Brief có mục tiêu và bố cục.","Chọn thao tác ảnh đúng lý do.","Kiểm chữ/dữ kiện độc lập.","Có quyền và khả năng tiếp cận."]},"pitfalls":["Suy ra nguyên nhân chỉ từ biểu đồ.","Đánh giá phát âm từ văn bản gõ.","Dùng cú pháp trọng số của công cụ A trong công cụ B.","Dùng ảnh tham chiếu không có quyền hoặc tin sơ đồ AI không kiểm."]},{"number":16,"stage":3,"minutes":105,"title":"Biểu mẫu, meta-prompt và chuỗi sản xuất","subtitle":"Tái sử dụng phần cố định, truyền dữ liệu qua các bước và kiểm lỗi.","prerequisites":"Bài 6, 8 và 13–15.","refs":[["prompt",54,65],["agents-guide",15,16],["prompt-book",267,389],["prompt-book",468,558],["prompt-book",735,782]],"objectives":["Thiết kế prompt template với biến rõ.","Dùng meta-prompt để tạo bản nháp nhưng kiểm giả định mới.","Xây pipeline có điểm kiểm trước khi xuất bản."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Một prompt dùng lại nên tách phần ổn định khỏi dữ liệu thay đổi. Phần ổn định là mục tiêu, ranh giới, định dạng và tiêu chí; biến có thể là chủ đề, độc giả, nguồn, thời lượng. Nếu biến còn trống, hệ phải hỏi hoặc báo thiếu, không tự điền. Meta-prompt là yêu cầu AI tạo prompt khác; nó giúp khởi tạo nhanh nhưng bản prompt sinh ra cần kiểm như mọi đầu ra AI, nhất là các ràng buộc AI tự thêm.\n\nTrong chuỗi sản xuất, đầu ra mỗi bước là đầu vào bước sau. Vấn đề không chỉ là tạo nhiều prompt mà là xác định hợp đồng dữ liệu và điểm dừng. Ví dụ nghiên cứu chủ đề → bảng nguồn → dàn ý → bản nháp → kiểm khẳng định → hình minh họa → người duyệt. Bước sau không nên chạy nếu bước trước sai nguồn, sai schema hoặc chưa được phép.","activity":{"task":"Mở sách Prompt Engineering for Generative AI trang PDF 279–389. Chọn một chuỗi ba bước và viết biến, đầu ra và phép kiểm của từng bước.","hint":"Ghi trạng thái khi dữ liệu thiếu.","sample":"Nguồn thiếu ngày xuất bản → đánh dấu chưa xác minh → không dùng cho kết luận về thông tin mới."}},{"title":"Mẫu prompt, biến & hướng dẫn tích cực","points":[["Phần cố định và biến","Phần cố định là nhiệm vụ, tiêu chí và định dạng; biến là người đọc, dữ liệu, ngôn ngữ hoặc thời hạn. Mẫu tốt không gắn cứng tên khách hàng hoặc số liệu từ một ví dụ. Đánh dấu biến rõ bằng [noi_dung] rồi thay hết trước khi chạy."],["Đơn giản nhưng không thiếu","Ưu tiên động từ cụ thể: trích, so sánh, kiểm tra, viết lại. Thay “đừng lan man” bằng “trình bày ba kết luận, mỗi kết luận có một bằng chứng”. Các giới hạn bắt buộc vẫn cần giữ khi liên quan độ đúng, quyền hạn hoặc định dạng."],["Nhật ký và thay đổi mô hình","Lưu mục tiêu, prompt, dữ liệu, mô hình nếu biết, cấu hình, đầu ra, điểm và lỗi. Khi đổi mô hình hoặc bản hướng dẫn, chạy lại bộ kiểm tra. Tên phiên bản như summary-v2 giúp nhận diện thay đổi; không chỉ lưu câu trả lời tốt nhất."]],"prompt":"MẪU summary-v1\nNgười đọc: [nguoi_doc]. Mục đích: [quyet_dinh]. Nguồn: [van_ban].\nTrả 3 kết luận, mỗi kết luận kèm bằng chứng từ nguồn; sau đó liệt kê thông tin còn thiếu. Dùng ngôn ngữ phù hợp [trinh_do].\nƯu tiên theo thứ tự: đúng nguồn, đủ thông tin quyết định, ngắn gọn. Nếu còn biến chưa điền, hỏi lại thay vì tự suy đoán.","body":"Cách thực hiện: 1. Tô dấu mọi thông tin sẽ thay ở lần dùng tiếp theo. 2. Tách chúng thành danh sách biến và quy tắc điền. 3. Chuyển lời nhắc chung chung thành hành vi cụ thể. 4. Thử hai bộ dữ liệu khác nhau và lưu kết quả cả hai.\n\nVì sao cách này hữu ích: Mẫu chỉ rõ điều thay đổi và ưu tiên khi yêu cầu xung đột; không phụ thuộc trí nhớ của cuộc trò chuyện.\n\nChuyển sang lĩnh vực khác: Mỗi nhóm công việc nên có mẫu nhỏ riêng; không ép một prompt khổng lồ phục vụ mọi mục đích.","activity":{"task":"Mở nguồn của phần này và làm thử: Tạo mẫu dùng ở hai lĩnh vực. Dữ liệu: A: ghi chú cuộc họp dự án. B: ghi chú chương sách. Tự viết mỗi nguồn 80–120 từ, không đưa dữ liệu riêng tư. Bước đầu: Dùng chung mẫu nhưng thay người đọc và mục đích.","hint":"Tiêu chí đúng nguồn phải giữ nguyên dù phong cách thay đổi.","sample":"Một mẫu đạt không tự tái sử dụng tên, số hay kết luận của A trong B. Nhật ký cần ghi cụ thể sửa gì và trường hợp nào được cải thiện, không chỉ “v2 tốt hơn”."}},{"title":"Ghép chuỗi prompt, biểu mẫu & lời gọi công cụ","points":[["Prompt template và parser","Biểu mẫu giữ cấu trúc cố định, biến thay theo công việc. Parser/schema kiểm tra kiểu dữ liệu và trường bắt buộc; cú pháp hợp lệ chưa bảo đảm sự thật. Nếu parser lỗi, sửa hoặc chạy lại có giới hạn, không nuốt lỗi."],["Chaining và query planning","Một câu hỏi phức tạp có phụ thuộc: tìm nguồn → trích dữ kiện → so sánh → viết. Sơ đồ chuỗi nêu đầu vào, đầu ra, điều kiện chạy và cách xử lý lỗi. Không cần framework khi vài bước thủ công đã đủ; sách dùng LangChain như một minh họa theo phiên bản tại thời điểm viết."],["Function calling và quyền","Lời gọi công cụ có tham số cấu trúc và kết quả trả về. Model đề xuất lệnh, ứng dụng kiểm tra quyền và thực thi; câu “tôi đã gọi API” trong hội thoại không phải bằng chứng. Hành động gửi/xóa/mua cần người duyệt theo mức rủi ro."]],"prompt":"Thiết kế workflow cho [mục tiêu]. Mỗi bước ghi đầu vào, đầu ra JSON, phép kiểm, trường hợp thiếu dữ liệu và điều kiện dừng. Chỉ đề xuất lệnh công cụ; không báo đã thực thi nếu chưa có kết quả công cụ. Hành động bên ngoài phải chờ tôi duyệt.","body":"Cách thực hiện: 1. Vẽ các bước và phụ thuộc. 2. Định nghĩa schema đầu ra từng bước, kể cả trường thiếu. 3. Thử dữ liệu tốt, thiếu và sai kiểu. 4. Mô phỏng công cụ bằng kết quả mẫu, ghi rõ là mô phỏng. 5. Nếu tích hợp thật, kiểm tra quyền, log và người duyệt.\n\nVì sao cách này hữu ích: Chuỗi có hợp đồng và phân biệt rõ đề xuất với thực thi.\n\nChuyển sang lĩnh vực khác: Dùng cho biên tập, bán hàng, nghiên cứu hoặc học tập; chuỗi thay theo nguồn và quyền của từng môi trường.","activity":{"task":"Mở nguồn của phần này và làm thử: Thiết kế chuỗi tạo bản tin. Dữ liệu: Có ba bài viết được cung cấp. Cần bản tin 200 chữ, hai dẫn nguồn và chưa được gửi email. Bước đầu: Vẽ bốn bước từ trích dẫn đến bản nháp.","hint":"Bước cuối chỉ tạo bản nháp, không gửi.","sample":"Chuỗi hợp lý: trích ý có nguồn → kiểm nguồn/ngày → dàn ý → viết → kiểm số chữ, nguồn và quyền. Bài thiếu ngày cần ghi rõ hoặc bỏ theo quy tắc đã đặt."}},{"title":"Tạo sản phẩm nhiều bước: từ nghiên cứu đến xuất bản","points":[["Dự án mẫu trong sách","Sách dùng bài blog: nghiên cứu chủ đề → phỏng vấn người có chuyên môn → dàn ý → soạn → điều chỉnh phong cách → chọn tiêu đề/hình → giao diện. Đây là ví dụ về chia việc; không mặc định SEO hay số lượt xem là thước đo chất lượng duy nhất."],["Nguồn, chuyên gia và tuyên bố","AI có thể soạn câu hỏi phỏng vấn và tóm tắt câu trả lời, nhưng không được bịa một cuộc phỏng vấn đã diễn ra. Tách “nguồn đã đọc”, “ý kiến người thật đã xác nhận” và “ý tưởng do AI đề xuất”. Mỗi khẳng định cần phép kiểm thích hợp."],["Nghiệm thu đa chiều","Đo tính đúng, sự hữu ích với độc giả, rõ ràng, tính tiếp cận, quyền ảnh và khả năng bảo trì. Giữ phiên bản prompt, bản nháp và sửa của biên tập viên để thấy quyết định nào làm sản phẩm tốt hơn."]],"prompt":"Hãy hỗ trợ tạo [sản phẩm] cho [độc giả] theo quy trình: nguồn đã xác nhận → câu hỏi cần chuyên gia → dàn ý → bản nháp → kiểm từng dữ kiện → biên tập → quyết định xuất. Đánh dấu rõ nội dung chưa được xác minh. Chỉ tạo bản nháp; tôi là người duyệt và xuất bản.","body":"Cách thực hiện: 1. Xác định độc giả và câu hỏi thật cần trả lời. 2. Lập danh sách nguồn, điểm cần hỏi chuyên gia và chỗ chưa rõ. 3. Tạo dàn ý có nguồn, soạn từng phần, kiểm từng khẳng định. 4. Tạo hình có brief và quyền; biên tập giọng/tiêu đề. 5. Dùng rubric để quyết định xuất bản hay sửa.\n\nVì sao cách này hữu ích: Chuỗi làm rõ bằng chứng, quyền quyết định và điều kiện nghiệm thu.\n\nChuyển sang lĩnh vực khác: Áp dụng cho báo cáo, khóa học, tài liệu sản phẩm hoặc video; thay đầu ra và chuẩn kiểm, giữ chuỗi nguồn–bản nháp–duyệt.","activity":{"task":"Mở nguồn của phần này và làm thử: Thiết kế quy trình bài hướng dẫn. Dữ liệu: Cần một bài 500 chữ về thói quen học tập; có hai nguồn do bạn tự chọn và chưa phỏng vấn ai. Bước đầu: Viết dàn ý kèm vị trí đặt nguồn.","hint":"Không biến câu hỏi phỏng vấn thành câu trả lời của người thật.","sample":"Bản đạt nêu độc giả, câu hỏi, nguồn có thể kiểm, chỗ chuyên gia chưa trả lời, bản nháp và điểm duyệt. Nếu thiếu nguồn cho khẳng định lớn, hoãn xuất hoặc viết lại."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Chia việc tạo khả năng tìm lỗi, nhưng thêm mỗi bước làm tăng chi phí và có thể truyền sai thông tin. Dùng ít bước nhất đủ để kiểm. Với bước có kết quả không chắc, giữ bảng bằng chứng hoặc ID nguồn đi cùng dữ liệu, thay vì chỉ truyền bản tóm tắt. Nếu muốn tự động hóa, cần kiểm schema, thử lỗi và quyền cho hành động cuối.\n\nĐánh giá pipeline bằng kết quả cuối và lỗi từng bước. Nếu bài viết sai do nguồn yếu, sửa bước nghiên cứu; nếu đúng dữ kiện nhưng không phù hợp độc giả, sửa brief và biên tập. Không dùng một điểm tổng để che lỗi ở bước quan trọng. Khi mới thiết kế, cho người thật duyệt trước xuất bản hoặc gửi ra ngoài.","activity":{"task":"Với chuỗi bạn vừa vẽ, tạo một ca lỗi nguồn và viết bước nào phải dừng, thông báo cho ai, cách thử lại.","hint":"Không để bản nháp tự tiếp tục khi bảng nguồn rỗng.","sample":"Không tìm được chính sách hiện hành → dừng bước viết khuyến nghị → hỏi người sở hữu tài liệu."}}],"cases":[{"domain":"Nhân sự","situation":"Tạo mẫu dùng ở hai lĩnh vực","input":"A: ghi chú cuộc họp dự án. B: ghi chú chương sách. Tự viết mỗi nguồn 80–120 từ, không đưa dữ liệu riêng tư.","steps":["Dùng chung mẫu nhưng thay người đọc và mục đích.","Kiểm tra có dữ kiện A bị mang sang B không.","Ghi một thay đổi tạo phiên bản v2 và chạy lại cả hai."],"result":"Một mẫu đạt không tự tái sử dụng tên, số hay kết luận của A trong B. Nhật ký cần ghi cụ thể sửa gì và trường hợp nào được cải thiện, không chỉ “v2 tốt hơn”.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Mẫu hướng dẫn nhân viên mới thay vị trí, bộ phận và lịch, giữ cấu trúc việc cần làm. Mỗi nhóm công việc nên có mẫu nhỏ riêng; không ép một prompt khổng lồ phục vụ mọi mục đích."},{"domain":"Doanh nghiệp","situation":"Thiết kế quy trình bài hướng dẫn","input":"Cần một bài 500 chữ về thói quen học tập; có hai nguồn do bạn tự chọn và chưa phỏng vấn ai.","steps":["Viết dàn ý kèm vị trí đặt nguồn.","Tạo ba câu hỏi phỏng vấn nhưng đánh dấu chưa thực hiện.","Đặt rubric 4 tiêu chí trước khi soạn."],"result":"Bản đạt nêu độc giả, câu hỏi, nguồn có thể kiểm, chỗ chuyên gia chưa trả lời, bản nháp và điểm duyệt. Nếu thiếu nguồn cho khẳng định lớn, hoãn xuất hoặc viết lại.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Trang giải thích quy trình cho nhân viên mới, có nguồn chính sách và người duyệt. Áp dụng cho báo cáo, khóa học, tài liệu sản phẩm hoặc video; thay đầu ra và chuẩn kiểm, giữ chuỗi nguồn–bản nháp–duyệt."}],"practice":{"basic":{"title":"Tạo mẫu dùng ở hai lĩnh vực","task":"A: ghi chú cuộc họp dự án. B: ghi chú chương sách. Tự viết mỗi nguồn 80–120 từ, không đưa dữ liệu riêng tư.","steps":["Dùng chung mẫu nhưng thay người đọc và mục đích.","Kiểm tra có dữ kiện A bị mang sang B không.","Ghi một thay đổi tạo phiên bản v2 và chạy lại cả hai."],"hint":"Tiêu chí đúng nguồn phải giữ nguyên dù phong cách thay đổi.","solution":"Một mẫu đạt không tự tái sử dụng tên, số hay kết luận của A trong B. Nhật ký cần ghi cụ thể sửa gì và trường hợp nào được cải thiện, không chỉ “v2 tốt hơn”."},"applied":{"title":"Thiết kế quy trình bài hướng dẫn","task":"Cần một bài 500 chữ về thói quen học tập; có hai nguồn do bạn tự chọn và chưa phỏng vấn ai.","steps":["Viết dàn ý kèm vị trí đặt nguồn.","Tạo ba câu hỏi phỏng vấn nhưng đánh dấu chưa thực hiện.","Đặt rubric 4 tiêu chí trước khi soạn."],"hint":"Không biến câu hỏi phỏng vấn thành câu trả lời của người thật.","solution":"Bản đạt nêu độc giả, câu hỏi, nguồn có thể kiểm, chỗ chuyên gia chưa trả lời, bản nháp và điểm duyệt. Nếu thiếu nguồn cho khẳng định lớn, hoãn xuất hoặc viết lại."},"rubric":["Biến và giá trị thiếu rõ.","Mỗi bước có hợp đồng và phép kiểm.","Nguồn được giữ qua chuỗi.","Có người duyệt trước hành động ngoài."]},"pitfalls":["Để sót dữ liệu khách hàng cũ trong mẫu.","Sửa mẫu nhưng không kiểm tra lại trường hợp đã đúng.","Tin JSON hợp lệ là dữ kiện đúng.","Bước sau dùng đầu ra rỗng mà không báo lỗi.","Bịa trích dẫn của chuyên gia."]},{"number":17,"stage":4,"minutes":105,"title":"Khi nào một tác vụ cần AI agent?","subtitle":"Phân biệt prompt, workflow cố định và agent biết chọn bước.","prerequisites":"Bài 2, 8 và 9. Có tác vụ được mô tả bằng đầu vào–đầu ra.","refs":[["use-cases",22,24],["use-cases",29,30],["agents-guide",4,8],["agents-companion",6,8]],"objectives":["Giải thích agent qua mục tiêu, trạng thái, công cụ và vòng lặp.","Chọn mức tự động hóa tối thiểu đủ làm việc.","Xác định rủi ro và điều kiện dừng trước khi xây."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Một lời gọi AI để tóm tắt văn bản là prompt. Một chuỗi cố định trích dữ liệu rồi viết báo cáo là workflow. Agent có thể chọn hành động tiếp theo dựa trên quan sát mới, dùng công cụ và lặp cho đến khi đạt điều kiện dừng hoặc cần con người. Tài liệu Practical Guide to Building Agents khuyên cân nhắc agent cho quyết định phức tạp, quy tắc cứng dễ vỡ và dữ liệu phi cấu trúc; không phải mọi tác vụ nhiều bước đều cần agent.\n\nHãy so mức đơn giản nhất có thể đạt yêu cầu. Checklist, mẫu prompt, mã quy tắc hoặc người duyệt có thể rẻ và dễ kiểm hơn. Agent thêm khả năng thích nghi nhưng cũng thêm đường lỗi: chọn sai công cụ, lặp vô hạn, tiêu quá nhiều lượt, đưa dữ liệu sai nơi hoặc hành động quá quyền. Trước khi xây, đặt thước đo hiệu quả so với baseline và ngân sách lượt chạy.","activity":{"task":"Mở A Practical Guide to Building Agents trang PDF 4–6. Chọn một tác vụ của bạn và lập bảng ba phương án: prompt đơn, workflow cố định, agent.","hint":"Nêu lợi ích và chi phí kiểm của từng phương án.","sample":"Tóm tắt 10 email có cùng định dạng: workflow có thể đủ; xử lý yêu cầu khách hàng không dự đoán trước có thể cần agent có quyền giới hạn."}},{"title":"Từ tác vụ đơn lẻ đến quy trình tự động","points":[["Quy trình là chuỗi việc phụ thuộc","Một báo cáo tuần có thể đọc dữ liệu, kiểm tra chất lượng, tính chỉ số, viết nhận xét và gửi duyệt. Mỗi bước phải có đầu vào, đầu ra, người chịu trách nhiệm và điều kiện chuyển. AI không nhất thiết cần tham gia bước tính toán đã có công thức chắc chắn."],["Tự động hóa cần cơ chế chạy","Một prompt có chữ “hàng tuần” chưa tạo lịch chạy. Hệ thống thật cần bộ lập lịch hoặc sự kiện kích hoạt, công cụ truy cập, nơi lưu trạng thái và theo dõi lỗi. Trợ lý được gọi thủ công khác agent chạy nền."],["Thiết kế ngoại lệ","Quy định khi nguồn chưa cập nhật, thiếu cột, API lỗi hoặc người duyệt chưa phản hồi. Hành động ghi/gửi cần tránh lặp nếu chạy lại. Khi thử ban đầu, có thể tạo bản nháp để kiểm tra thay vì trực tiếp phát hành."]],"prompt":"Thiết kế quy trình cho [việc lặp]. Với mỗi bước, nêu đầu vào, xử lý, đầu ra, công cụ/người thực hiện và điều kiện lỗi. Phân biệt bước dùng quy tắc cố định và bước cần AI. Nêu trigger, cách tránh thực hiện lặp và điều kiện chuyển người xử lý. Hiện chỉ lập thiết kế và chạy mẫu trên [dữ liệu], chưa khẳng định đã tạo lịch.","body":"Cách thực hiện: 1. Vẽ quy trình hiện tại từ đầu đến cuối. 2. Gán nhóm ứng dụng và phương pháp phù hợp cho từng bước. 3. Đặt điểm kiểm tra và chuyển người xử lý. 4. Thử một vòng bằng dữ liệu nhỏ trước khi gắn lịch.\n\nVì sao cách này hữu ích: Prompt làm rõ hạ tầng cần thiết và phạm vi thực thi thực sự.\n\nChuyển sang lĩnh vực khác: Chuyển từ ngành này sang ngành khác bằng cách thay dữ liệu, điểm phê duyệt và thước đo chất lượng.","activity":{"task":"Mở nguồn của phần này và làm thử: Thiết kế bản tin tuần. Dữ liệu: Đầu vào là ba ghi chú dự án; đầu ra là bản nháp tối đa 200 từ. Phải có người duyệt trước khi gửi. Một tuần có thể không có dữ liệu mới. Bước đầu: Vẽ các bước và điểm duyệt.","hint":"Không có dữ liệu mới không có nghĩa mọi dự án đều hoàn thành.","sample":"Đọc nguồn → xác nhận thời điểm → trích thay đổi → tạo bản nháp → người duyệt → gửi bằng công cụ được cấp. Không có cập nhật thì ghi trạng thái đó; không bịa tiến độ."}},{"title":"Khi nào cần agent?","points":[["Agent theo cách dùng của tài liệu","Agent dùng mô hình để quyết định cách thực hiện nhiều bước và công cụ để thu thập thông tin hoặc hành động. Một bộ phân loại một lượt hoặc chatbot chỉ trả lời chưa nhất thiết là agent. Thuật ngữ có thể được dùng khác nhau giữa sản phẩm; hãy nhìn khả năng điều khiển quy trình thật."],["Ba dấu hiệu phù hợp","Nguồn gợi ý quyết định nhiều ngoại lệ, bộ quy tắc khó bảo trì và dữ liệu phi cấu trúc. Nếu thao tác là cộng số hoặc chuyển định dạng theo quy tắc rõ, chương trình xác định thường dễ kiểm tra hơn. Cần chứng minh agent cải thiện kết quả chứ không chỉ có vẻ hiện đại."],["Nền tảng trước tự chủ","Đặt phạm vi, công cụ, tiêu chí hoàn thành và đường chuyển người xử lý. Bắt đầu với một agent hoặc workflow nhỏ, đo rồi mới thêm phức tạp. Mức tự chủ nên phù hợp hậu quả và khả năng đảo ngược hành động."]],"prompt":"Đánh giá nhiệm vụ [việc] theo ba phương án: quy tắc cố định, workflow có AI, agent dùng công cụ. Nêu độ bất định, dữ liệu, ngoại lệ và hậu quả sai. Chọn phương án đơn giản nhất đáp ứng tiêu chí [tiêu chí]. Nếu đề xuất agent, chỉ rõ quyết định nào cần linh hoạt và cách chuyển lại cho người dùng khi thất bại.","body":"Cách thực hiện: 1. Mô tả biến thiên thực tế của nhiệm vụ. 2. So ba phương án: quy tắc, workflow có AI, agent. 3. Xác định công cụ và điểm cần quyết định linh hoạt. 4. Lập thử nghiệm nhỏ cùng tiêu chí thành công và giới hạn.\n\nVì sao cách này hữu ích: So phương án dựa trên nhu cầu thực thay vì bắt đầu từ kiến trúc yêu thích.\n\nChuyển sang lĩnh vực khác: Khung lựa chọn này áp dụng xuyên ngành; quyền hạn và tiêu chí kiểm tra phải thay theo bối cảnh.","activity":{"task":"Mở nguồn của phần này và làm thử: Chọn cách triển khai. Dữ liệu: A: tính tổng số lượng theo mã. B: tóm tắt ghi chú theo mẫu cố định. C: tra nhiều hệ thống để xử lý yêu cầu giao hàng có ngoại lệ. Bước đầu: Chọn phương án cho A/B/C.","hint":"Không phải cứ có nhiều bước là bắt buộc agent; workflow cố định vẫn có thể đủ.","sample":"A ưu tiên mã xác định; B có thể một lần gọi mô hình trong workflow; C là ứng viên agent nếu đường đi tùy tình huống và cần công cụ. Cần chính sách, quyền đọc, tiêu chí dừng và chuyển người xử lý."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Một agent đơn thường dễ quan sát hơn hệ nhiều agent. Định nghĩa mục tiêu thành tiêu chí cụ thể, ví dụ “soạn bản nháp có ít nhất hai trang nguồn” thay vì “giải quyết hoàn hảo”. Vòng chạy cần điều kiện thành công, giới hạn lượt, lỗi công cụ, thiếu dữ liệu và điểm chuyển người. Nếu không đo được trạng thái đạt, agent có thể tiếp tục tạo hành động mà không tạo giá trị.\n\nKhi thử, dùng môi trường mô phỏng và dữ liệu mẫu trước. Ghi trace: ở mỗi bước agent quan sát gì, chọn gì, công cụ trả gì, vì sao dừng. Nhờ trace, ta phân biệt lỗi mô hình với lỗi công cụ, quyền hoặc dữ liệu.","activity":{"task":"Viết hợp đồng dừng cho tác vụ bạn chọn: đạt khi nào, dừng vì lỗi nào, chuyển người khi nào.","hint":"Thêm giới hạn lượt và hành động tác động bên ngoài.","sample":"Đạt khi bản nháp có 2 nguồn hợp lệ; dừng sau 5 lượt hoặc khi nguồn không đủ; không tự gửi."}}],"cases":[{"domain":"Quản lý","situation":"Thiết kế bản tin tuần","input":"Đầu vào là ba ghi chú dự án; đầu ra là bản nháp tối đa 200 từ. Phải có người duyệt trước khi gửi. Một tuần có thể không có dữ liệu mới.","steps":["Vẽ các bước và điểm duyệt.","Định nghĩa hành vi khi không có cập nhật.","Mô phỏng một vòng, ghi rõ chưa gửi thật."],"result":"Đọc nguồn → xác nhận thời điểm → trích thay đổi → tạo bản nháp → người duyệt → gửi bằng công cụ được cấp. Không có cập nhật thì ghi trạng thái đó; không bịa tiến độ.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Báo cáo tiến độ dự án từ ghi chú → bảng việc → bản nháp cập nhật. Chuyển từ ngành này sang ngành khác bằng cách thay dữ liệu, điểm phê duyệt và thước đo chất lượng."},{"domain":"Dịch vụ","situation":"Chọn cách triển khai","input":"A: tính tổng số lượng theo mã. B: tóm tắt ghi chú theo mẫu cố định. C: tra nhiều hệ thống để xử lý yêu cầu giao hàng có ngoại lệ.","steps":["Chọn phương án cho A/B/C.","Nêu dữ liệu và công cụ cần cho C.","Đề xuất một giới hạn cho thử nghiệm đầu tiên."],"result":"A ưu tiên mã xác định; B có thể một lần gọi mô hình trong workflow; C là ứng viên agent nếu đường đi tùy tình huống và cần công cụ. Cần chính sách, quyền đọc, tiêu chí dừng và chuyển người xử lý.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Xử lý yêu cầu khách nhiều bước có ngoại lệ có thể phù hợp agent nếu công cụ và chính sách rõ. Khung lựa chọn này áp dụng xuyên ngành; quyền hạn và tiêu chí kiểm tra phải thay theo bối cảnh."}],"practice":{"basic":{"title":"Thiết kế bản tin tuần","task":"Đầu vào là ba ghi chú dự án; đầu ra là bản nháp tối đa 200 từ. Phải có người duyệt trước khi gửi. Một tuần có thể không có dữ liệu mới.","steps":["Vẽ các bước và điểm duyệt.","Định nghĩa hành vi khi không có cập nhật.","Mô phỏng một vòng, ghi rõ chưa gửi thật."],"hint":"Không có dữ liệu mới không có nghĩa mọi dự án đều hoàn thành.","solution":"Đọc nguồn → xác nhận thời điểm → trích thay đổi → tạo bản nháp → người duyệt → gửi bằng công cụ được cấp. Không có cập nhật thì ghi trạng thái đó; không bịa tiến độ."},"applied":{"title":"Chọn cách triển khai","task":"A: tính tổng số lượng theo mã. B: tóm tắt ghi chú theo mẫu cố định. C: tra nhiều hệ thống để xử lý yêu cầu giao hàng có ngoại lệ.","steps":["Chọn phương án cho A/B/C.","Nêu dữ liệu và công cụ cần cho C.","Đề xuất một giới hạn cho thử nghiệm đầu tiên."],"hint":"Không phải cứ có nhiều bước là bắt buộc agent; workflow cố định vẫn có thể đủ.","solution":"A ưu tiên mã xác định; B có thể một lần gọi mô hình trong workflow; C là ứng viên agent nếu đường đi tùy tình huống và cần công cụ. Cần chính sách, quyền đọc, tiêu chí dừng và chuyển người xử lý."},"rubric":["Chọn agent có lý do so với cách đơn giản.","Mục tiêu đo được.","Có giới hạn lượt và ngân sách.","Có trace và người xử lý ngoại lệ."]},"pitfalls":["Coi lời hứa trong chat là lịch đã tạo.","Không tính lỗi ở bước giao giữa hai hệ thống.","Dùng agent cho phép tính đơn giản.","Tăng tự chủ trước khi đo chất lượng."]},{"number":18,"stage":4,"minutes":105,"title":"Công cụ, trạng thái và bộ nhớ agent","subtitle":"Quyền hành động, dữ kiện tạm, tri thức dài hạn và cách quên.","prerequisites":"Bài 8 và 17. Biết hợp đồng công cụ.","refs":[["agents-guide",7,12],["agents-companion",7,7],["agents-guide",13,16],["agents-companion",28,31],["agents-companion",38,39],["prompt-book",521,558],["prompt-book",468,558]],"objectives":["Định nghĩa hợp đồng công cụ đọc và ghi.","Phân biệt trạng thái phiên với bộ nhớ dài hạn.","Thiết kế quy tắc ghi, sửa, xóa và truy cập bộ nhớ."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Tài liệu OpenAI mô tả agent qua mô hình, công cụ và chỉ dẫn. Mô hình đề xuất bước; ứng dụng cấp công cụ và thực thi; chỉ dẫn đặt mục tiêu và giới hạn. Công cụ đọc như tìm tài liệu khác về hậu quả so với công cụ ghi như tạo đơn hàng. Tham số phải được kiểm kiểu, phạm vi và quyền ở lớp ứng dụng, không chỉ ghi trong prompt. Nếu công cụ trả lỗi, agent cần nhận trạng thái lỗi thật và chọn thử lại có giới hạn, hỏi thêm hoặc dừng.\n\nTrạng thái phiên là những gì cần cho tác vụ đang chạy: mục tiêu, bước đã làm, kết quả công cụ, ngân sách còn. Bộ nhớ dài hạn là thông tin được giữ qua nhiều phiên. Không nên biến mọi câu hội thoại thành ký ức vĩnh viễn. Một mục nhớ cần nguồn, thời điểm, mục đích, mức chắc chắn, quyền truy cập và cách người dùng sửa/xóa.","activity":{"task":"Mở Agents Companion trang PDF 28–31 và Prompt Engineering for Generative AI trang PDF 521–558. Thiết kế bản ghi bộ nhớ cho một mục tiêu học đã được người dùng xác nhận.","hint":"Ghi thời hạn và điều kiện cập nhật.","sample":"Mục tiêu “học thống kê cơ bản”, nguồn: người học xác nhận ngày X, phạm vi: trợ lý học, xem lại sau 4 tuần, có nút sửa/xóa."}},{"title":"Model, tools & instructions","points":[["Mô hình là một thành phần","Chọn mô hình theo khả năng hoàn thành nhiệm vụ, chi phí và thời gian. Nguồn đề xuất thiết lập chất lượng nền bằng mô hình đủ khả năng rồi thử lựa chọn nhỏ hơn. Khóa học không cố định tên mô hình vì khả năng, giá và quyền truy cập có thể đổi."],["Công cụ phải mô tả chính xác","Công cụ dữ liệu đọc thông tin; công cụ hành động cập nhật hệ thống; công cụ điều phối gọi hoặc chuyển việc cho agent khác. Tên, tham số, kết quả, lỗi và tác động phụ cần rõ. Công cụ có tên gần giống dễ khiến chọn sai dù số lượng không nhiều."],["Instructions là quy trình thực thi","Chuyển tài liệu thao tác thành bước có hành động và nhánh khi thiếu thông tin. Giữ chính sách thật, không tự thêm quyền. Chỉ dẫn rõ không thay thế xác thực và kiểm tra quyền ở phía hệ thống."]],"prompt":"Thiết kế agent cho [mục tiêu]. Lập ba phần: tiêu chí chọn mô hình; công cụ (tên, mục đích, tham số, đầu ra, lỗi, quyền đọc/ghi); chỉ dẫn theo từng bước và ngoại lệ. Chỉ dùng các công cụ đã có [danh sách]. Nêu hành động nào cần xác nhận và điều kiện hoàn thành. Không mô tả công cụ chưa có như đã kết nối.","body":"Cách thực hiện: 1. Chọn tập thử đại diện để so mô hình. 2. Liệt kê công cụ cần thiết và loại tác động. 3. Viết tham số, kết quả và lỗi của từng công cụ. 4. Viết chỉ dẫn gắn mỗi bước với công cụ hoặc sản phẩm.\n\nVì sao cách này hữu ích: Ba phần tạo hợp đồng rõ giữa mô hình, công cụ và quy trình.\n\nChuyển sang lĩnh vực khác: Thiết kế công cụ theo thao tác và rủi ro, không theo một ngành cụ thể.","activity":{"task":"Mở nguồn của phần này và làm thử: Agent hỗ trợ mượn sách. Dữ liệu: Có hai công cụ giả lập: lookup_loan(book_id) và draft_extension(book_id,days). Công cụ thứ hai chỉ tạo bản nháp; không gia hạn thật. Bước đầu: Viết schema bằng lời cho hai công cụ.","hint":"Tên draft_extension không cho phép nói đã gia hạn.","sample":"Hỏi mã sách nếu thiếu → tra khoản mượn → kiểm tra điều kiện trong chính sách được cung cấp → tạo bản nháp nếu phù hợp → báo cần duyệt. Không tự đặt chính sách số ngày nếu nguồn chưa có."}},{"title":"Vòng chạy, trạng thái, bộ nhớ & registry","points":[["Run và trạng thái","Một run là lần thực hiện mục tiêu, thường có vòng gọi mô hình/công cụ tới khi hoàn thành, lỗi hoặc hết giới hạn. Trạng thái lưu việc đã làm, dữ kiện xác nhận và bước đang chờ. Không dựa hoàn toàn vào việc mô hình nhớ toàn bộ hội thoại."],["Bộ nhớ theo phạm vi","Bộ nhớ ngắn hạn phục vụ phiên; dài hạn có thể lưu sở thích hoặc dữ liệu tham chiếu khi được phép. Cần nguồn, thời điểm, quyền truy cập và cách sửa/xóa. Ghi nhớ phản hồi không tự có nghĩa mô hình được huấn luyện lại. Cache là kết quả dùng lại, phải có điều kiện hết hạn."],["Registry và giao tiếp","Registry là danh mục có tên, năng lực, tham số, quyền và phiên bản của công cụ/agent. Với tác vụ nền, cần mã tác vụ, trạng thái, thông báo thay đổi và khả năng tiếp tục sau gián đoạn. Việc dùng nhiều agent làm tăng yêu cầu quản lý ngữ cảnh, chi phí và phối hợp."]],"prompt":"Thiết kế trạng thái cho [quy trình]. Với mỗi trạng thái nêu dữ liệu được lưu, điều kiện chuyển và hành động tiếp theo. Giới hạn tối đa [số] lượt gọi và [thời gian]. Tách dữ liệu phiên khỏi dữ liệu dài hạn; nêu quyền truy cập, cập nhật và xóa. Nếu tác vụ được chạy lại, xác định cách tránh tạo kết quả ghi trùng.","body":"Cách thực hiện: 1. Liệt kê trạng thái: mới, đang làm, chờ dữ liệu, hoàn thành, lỗi. 2. Quy định dữ liệu cần giữ và thời hạn. 3. Thiết kế điều kiện dừng theo lượt, thời gian và kết quả. 4. Thử tiếp tục một tác vụ sau gián đoạn, tránh lặp hành động ghi.\n\nVì sao cách này hữu ích: Trạng thái và giới hạn làm cho quy trình có thể tiếp tục, kiểm tra và dừng có chủ đích.\n\nChuyển sang lĩnh vực khác: Bất kỳ tác vụ dài nào cũng cần trạng thái; chọn dữ liệu bộ nhớ theo nhu cầu và quyền thực tế.","activity":{"task":"Mở nguồn của phần này và làm thử: Tiếp tục sau mất kết nối. Dữ liệu: Quy trình đã tạo bản nháp báo cáo mã R17. Mất mạng trước khi nhận xác nhận. Lần chạy lại không biết tạo thành công hay chưa. Bước đầu: Mô tả trạng thái chưa chắc chắn.","hint":"Không coi timeout là chắc chắn hành động thất bại.","sample":"Kiểm tra trạng thái theo mã yêu cầu/R17 trước; nếu đã có, dùng lại kết quả. Nếu chưa thể biết, giữ trạng thái cần kiểm tra thay vì tạo vô hạn. Cơ chế idempotency phải được hệ thống hỗ trợ để bảo đảm."}},{"title":"Bộ nhớ agent: giữ điều cần, quên điều nên quên","points":[["Ba loại thông tin","Trạng thái phiên lưu bước đang làm; tóm tắt hội thoại giúp tiếp tục trong giới hạn ngữ cảnh; bộ nhớ dài hạn chứa điều cần dùng ở phiên sau. Mỗi loại có hạn dùng, nguồn và quyền khác nhau. Sách trình bày ví dụ bộ nhớ trong framework; tên API có thể đã đổi."],["Ghi nhớ chọn lọc","Đừng lưu mọi câu nói. Chỉ lưu dữ kiện được người dùng xác nhận hoặc có nguồn, hữu ích cho tác vụ tương lai, có mục đích và thời hạn rõ. Lưu trạng thái “chưa xác nhận” riêng. Trước khi dùng bộ nhớ, kiểm tra nó còn đúng hay không."],["Vòng đời và bảo vệ","Một mục nhớ cần ID, nội dung, nguồn, thời gian, phạm vi truy cập, cách sửa và xóa. Với dữ liệu nhạy cảm, cân nhắc không lưu. Agent phải biết khi nào quên hoặc hỏi lại, tránh đưa thông tin của người này vào câu trả lời cho người khác."]],"prompt":"Với thông tin [X], hãy đề xuất có nên lưu không. Ghi lý do, nguồn, mục đích, thời hạn, quyền truy cập và cách người dùng sửa/xóa. Không lưu suy đoán về người dùng như dữ kiện. Khi thông tin mới mâu thuẫn, hỏi xác nhận và giữ lịch sử thay đổi.","body":"Cách thực hiện: 1. Liệt kê thông tin cần trong một phiên và qua nhiều phiên. 2. Định nghĩa điều kiện ghi cùng quyền xác nhận. 3. Thiết kế bản ghi có nguồn, ngày, trạng thái và hạn dùng. 4. Thử ba tình huống: thông tin đổi, thông tin sai, người dùng yêu cầu xóa. 5. Kiểm tra câu trả lời không rò sang người khác.\n\nVì sao cách này hữu ích: Bộ nhớ trở thành dữ liệu có vòng đời và quyền, không phải lời hứa mơ hồ.\n\nChuyển sang lĩnh vực khác: Áp dụng cho trợ lý cá nhân, CRM, học tập, chăm sóc khách hàng; chỉ khác chính sách dữ liệu và thời hạn.","activity":{"task":"Mở nguồn của phần này và làm thử: Thiết kế 4 mục bộ nhớ. Dữ liệu: Người dùng nói: “Tôi học buổi tối”; “Tôi chắc chắn giỏi toán”; “Đừng nhớ địa chỉ nhà”; “Tháng tới đổi lịch sang sáng”. Bước đầu: Quyết định lưu/không lưu từng mục.","hint":"“Giỏi toán” là tự đánh giá, không phải điểm đo khách quan.","sample":"Có thể lưu sở thích lịch sau khi xác nhận và cập nhật khi đổi. Không lưu địa chỉ theo yêu cầu. Tự đánh giá năng lực nếu cần chỉ lưu là phát biểu của người dùng, không nâng thành chẩn đoán."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Bộ nhớ và truy hồi tài liệu dễ bị nhầm. Kho tài liệu lưu nguồn có thể tham khảo; bộ nhớ cá nhân lưu điều đã xảy ra hoặc sở thích được xác nhận. Một suy đoán như “người này yếu toán” không nên lưu thành sự thật chỉ từ một câu sai. Nếu thông tin mới mâu thuẫn với mục cũ, đánh dấu thay đổi và hỏi xác nhận; không tự chọn câu thuận tiện nhất.\n\nQuyền của công cụ và bộ nhớ phải đi cùng danh tính người dùng. Agent không được truy tài liệu riêng của người khác chỉ vì truy hồi thấy gần nghĩa. Với tác vụ nhạy cảm, có thể quyết định không lưu, dùng dữ liệu giả lập trong bài học và chuyển người khi quyền chưa rõ.","activity":{"task":"Tạo ba tình huống kiểm bộ nhớ: người dùng đổi mục tiêu, yêu cầu xóa, và câu nói có vẻ là suy đoán. Viết phản ứng đúng.","hint":"Phân biệt “ghi nhận người dùng nói” và “sự thật đã kiểm”.","sample":"Đổi lịch học: cập nhật sau xác nhận, giữ lịch sử thay đổi nếu được phép; yêu cầu xóa: xóa mục và các bản sao liên quan theo khả năng hệ thống."}}],"cases":[{"domain":"Thư viện","situation":"Agent hỗ trợ mượn sách","input":"Có hai công cụ giả lập: lookup_loan(book_id) và draft_extension(book_id,days). Công cụ thứ hai chỉ tạo bản nháp; không gia hạn thật.","steps":["Viết schema bằng lời cho hai công cụ.","Viết quy trình khi người dùng thiếu book_id.","Nêu câu trả lời cuối phản ánh đúng trạng thái bản nháp."],"result":"Hỏi mã sách nếu thiếu → tra khoản mượn → kiểm tra điều kiện trong chính sách được cung cấp → tạo bản nháp nếu phù hợp → báo cần duyệt. Không tự đặt chính sách số ngày nếu nguồn chưa có.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Tra hạn trả là đọc; gia hạn là ghi; chuyển yêu cầu đặc biệt cho thủ thư là bàn giao. Thiết kế công cụ theo thao tác và rủi ro, không theo một ngành cụ thể."},{"domain":"Hỗ trợ dự án","situation":"Thiết kế 4 mục bộ nhớ","input":"Người dùng nói: “Tôi học buổi tối”; “Tôi chắc chắn giỏi toán”; “Đừng nhớ địa chỉ nhà”; “Tháng tới đổi lịch sang sáng”.","steps":["Quyết định lưu/không lưu từng mục.","Gắn ngày và trạng thái.","Xử lý đổi lịch và yêu cầu không nhớ địa chỉ."],"result":"Có thể lưu sở thích lịch sau khi xác nhận và cập nhật khi đổi. Không lưu địa chỉ theo yêu cầu. Tự đánh giá năng lực nếu cần chỉ lưu là phát biểu của người dùng, không nâng thành chẩn đoán.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Nhớ quyết định phiên bản mới; đánh dấu bản cũ đã thay thế. Áp dụng cho trợ lý cá nhân, CRM, học tập, chăm sóc khách hàng; chỉ khác chính sách dữ liệu và thời hạn."}],"practice":{"basic":{"title":"Agent hỗ trợ mượn sách","task":"Có hai công cụ giả lập: lookup_loan(book_id) và draft_extension(book_id,days). Công cụ thứ hai chỉ tạo bản nháp; không gia hạn thật.","steps":["Viết schema bằng lời cho hai công cụ.","Viết quy trình khi người dùng thiếu book_id.","Nêu câu trả lời cuối phản ánh đúng trạng thái bản nháp."],"hint":"Tên draft_extension không cho phép nói đã gia hạn.","solution":"Hỏi mã sách nếu thiếu → tra khoản mượn → kiểm tra điều kiện trong chính sách được cung cấp → tạo bản nháp nếu phù hợp → báo cần duyệt. Không tự đặt chính sách số ngày nếu nguồn chưa có."},"applied":{"title":"Thiết kế 4 mục bộ nhớ","task":"Người dùng nói: “Tôi học buổi tối”; “Tôi chắc chắn giỏi toán”; “Đừng nhớ địa chỉ nhà”; “Tháng tới đổi lịch sang sáng”.","steps":["Quyết định lưu/không lưu từng mục.","Gắn ngày và trạng thái.","Xử lý đổi lịch và yêu cầu không nhớ địa chỉ."],"hint":"“Giỏi toán” là tự đánh giá, không phải điểm đo khách quan.","solution":"Có thể lưu sở thích lịch sau khi xác nhận và cập nhật khi đổi. Không lưu địa chỉ theo yêu cầu. Tự đánh giá năng lực nếu cần chỉ lưu là phát biểu của người dùng, không nâng thành chẩn đoán."},"rubric":["Công cụ có tham số và quyền.","Trạng thái phiên tách bộ nhớ dài hạn.","Bộ nhớ có nguồn, thời điểm và cách xóa.","Không lưu suy đoán như sự thật."]},"pitfalls":["Công cụ khác tên nhưng cùng mô tả mơ hồ.","Cho rằng prompt là cơ chế phân quyền.","Lưu mọi dữ liệu không có mục đích hoặc thời hạn.","Thử lại hành động ghi mà không kiểm tra đã thành công chưa.","Lưu bản tóm tắt sai rồi dùng lại như sự thật."]},{"number":19,"stage":4,"minutes":105,"title":"RAG: trả lời dựa trên tài liệu truy hồi","subtitle":"Embedding, metadata, truy vấn nhiều bước và dẫn nguồn đúng.","prerequisites":"Bài 10–11 và 18. Đã biết chia đoạn và quyền dữ liệu.","refs":[["agents-companion",10,10],["agents-companion",33,37],["prompt",65,65],["prompt-book",391,467],["agents-companion",67,68]],"objectives":["Vẽ luồng nạp tài liệu đến câu trả lời.","Chẩn đoán lỗi truy hồi và lỗi tổng hợp riêng.","Thiết kế câu trả lời biết nói “không đủ nguồn”."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Retrieval-Augmented Generation không “dạy” mô hình lại toàn bộ sách; hệ tìm những đoạn liên quan tại lúc trả lời và đặt chúng vào ngữ cảnh. Luồng gồm nạp tài liệu, làm sạch, chia đoạn, gắn metadata, tạo chỉ mục, truy hồi, có thể xếp hạng lại, rồi sinh câu trả lời có nguồn. Mỗi khâu có thể sai. Bảng bị tách khỏi tiêu đề làm mất đơn vị; bản cũ không có ngày có thể bị dùng nhầm; đoạn đúng được tìm nhưng mô hình lại suy quá dữ liệu.\n\nEmbedding biểu diễn đoạn văn và câu hỏi thành vector để tìm gần về nghĩa. Nó không phải thước đo sự thật. Từ khóa, bộ lọc metadata và quyền truy cập vẫn cần. Khi câu hỏi nhiều ý, agentic RAG có thể chia câu hỏi, tìm nhiều lượt và xác nhận phần còn thiếu; nhưng phải đặt giới hạn lượt và tránh tự diễn giải mâu thuẫn thành sự đồng ý.","activity":{"task":"Mở Agents Companion trang PDF 33–37 và sách Prompt Engineering for Generative AI trang PDF 391–467. Vẽ luồng RAG cho bộ tài liệu bạn chọn, ghi lỗi có thể xảy ra tại ba khâu.","hint":"Ít nhất một lỗi về quyền hoặc phiên bản.","sample":"Nạp bản cũ → chỉ mục sai ngày; truy hồi bỏ sót bảng → thiếu con số; tổng hợp thêm kết luận không có trong đoạn."}},{"title":"RAG: tìm đúng tài liệu trước khi trả lời","points":[["RAG là gì?","Retrieval-Augmented Generation là sinh câu trả lời có bổ sung thông tin được truy xuất. Quy trình thường gồm chuẩn bị nguồn → chia đoạn → tạo chỉ mục → tìm đoạn phù hợp → đưa vào ngữ cảnh → tạo câu trả lời có dẫn chứng. RAG không tự làm tài liệu đúng hoặc luôn tìm đủ mọi đoạn cần thiết."],["Chuẩn bị nguồn và metadata","Giữ tiêu đề, bảng, đơn vị và đoạn giải thích cùng nhau khi có thể. Metadata là thông tin kèm đoạn như tác giả, ngày, phiên bản, phòng ban và quyền truy cập. Embedding biểu diễn nội dung thành vector phục vụ tìm tương đồng; từ khóa vẫn hữu ích với mã và tên chính xác."],["Tìm kiếm, xếp hạng và grounding","Truy xuất lấy ứng viên, reranking xếp lại theo mức phù hợp. Grounding kiểm tra nhận định có được đoạn nguồn hỗ trợ không. Nếu không tìm được đúng đoạn, đổi prompt viết câu trả lời chưa chắc giải quyết được. Nguồn khuyến nghị cải thiện tìm kiếm trước khi thêm agent phức tạp."]],"prompt":"Từ các đoạn nguồn [đoạn có mã], trả lời [câu hỏi]. Gắn mỗi nhận định với mã đoạn hỗ trợ. Giữ nguyên điều kiện và thời điểm áp dụng. Nếu nguồn không đủ, nêu thông tin thiếu thay vì dùng kiến thức ngoài để lấp. Trước khi trả lời, liệt kê ngắn các đoạn thực sự liên quan.","body":"Cách thực hiện: 1. Chọn một bộ tài liệu nhỏ, loại bản trùng và ghi phiên bản. 2. Chia theo chủ đề, giữ điều kiện và bảng liên quan. 3. Đặt câu hỏi có đáp án biết trước, kiểm tra đoạn tìm được. 4. Chỉ tạo câu trả lời từ đoạn đủ bằng chứng; đánh dấu thiếu nguồn.\n\nVì sao cách này hữu ích: Các mã đoạn cho phép kiểm tra cả chất lượng truy xuất lẫn câu trả lời.\n\nChuyển sang lĩnh vực khác: Thay bộ nguồn và metadata theo ngành; giữ hai phép kiểm tra riêng: tìm đúng và trả lời đúng.","activity":{"task":"Mở nguồn của phần này và làm thử: RAG thủ công trên ba đoạn. Dữ liệu: D1: Phiên bản 2026, nhân viên nhóm A được mượn thiết bị tối đa 7 ngày. D2: Nhóm B tối đa 3 ngày. D3: Gia hạn cần người quản lý duyệt. Câu hỏi: nhóm B mượn 5 ngày có tự động được không? Bước đầu: Chọn đoạn cần thiết trước khi trả lời.","hint":"Cần kết hợp thời hạn nhóm B và quy tắc gia hạn.","sample":"Theo D2, thời hạn thông thường của B là 3 ngày; theo D3, gia hạn cần duyệt. Không thể nói tự động được 5 ngày. Nguồn chưa nêu cách gửi yêu cầu hoặc tiêu chí chấp thuận."}},{"title":"Agentic RAG: tìm kiếm nhiều bước có điều kiện","points":[["Điểm khác với RAG cố định","Agentic RAG cho phép hệ thống quyết định truy vấn tiếp, chia câu hỏi, chọn nguồn và kiểm tra kết quả. Ví dụ hỏi so chính sách giữa hai địa điểm cần đọc từng nguồn rồi đối chiếu. Phức tạp hơn đồng nghĩa cần giới hạn lượt, thời gian và cách đánh giá."],["Vòng tìm kiếm có lý do","Mỗi truy vấn mới phải giải quyết khoảng trống cụ thể: thiếu định nghĩa, sai phiên bản hoặc thiếu ngoại lệ. Mở rộng từ đồng nghĩa khác với nới điều kiện bắt buộc. Không tìm thấy món thuần chay thì không được tự thay bằng món chay có sữa rồi nói đã thỏa yêu cầu."],["Kiểm tra nguồn trước tổng hợp","Đánh giá độ mới, quyền truy cập, mức liên quan và mâu thuẫn. Dừng khi đủ bằng chứng hoặc hết ngân sách; báo câu chưa trả lời được. Thêm agent không khắc phục nguồn lỗi hoặc chỉ mục kém."]],"prompt":"Tìm câu trả lời cho [câu hỏi] trong [nguồn]. Ràng buộc bắt buộc: [điều kiện]. Tối đa 3 vòng tìm. Sau mỗi vòng, ghi bằng chứng có được và khoảng trống cần giải quyết. Có thể đổi từ khóa hoặc nguồn phù hợp, nhưng giữ ràng buộc bắt buộc. Nếu chưa tìm đủ, trình bày kết quả một phần và phần chưa xác minh.","body":"Cách thực hiện: 1. Chia câu hỏi thành các thông tin cần xác nhận. 2. Truy xuất lượt đầu và đánh dấu khoảng trống. 3. Viết truy vấn tiếp theo gắn với từng khoảng trống. 4. Tổng hợp nguồn đã xác minh và ghi điều còn thiếu.\n\nVì sao cách này hữu ích: Mỗi vòng được dẫn dắt bởi thiếu hụt bằng chứng, tránh tìm kiếm lan man hoặc tự đổi mục tiêu.\n\nChuyển sang lĩnh vực khác: Tách “điều kiện phải có” khỏi “mong muốn” trước khi tìm sản phẩm, tài liệu, lịch trình hoặc giải pháp.","activity":{"task":"Mở nguồn của phần này và làm thử: Giữ ràng buộc khi truy xuất. Dữ liệu: Cần phòng 20 người có lối tiếp cận xe lăn. Kết quả đầu: A chứa 30 người, chưa rõ lối tiếp cận; B chứa 15 người, có lối tiếp cận. Chưa có kết quả khác. Bước đầu: Nêu vì sao chưa lựa chọn được.","hint":"Sức chứa và lối tiếp cận đều là điều kiện bắt buộc.","sample":"B không đủ sức chứa; A cần xác minh lối tiếp cận. Có thể tìm thông tin chính thức về A hoặc phòng khác thỏa cả hai. Không nói A phù hợp khi chưa có bằng chứng."}},{"title":"Embedding, kho vector & truy hồi kết hợp","points":[["Embedding và kho vector","Embedding biểu diễn văn bản thành vector để tìm đoạn gần về nghĩa. Nó hữu ích khi câu hỏi và văn bản dùng từ khác nhau, nhưng độ gần không bảo đảm đúng sự kiện. Kho vector lưu vector, đoạn gốc và metadata như nguồn, trang, ngày, quyền truy cập."],["Truy hồi có bộ lọc","Từ khóa tốt cho mã định danh/tên riêng; vector tốt cho diễn đạt tương tự; metadata lọc thời gian, loại tài liệu và quyền. Có thể kết hợp rồi rerank. Self-query là cách chuyển ràng buộc trong câu hỏi thành bộ lọc có cấu trúc; phải xác nhận bộ lọc không loại nhầm nguồn."],["Đánh giá hai tầng","Tầng truy hồi: tài liệu đúng có nằm trong top-k không, quyền có đúng không. Tầng trả lời: câu trả lời có bám đoạn tìm được và dẫn đúng trang không. Nếu truy hồi thiếu, sửa chia đoạn, metadata hoặc câu hỏi; nếu truy hồi đúng mà trả lời sai, sửa bước tổng hợp."]],"prompt":"Với câu hỏi [Q], truy hồi tối đa [k] đoạn theo nghĩa và từ khóa; lọc metadata [ngày/quyền]. Trả ID, trang, lý do liên quan và mức chưa chắc. Nếu các đoạn chưa đủ, nói thiếu bằng chứng trước khi tạo câu trả lời.","body":"Cách thực hiện: 1. Chọn 10 câu hỏi cùng vị trí đáp án trong nguồn. 2. Tạo bản ghi đoạn có ID, trang và quyền. 3. Thử từ khóa, vector và bộ lọc trên cùng câu hỏi. 4. Ghi top-k, câu bỏ sót và nguyên nhân. 5. Chỉ sau đó đánh giá câu trả lời có nguồn.\n\nVì sao cách này hữu ích: Prompt tách truy hồi khỏi tổng hợp, để kiểm tra đoạn nguồn trước.\n\nChuyển sang lĩnh vực khác: Cách này dùng cho chính sách nội bộ, giáo trình, hỗ trợ khách hàng và nghiên cứu; metadata thay theo nhiệm vụ.","activity":{"task":"Mở nguồn của phần này và làm thử: Chọn chiến lược truy hồi. Dữ liệu: Sáu đoạn tài liệu giả định: hai về “nghỉ phép”, hai về “paid time off”, một bản đã hết hạn, một tài liệu riêng tư. Bước đầu: Thiết kế metadata cho từng đoạn.","hint":"Đoạn gần về nghĩa nhưng hết hạn không được ưu tiên hơn bản hiện hành.","sample":"Kết quả tốt có thể dùng từ đồng nghĩa để tăng recall, nhưng phải lọc ngày và quyền trước khi trả lời. Với câu không còn nguồn hiện hành, báo thiếu thay vì dùng bản cũ."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Một bộ thử RAG cần câu hỏi có đáp án ở nguồn, câu hỏi không có đáp án và câu hỏi có nhiều tài liệu mâu thuẫn. Đo retrieval recall: đoạn cần có vào top-k không. Sau đó đo grounding: câu trả lời có được đoạn đó hỗ trợ không. Nên kiểm liên kết trang hoặc đoạn cụ thể, không chỉ tên file. Nếu không tìm được, có thể hỏi thêm nguồn, mở rộng truy vấn có kiểm soát hoặc nói rõ chưa đủ.\n\nKhi dùng tài liệu riêng, lọc quyền trước khi đưa đoạn vào ngữ cảnh. Không thể sửa rò rỉ bằng cách thêm câu “đừng tiết lộ” sau khi hệ đã trao đoạn sai quyền cho mô hình. Kiểm an toàn ở kiến trúc dữ liệu, truy hồi và hành động, không chỉ ở văn bản prompt.","activity":{"task":"Tạo bốn câu hỏi thử cho bộ tài liệu: một rõ, một dùng đồng nghĩa, một thiếu đáp án, một đụng bản cũ/mới. Ghi kết quả mong đợi.","hint":"Ca thiếu đáp án không được chấm là sai nếu hệ trả “chưa đủ”.","sample":"Hỏi chính sách hiện hành nhưng chỉ tìm bản 2023 đã hết hạn → hệ phải báo chưa có nguồn hiện hành hoặc tìm tiếp theo quyền."}}],"cases":[{"domain":"Nhân sự","situation":"RAG thủ công trên ba đoạn","input":"D1: Phiên bản 2026, nhân viên nhóm A được mượn thiết bị tối đa 7 ngày. D2: Nhóm B tối đa 3 ngày. D3: Gia hạn cần người quản lý duyệt. Câu hỏi: nhóm B mượn 5 ngày có tự động được không?","steps":["Chọn đoạn cần thiết trước khi trả lời.","Viết câu trả lời có mã nguồn.","Nêu điều chưa biết về quy trình duyệt."],"result":"Theo D2, thời hạn thông thường của B là 3 ngày; theo D3, gia hạn cần duyệt. Không thể nói tự động được 5 ngày. Nguồn chưa nêu cách gửi yêu cầu hoặc tiêu chí chấp thuận.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Tra chính sách nghỉ theo đúng địa điểm, phiên bản và nhóm nhân viên được áp dụng. Thay bộ nguồn và metadata theo ngành; giữ hai phép kiểm tra riêng: tìm đúng và trả lời đúng."},{"domain":"Học thuật","situation":"Chọn chiến lược truy hồi","input":"Sáu đoạn tài liệu giả định: hai về “nghỉ phép”, hai về “paid time off”, một bản đã hết hạn, một tài liệu riêng tư.","steps":["Thiết kế metadata cho từng đoạn.","Viết ba câu hỏi dùng từ khác nhau.","Mô phỏng kết quả từ khóa và theo nghĩa.","Xác định điều kiện loại bản cũ và tài liệu không có quyền."],"result":"Kết quả tốt có thể dùng từ đồng nghĩa để tăng recall, nhưng phải lọc ngày và quyền trước khi trả lời. Với câu không còn nguồn hiện hành, báo thiếu thay vì dùng bản cũ.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Tìm đoạn giải thích cùng khái niệm dù người hỏi dùng từ đồng nghĩa. Cách này dùng cho chính sách nội bộ, giáo trình, hỗ trợ khách hàng và nghiên cứu; metadata thay theo nhiệm vụ."}],"practice":{"basic":{"title":"RAG thủ công trên ba đoạn","task":"D1: Phiên bản 2026, nhân viên nhóm A được mượn thiết bị tối đa 7 ngày. D2: Nhóm B tối đa 3 ngày. D3: Gia hạn cần người quản lý duyệt. Câu hỏi: nhóm B mượn 5 ngày có tự động được không?","steps":["Chọn đoạn cần thiết trước khi trả lời.","Viết câu trả lời có mã nguồn.","Nêu điều chưa biết về quy trình duyệt."],"hint":"Cần kết hợp thời hạn nhóm B và quy tắc gia hạn.","solution":"Theo D2, thời hạn thông thường của B là 3 ngày; theo D3, gia hạn cần duyệt. Không thể nói tự động được 5 ngày. Nguồn chưa nêu cách gửi yêu cầu hoặc tiêu chí chấp thuận."},"applied":{"title":"Chọn chiến lược truy hồi","task":"Sáu đoạn tài liệu giả định: hai về “nghỉ phép”, hai về “paid time off”, một bản đã hết hạn, một tài liệu riêng tư.","steps":["Thiết kế metadata cho từng đoạn.","Viết ba câu hỏi dùng từ khác nhau.","Mô phỏng kết quả từ khóa và theo nghĩa.","Xác định điều kiện loại bản cũ và tài liệu không có quyền."],"hint":"Đoạn gần về nghĩa nhưng hết hạn không được ưu tiên hơn bản hiện hành.","solution":"Kết quả tốt có thể dùng từ đồng nghĩa để tăng recall, nhưng phải lọc ngày và quyền trước khi trả lời. Với câu không còn nguồn hiện hành, báo thiếu thay vì dùng bản cũ."},"rubric":["Luồng RAG đủ các khâu.","Có kiểm ngày/phiên bản/quyền.","Đo retrieval và grounding riêng.","Biết dừng khi nguồn không đủ."]},"pitfalls":["Chia đoạn làm mất điều kiện đi kèm.","Truy xuất tài liệu người dùng không có quyền đọc.","Nới điều kiện mà không nói với người dùng.","Thêm nhiều lượt tìm không có thông tin mới.","Nhầm điểm tương đồng với độ đúng."]},{"number":20,"stage":4,"minutes":120,"title":"Nhiều agent và hợp đồng giao việc","subtitle":"Điều phối, phân nhiệm, tổng hợp và tránh chi phí phối hợp vô ích.","prerequisites":"Bài 17–19. Có một agent đơn với trace.","refs":[["agents-guide",13,23],["agents-companion",23,33],["agents-companion",54,69],["agents-companion",46,53]],"objectives":["So manager, handoff và các kiểu phối hợp.","Viết hợp đồng nhiệm vụ con có nghiệm thu.","Đánh giá hệ nhiều agent so với một agent."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Nhiều agent không đồng nghĩa nhiều trí tuệ hơn. Mỗi agent có thể chuyên một việc, nhưng hệ phải truyền bối cảnh, xử lý trùng lặp và giải quyết mâu thuẫn. Tài liệu OpenAI nêu mô hình manager dùng agent như công cụ và mô hình handoff chuyển quyền điều khiển; Agents Companion mô tả tuần tự, phân cấp, cộng tác, cạnh tranh và nhiều mẫu khác. Chọn cấu trúc theo phụ thuộc công việc: việc độc lập có thể chạy song song; việc phụ thuộc cần thứ tự; việc tranh luận cần tiêu chí phân xử.\n\nMột nhiệm vụ con phải có mục tiêu, đầu vào, nguồn, giới hạn thời gian/quyền, sản phẩm và tiêu chí nghiệm thu. Nếu giao “tìm mọi thứ hữu ích”, agent con có thể tốn ngân sách và tạo kết quả khó hợp nhất. Giới hạn của nhiệm vụ cha phải truyền xuống; không để mỗi nhánh tự quyết định mở rộng phạm vi.","activity":{"task":"Mở Agents Companion trang PDF 23–33 và 46–53. Vẽ một sơ đồ hai agent cho việc nghiên cứu rồi viết, có người điều phối và bước kiểm.","hint":"Nêu ai xử lý mâu thuẫn giữa hai kết quả.","sample":"Agent A trích nguồn, B viết dàn ý từ bảng nguồn; manager kiểm nguồn trước khi cho B tiếp tục."}},{"title":"Kiến trúc nhiều agent & lựa chọn phối hợp","points":[["Các mẫu phổ biến","Sequential chuyển kết quả lần lượt. Hierarchical/manager có một bộ điều phối gọi agent như công cụ và tổng hợp. Handoff chuyển quyền xử lý cho agent khác. Collaborative ghép chuyên môn bổ sung; competitive so các phương án cạnh tranh. Cần chọn theo phụ thuộc và quyền điều khiển thật."],["Bàn giao là hợp đồng","Một bàn giao nên có mục tiêu, dữ kiện đã xác nhận, đầu ra, nguồn, việc chưa làm và giới hạn. Không gửi toàn bộ lịch sử vô chọn lọc. Có thể dùng graph khai báo trước hoặc luồng điều khiển bằng mã; quan trọng là trạng thái và điểm chuyển dễ kiểm tra."],["Khi nào nên tách","Nguồn khuyên khai thác một agent trước. Tách khi logic quá nhiều nhánh hoặc công cụ chồng lấn làm giảm chất lượng dù đã làm rõ mô tả. Nhiều agent có thể tăng chi phí, độ trễ và lỗi phối hợp; không mặc định làm giảm hallucination."]],"prompt":"Cho nhiệm vụ [việc], so thiết kế một agent với hai phương án nhiều agent. Mỗi phương án nêu vai trò, quyền điều khiển, hợp đồng bàn giao, bước song song/tuần tự, điều kiện lỗi và chi phí dự kiến. Chỉ khuyến nghị tách nếu có lợi ích kiểm chứng được bằng [bộ thử].","body":"Cách thực hiện: 1. Mô tả thiết kế một agent trước. 2. Chỉ ra vấn đề đo được mà việc tách có thể giải quyết. 3. Chọn mẫu phối hợp và hợp đồng bàn giao. 4. So cả hệ với bản đơn trên cùng tập thử.\n\nVì sao cách này hữu ích: Kiến trúc được đánh giá bằng nhiệm vụ và phép đo, không bằng số lượng vai trò.\n\nChuyển sang lĩnh vực khác: Phối hợp cần dựa vào phụ thuộc và chuyên môn, giống cách chia việc cho đội người.","activity":{"task":"Mở nguồn của phần này và làm thử: Thiết kế báo cáo thị trường. Dữ liệu: Ba việc: thu nguồn, kiểm tra số liệu, viết báo cáo. Có hai nhóm nguồn độc lập nhưng bản viết phải dùng số đã kiểm tra. Bước đầu: Chọn bước có thể song song.","hint":"Hai nhóm thu nguồn có thể song song; kiểm tra và viết có điều kiện phụ thuộc.","sample":"Manager có thể giao hai nhánh thu nguồn, ghép bảng bằng chứng, kiểm tra rồi giao viết. Gói bàn giao chứa số đã xác nhận, nguồn, phạm vi và điểm chưa chắc. Không chỉ gửi một đoạn tóm tắt mất dẫn chứng."}},{"title":"Mẫu phối hợp nâng cao qua tình huống thực tế","points":[["Các vai chuyên biệt","Ví dụ automotive trong tài liệu có điều hướng, tìm media, soạn tin, tra hướng dẫn xe và kiến thức chung. Giá trị học nằm ở việc tách năng lực và quyền, không phải sao chép thông tin địa điểm hoặc thao tác xe trong ví dụ thành chỉ dẫn hiện tại."],["Các mẫu nâng cao","Diamond đưa kết quả chuyên môn qua lớp kiểm tra/diễn đạt trước khi trả. Peer-to-peer cho chuyển lại khi định tuyến nhầm. Response mixer ghép phần bổ sung nhưng phải giải quyết mâu thuẫn theo bằng chứng. Adaptive loop cải tiến qua số vòng giới hạn; không tự nới điều kiện bắt buộc."],["Edge/cloud và khả năng phục hồi","Nguồn minh họa việc đặt chức năng cần phản hồi nhanh ở thiết bị và truy vấn nặng trên cloud. Bài học tổng quát là phân nhóm theo độ trễ, kết nối và tác động, rồi thiết kế hành vi khi một thành phần không có. Không được biến thiếu dữ liệu thành đảm bảo an toàn hoặc suy đoán chắc chắn."]],"prompt":"Thiết kế bộ tổng hợp cho các kết quả [kết quả có nguồn]. Giữ phần có bằng chứng, đánh dấu mâu thuẫn và thông tin thiếu. Khi đổi giọng văn, giữ nguyên số, điều kiện và mức độ chắc chắn. Nêu cách chuyển tác vụ khi định tuyến sai và hành vi giảm cấp nếu một nguồn không truy cập được.","body":"Cách thực hiện: 1. Liệt kê năng lực và ranh giới từng vai. 2. Chọn đường trả lời khi định tuyến đúng/sai. 3. Thiết kế kiểm tra trước và sau đổi giọng văn. 4. Mô phỏng mất một nguồn hoặc mất kết nối.\n\nVì sao cách này hữu ích: Tổng hợp cần bảo toàn nghĩa và trạng thái xác minh, không chỉ làm văn bản mượt hơn.\n\nChuyển sang lĩnh vực khác: Các mẫu automotive chuyển được sang sự kiện, thiết bị, dịch vụ hoặc nghiên cứu bằng cách thay vai và công cụ.","activity":{"task":"Mở nguồn của phần này và làm thử: Ghép hai kết quả mâu thuẫn. Dữ liệu: Agent lịch: “Phòng A còn trống thứ Sáu, nguồn cập nhật hôm qua.” Agent địa điểm: “Phòng A đang bảo trì thứ Sáu, thông báo sáng nay.” Bước đầu: Nêu mâu thuẫn thay vì ghép cả hai thành kế hoạch chắc chắn.","hint":"Nguồn mới hơn đáng xem xét nhưng vẫn cần kiểm tra phạm vi và tính chính thức.","sample":"Chưa nên xác nhận phòng A. Kiểm tra thông báo bảo trì có áp dụng đúng phòng/ngày và liên hệ hệ thống lịch chính thức. Câu trả lời phải báo mâu thuẫn cùng bước xác minh, không tự tuyên bố phòng sẵn sàng."}},{"title":"Giao việc bằng hợp đồng nhiệm vụ","points":[["Contract trong tài liệu","Nguồn đề xuất “contract-adhering agents”: mô tả công việc như một thỏa thuận có sản phẩm, đặc tả, phạm vi, chi phí, thời gian, nguồn và nhịp phản hồi. Đây là hợp đồng kỹ thuật của tác vụ, không tự là hợp đồng pháp lý hay lời bảo đảm hoàn thành."],["Vòng đời","Khởi tạo → rà thiếu/mâu thuẫn → làm rõ hoặc thương lượng → thực hiện → kiểm tra sản phẩm → phản hồi và sửa. Khi phát hiện mục tiêu không thể đạt trong nguồn lực, cần nêu lựa chọn thay đổi phạm vi, thời gian hoặc chất lượng thay vì tự đổi một yếu tố."],["Nhiệm vụ con và ngân sách chung","Subcontract chia việc nhưng giữ tiêu chí, nguồn và giới hạn từ nhiệm vụ cha. Cần chủ thể tổng hợp, theo dõi phụ thuộc và dừng nhánh không còn cần. Ví dụ co-scientist trong nguồn minh họa tạo–đánh giá–cải tiến giả thuyết; giả thuyết được tạo chưa phải kết quả thực nghiệm đã chứng minh."]],"prompt":"HỢP ĐỒNG NHIỆM VỤ\nMục tiêu: [mục tiêu]. Sản phẩm: [danh sách]. Nghiệm thu: [tiêu chí kiểm tra].\nTrong phạm vi: [việc]. Ngoài phạm vi: [việc]. Nguồn: [nguồn]. Ngân sách/thời gian: [giới hạn].\nCập nhật khi: [mốc]. Trước thực hiện, chỉ ra yêu cầu thiếu hoặc mâu thuẫn. Nếu chia nhiệm vụ con, truyền cùng giới hạn và nêu cách hợp nhất kết quả. Báo phần chưa đạt thay vì tự thay tiêu chí.","body":"Cách thực hiện: 1. Viết sản phẩm có cách kiểm tra. 2. Nêu phạm vi trong/ngoài cùng nguồn được dùng. 3. Đặt giới hạn thời gian, chi phí và nhịp cập nhật. 4. Rà mâu thuẫn rồi phân việc con có điều kiện nghiệm thu.\n\nVì sao cách này hữu ích: Nhiệm vụ có điểm kết thúc và cơ chế xử lý bất định, giúp người giao việc giữ quyền quyết định.\n\nChuyển sang lĩnh vực khác: Khung dùng được cho agent, cộng tác viên hoặc chính kế hoạch học của bạn.","activity":{"task":"Mở nguồn của phần này và làm thử: Hợp đồng cho báo cáo ngắn. Dữ liệu: Cần báo cáo 2 trang so ba phương án từ 4 tài liệu cung cấp, trong 90 phút. Không tìm web. Một phương án chưa có dữ liệu chi phí. Bước đầu: Viết tiêu chí nghiệm thu.","hint":"Không thể yêu cầu bảng chi phí đầy đủ bằng cách tự bịa nguồn.","sample":"Nghiệm thu nên yêu cầu đủ ba phương án, cùng tiêu chí, dẫn nguồn và ô thiếu ghi rõ. Dành thời gian kiểm tra/hợp nhất trong 90 phút; không phân ba nhiệm vụ 90 phút rồi quên tổng nguồn lực."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Đánh giá hệ nhiều agent bằng kết quả cuối, số lần dùng công cụ, chi phí, thời gian và lỗi phối hợp. Nếu một agent đơn làm tương đương, hệ nhiều agent chưa chứng minh giá trị. Những ca cần lưu ý gồm hai agent cùng tìm nguồn rồi đưa bản khác nhau, agent con vượt quyền, hoặc manager tóm tắt làm rơi ngoại lệ. Trace từng nhánh và điểm hợp nhất là điều kiện để chẩn đoán.\n\n“Hợp đồng” trong tài liệu là cách mô tả nhiệm vụ kỹ thuật, không tự là hợp đồng pháp lý. Khi yêu cầu thiếu hoặc mâu thuẫn, agent nên trả lại câu hỏi hoặc đề xuất thay đổi phạm vi để người giao quyết; không lặng lẽ giảm tiêu chuẩn nghiệm thu.","activity":{"task":"Viết hợp đồng cho hai nhiệm vụ con và một bước hợp nhất. Thử tình huống hai nhánh đưa số liệu khác nhau.","hint":"Cần quay về nguồn và nêu mâu thuẫn thay vì lấy trung bình tùy tiện.","sample":"Hai báo cáo có số khác kỳ: manager kiểm ngày, định nghĩa và trang; nếu chưa giải quyết, đánh dấu bất đồng trong kết quả."}}],"cases":[{"domain":"Nội dung","situation":"Thiết kế báo cáo thị trường","input":"Ba việc: thu nguồn, kiểm tra số liệu, viết báo cáo. Có hai nhóm nguồn độc lập nhưng bản viết phải dùng số đã kiểm tra.","steps":["Chọn bước có thể song song.","Thiết kế manager hoặc sequential phù hợp.","Viết gói bàn giao cho người viết."],"result":"Manager có thể giao hai nhánh thu nguồn, ghép bảng bằng chứng, kiểm tra rồi giao viết. Gói bàn giao chứa số đã xác nhận, nguồn, phạm vi và điểm chưa chắc. Không chỉ gửi một đoạn tóm tắt mất dẫn chứng.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Nghiên cứu → kiểm chứng → viết là chuỗi có phụ thuộc, không nên viết trước khi có dữ kiện. Phối hợp cần dựa vào phụ thuộc và chuyên môn, giống cách chia việc cho đội người."},{"domain":"Thiết kế","situation":"Hợp đồng cho báo cáo ngắn","input":"Cần báo cáo 2 trang so ba phương án từ 4 tài liệu cung cấp, trong 90 phút. Không tìm web. Một phương án chưa có dữ liệu chi phí.","steps":["Viết tiêu chí nghiệm thu.","Nêu cách xử lý ô chi phí thiếu.","Chia ba nhiệm vụ con với tổng thời gian phù hợp."],"result":"Nghiệm thu nên yêu cầu đủ ba phương án, cùng tiêu chí, dẫn nguồn và ô thiếu ghi rõ. Dành thời gian kiểm tra/hợp nhất trong 90 phút; không phân ba nhiệm vụ 90 phút rồi quên tổng nguồn lực.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Ba phương án bố cục theo kích thước, đối tượng và tiêu chí đọc; không tự xuất bản. Khung dùng được cho agent, cộng tác viên hoặc chính kế hoạch học của bạn."}],"practice":{"basic":{"title":"Thiết kế báo cáo thị trường","task":"Ba việc: thu nguồn, kiểm tra số liệu, viết báo cáo. Có hai nhóm nguồn độc lập nhưng bản viết phải dùng số đã kiểm tra.","steps":["Chọn bước có thể song song.","Thiết kế manager hoặc sequential phù hợp.","Viết gói bàn giao cho người viết."],"hint":"Hai nhóm thu nguồn có thể song song; kiểm tra và viết có điều kiện phụ thuộc.","solution":"Manager có thể giao hai nhánh thu nguồn, ghép bảng bằng chứng, kiểm tra rồi giao viết. Gói bàn giao chứa số đã xác nhận, nguồn, phạm vi và điểm chưa chắc. Không chỉ gửi một đoạn tóm tắt mất dẫn chứng."},"applied":{"title":"Hợp đồng cho báo cáo ngắn","task":"Cần báo cáo 2 trang so ba phương án từ 4 tài liệu cung cấp, trong 90 phút. Không tìm web. Một phương án chưa có dữ liệu chi phí.","steps":["Viết tiêu chí nghiệm thu.","Nêu cách xử lý ô chi phí thiếu.","Chia ba nhiệm vụ con với tổng thời gian phù hợp."],"hint":"Không thể yêu cầu bảng chi phí đầy đủ bằng cách tự bịa nguồn.","solution":"Nghiệm thu nên yêu cầu đủ ba phương án, cùng tiêu chí, dẫn nguồn và ô thiếu ghi rõ. Dành thời gian kiểm tra/hợp nhất trong 90 phút; không phân ba nhiệm vụ 90 phút rồi quên tổng nguồn lực."},"rubric":["Có lý do dùng nhiều agent.","Hợp đồng con có nghiệm thu và giới hạn.","Có điểm hợp nhất và xử lý mâu thuẫn.","So được với baseline một agent."]},"pitfalls":["Song song các bước phụ thuộc dữ liệu.","Mất nguồn hoặc giới hạn khi bàn giao.","Lấy điểm tự tin tự khai làm bằng chứng đúng.","Biến “chưa xác nhận” thành “đã đảm bảo” khi viết lại.","Sản phẩm “chất lượng cao” không có tiêu chí."]},{"number":21,"stage":5,"minutes":105,"title":"Guardrails, quyền dữ liệu và thiên lệch","subtitle":"Nhiều lớp kiểm soát trước, trong và sau khi AI hành động.","prerequisites":"Bài 17–20. Biết đường dữ liệu và công cụ.","refs":[["agents-guide",24,31],["agents-companion",10,10],["enterprise",23,23],["ai-classroom",248,287]],"objectives":["Đặt kiểm soát theo mức hậu quả.","Bảo vệ quyền dữ liệu ở nguồn và công cụ.","Rà thiên lệch mà không tin một câu lệnh chung chung."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Guardrails là các lớp kiểm soát nhằm giảm rủi ro, không phải lời cam kết mô hình không bao giờ sai. Lớp đầu vào kiểm dữ liệu và quyền: có được đưa hồ sơ này vào hệ thống không, người dùng có quyền hỏi không. Lớp công cụ kiểm tham số và hành động: lệnh đọc khác lệnh xóa hay gửi. Lớp đầu ra kiểm nguồn, thông tin cá nhân, nội dung gây hại và điều cần người duyệt. Một prompt “hãy an toàn” chỉ là một lớp yếu nếu ứng dụng đã cấp quyền quá rộng.\n\nQuyền riêng tư cần xem mục đích, loại dữ liệu, người truy cập, thời hạn giữ và cách sửa/xóa. Thông tin trong sách phản ánh thời điểm xuất bản, không thay cho chính sách hiện hành của tổ chức hoặc quy định pháp luật. Khi học, dùng dữ liệu giả định hoặc đã ẩn danh để không tạo rủi ro không cần thiết.","activity":{"task":"Mở A Practical Guide to Building Agents trang PDF 24–31 và The AI Classroom trang PDF 248–287. Vẽ ba lớp kiểm soát cho một quy trình dùng tài liệu học viên hoặc khách hàng.","hint":"Quyền truy cập phải được kiểm trước truy hồi.","sample":"Đầu vào ẩn danh và xác nhận quyền → công cụ chỉ đọc đúng phạm vi → đầu ra không lộ dữ liệu, người duyệt quyết định gửi."}},{"title":"Guardrails, quyền hạn & chuyển người xử lý","points":[["Các lớp guardrail","Nguồn nêu kiểm tra phạm vi, nội dung không phù hợp, thông tin nhận dạng cá nhân, quy tắc xác định, xác thực đầu ra và bảo vệ công cụ. Guardrail là kiểm soát giảm rủi ro; một mô hình kiểm duyệt không thay xác thực, phân quyền hoặc kiểm tra dữ liệu phía ứng dụng."],["Rủi ro theo hành động","Đọc một tài liệu khác gửi email hoặc thanh toán. Xem quyền đọc/ghi, khả năng đảo ngược, phạm vi tài khoản và hậu quả. Với hành động không thể đảo ngược, kiểm tra phải xảy ra trước tác động; không trông chờ kiểm tra chạy song song rồi sửa sau."],["Con người và trải nghiệm","Chuyển người khi vượt số lần thất bại, thiếu quyền hoặc hành động có tác động cao theo chính sách thật. Gói chuyển cần mục tiêu, dữ kiện xác nhận, bước đã làm và vấn đề còn lại. Kiểm soát quá nhiều cũng gây cản trở; điều chỉnh theo lỗi thực tế và quyền đã được cấp."]],"prompt":"Rà quy trình [quy trình] theo dữ liệu, quyền và tác động. Với mỗi công cụ, ghi đọc/ghi, khả năng đảo ngược, điều kiện được phép và kiểm tra trước khi gọi. Xác định ngưỡng lỗi cần chuyển người, thông tin bàn giao và hành vi khi thiếu quyền. Phân biệt kiểm soát có trong mã/hệ thống với lời nhắc trong prompt.","body":"Cách thực hiện: 1. Liệt kê dữ liệu và hành động của quy trình. 2. Phân loại tác động và quyền tối thiểu. 3. Đặt kiểm tra ở đúng điểm trước tác động. 4. Thử thiếu quyền, nguồn chứa chỉ dẫn lạ và lỗi lặp.\n\nVì sao cách này hữu ích: Prompt buộc thiết kế kiểm soát cụ thể thay vì một khẩu hiệu.\n\nChuyển sang lĩnh vực khác: Mọi ngành đều có hành động cần giới hạn; ngưỡng phải theo tác động thực và chính sách nơi dùng.","activity":{"task":"Mở nguồn của phần này và làm thử: Bảo vệ quy trình gửi bản tin. Dữ liệu: Hệ thống có quyền đọc ghi chú và tạo bản nháp. Chưa có quyền gửi. Người dùng chỉ yêu cầu “chuẩn bị bản tin”. Bước đầu: Phân loại hành động.","hint":"“Chuẩn bị” không tự cấp quyền gửi tới người khác.","sample":"Đọc nguồn và tạo bản nháp là trong phạm vi. Dừng ở bản nháp, báo chưa gửi. Khả năng gửi cần công cụ, quyền và yêu cầu rõ về người nhận/nội dung; kiểm tra trước gửi."}},{"title":"Thiên lệch, quyền riêng tư & góc nhìn đa dạng","points":[["Thiên lệch trong nội dung","Hình ảnh và văn bản có thể lặp khuôn mẫu từ dữ liệu huấn luyện. Kiểm người/vai trò nào xuất hiện hoặc bị bỏ sót, ngôn ngữ nào được ưu ái và nguồn nào được coi là mặc định. Tăng đa dạng bằng tiêu chí rõ, rồi vẫn kiểm bằng người và tài liệu gốc."],["Quyền riêng tư","Trước khi đưa bài làm, thông tin học viên hoặc dữ liệu tổ chức vào AI, cần biết loại dữ liệu nào thu, lưu bao lâu, ai truy cập, mục đích xử lý, cách xóa và phương án thay thế. Điều kiện cụ thể phụ thuộc công cụ và quy định của tổ chức; không suy từ sách thành luật hiện hành."],["Bong bóng cá nhân hóa","Nếu chỉ luôn cho người học nội dung họ thích hoặc đã biết, họ có thể ít gặp góc nhìn khác. Chèn câu hỏi đối lập, nguồn khác đáng tin và bài chuyển giao mới, đồng thời tránh gây quá tải."]],"prompt":"Hãy rà đầu ra [X] theo ba lớp: dữ kiện có nguồn; nhóm/góc nhìn có thể bị bỏ sót; dữ liệu cá nhân không cần thiết. Đề xuất bản sửa với cùng mục tiêu. Chỉ dùng dữ liệu đã được phép; nếu quyền chưa rõ, dừng và hỏi.","body":"Cách thực hiện: 1. Chọn một đầu ra và liệt kê ai/vấn đề bị thiếu. 2. Đối chiếu 2 nguồn độc lập cho kết luận quan trọng. 3. Ẩn danh hoặc bỏ dữ liệu không cần trước khi thử công cụ. 4. Đặt câu hỏi về lưu trữ/quyền/xóa cho nhà cung cấp. 5. Thêm một góc nhìn phản biện vào thiết kế.\n\nVì sao cách này hữu ích: Prompt kết hợp kiểm nguồn, đại diện và quyền dữ liệu trước khi ứng dụng.\n\nChuyển sang lĩnh vực khác: Dùng cho tuyển dụng, y tế, truyền thông, giáo dục hoặc nghiên cứu; độ nhạy và trách nhiệm duyệt thay theo ngành.","activity":{"task":"Mở nguồn của phần này và làm thử: Rà một bộ câu hỏi học tập. Dữ liệu: Bộ 6 câu hỏi giả định chỉ dùng tên và bối cảnh của một nhóm học viên; một câu chứa tên đầy đủ và điểm cá nhân. Bước đầu: Nêu điểm mất cân bằng và thông tin nhạy cảm.","hint":"Không chỉ đổi tên nhân vật; thay bối cảnh và góc nhìn.","sample":"Bản sửa loại tên/điểm cá nhân khỏi prompt thử, mở rộng ví dụ một cách phù hợp, rồi nhờ người có trách nhiệm xem lại tính chính xác và bao trùm."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Thiên lệch có thể xuất hiện trong nguồn, truy hồi và cách viết kết luận. Kiểm nhóm nào được đại diện, ví dụ nào bị thiếu, vai trò nào bị gắn định kiến. “Hãy không thiên lệch” chưa đủ; cần bộ ca thử so các nhóm trong điều kiện tương đương, người có bối cảnh rà kết quả và sửa dữ liệu/tiêu chí. Cũng cần tránh cá nhân hóa chỉ lặp lại góc nhìn người học đã biết, khiến họ ít gặp luận điểm phản biện.\n\nThiết kế chuyển người xử lý: khi nguồn mâu thuẫn, rủi ro cao, người dùng yêu cầu, hoặc hệ vượt ngưỡng lỗi. Người xử lý cần nhận trace và bằng chứng để tiếp tục, không chỉ một câu “AI thất bại”.","activity":{"task":"Tạo hai ca kiểm thiên lệch hoặc quyền cho hệ của bạn. Với mỗi ca, nêu dấu hiệu lỗi và hành động dừng.","hint":"Một ca nên liên quan tài liệu sai quyền hoặc thông tin cá nhân.","sample":"Hỏi hồ sơ người khác → truy hồi trả 0 đoạn và báo thiếu quyền, không chuyển nội dung vào ngữ cảnh."}}],"cases":[{"domain":"Hành chính","situation":"Bảo vệ quy trình gửi bản tin","input":"Hệ thống có quyền đọc ghi chú và tạo bản nháp. Chưa có quyền gửi. Người dùng chỉ yêu cầu “chuẩn bị bản tin”.","steps":["Phân loại hành động.","Viết điểm dừng và câu trả lời cuối.","Mô tả điều cần có nếu muốn bổ sung khả năng gửi."],"result":"Đọc nguồn và tạo bản nháp là trong phạm vi. Dừng ở bản nháp, báo chưa gửi. Khả năng gửi cần công cụ, quyền và yêu cầu rõ về người nhận/nội dung; kiểm tra trước gửi.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Soạn thư có thể làm trong bản nháp; gửi thư cần đúng người nhận và phạm vi cho phép. Mọi ngành đều có hành động cần giới hạn; ngưỡng phải theo tác động thực và chính sách nơi dùng."},{"domain":"Tuyển dụng","situation":"Rà một bộ câu hỏi học tập","input":"Bộ 6 câu hỏi giả định chỉ dùng tên và bối cảnh của một nhóm học viên; một câu chứa tên đầy đủ và điểm cá nhân.","steps":["Nêu điểm mất cân bằng và thông tin nhạy cảm.","Viết lại hai câu hỏi đa dạng hơn.","Đề xuất cách dùng dữ liệu mẫu thay dữ liệu thật."],"result":"Bản sửa loại tên/điểm cá nhân khỏi prompt thử, mở rộng ví dụ một cách phù hợp, rồi nhờ người có trách nhiệm xem lại tính chính xác và bao trùm.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Bản tóm tắt ứng viên không suy năng lực từ tên, ảnh hoặc trường học. Dùng cho tuyển dụng, y tế, truyền thông, giáo dục hoặc nghiên cứu; độ nhạy và trách nhiệm duyệt thay theo ngành."}],"practice":{"basic":{"title":"Bảo vệ quy trình gửi bản tin","task":"Hệ thống có quyền đọc ghi chú và tạo bản nháp. Chưa có quyền gửi. Người dùng chỉ yêu cầu “chuẩn bị bản tin”.","steps":["Phân loại hành động.","Viết điểm dừng và câu trả lời cuối.","Mô tả điều cần có nếu muốn bổ sung khả năng gửi."],"hint":"“Chuẩn bị” không tự cấp quyền gửi tới người khác.","solution":"Đọc nguồn và tạo bản nháp là trong phạm vi. Dừng ở bản nháp, báo chưa gửi. Khả năng gửi cần công cụ, quyền và yêu cầu rõ về người nhận/nội dung; kiểm tra trước gửi."},"applied":{"title":"Rà một bộ câu hỏi học tập","task":"Bộ 6 câu hỏi giả định chỉ dùng tên và bối cảnh của một nhóm học viên; một câu chứa tên đầy đủ và điểm cá nhân.","steps":["Nêu điểm mất cân bằng và thông tin nhạy cảm.","Viết lại hai câu hỏi đa dạng hơn.","Đề xuất cách dùng dữ liệu mẫu thay dữ liệu thật."],"hint":"Không chỉ đổi tên nhân vật; thay bối cảnh và góc nhìn.","solution":"Bản sửa loại tên/điểm cá nhân khỏi prompt thử, mở rộng ví dụ một cách phù hợp, rồi nhờ người có trách nhiệm xem lại tính chính xác và bao trùm."},"rubric":["Có kiểm trước truy hồi/công cụ.","Quyền dữ liệu rõ.","Có bộ ca thiên lệch cụ thể.","Có chuyển người với trace."]},"pitfalls":["Coi xác thực danh tính là đủ quyền với mọi dữ liệu.","Kiểm tra sau khi hành động không thể đảo ngược đã xảy ra.","Sửa thiên lệch bằng khẩu hiệu mà không kiểm ví dụ.","Đưa dữ liệu thật vào bản thử để “tiện hơn”."]},{"number":22,"stage":5,"minutes":105,"title":"Đánh giá agent và vận hành sau thử nghiệm","subtitle":"Trace, trajectory, chất lượng đầu ra, chi phí và thay đổi phiên bản.","prerequisites":"Bài 9, 17–21.","refs":[["agents-companion",17,20],["agents-companion",32,33],["agents-companion",20,23],["agents-companion",31,33],["ai-classroom",186,222],["agents-companion",8,14],["agents-companion",69,73]],"objectives":["Đánh giá hành động chứ không chỉ câu trả lời cuối.","Thiết kế giám sát lỗi và chi phí.","So phiên bản mới với baseline trước khi triển khai."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Một agent có thể đưa đáp án cuối đúng nhờ may mắn dù đã dùng công cụ sai quyền hoặc lặp tốn kém. Vì vậy cần đánh giá trajectory: những công cụ nào được gọi, thứ tự có phù hợp không, có gọi thừa, có vượt ngân sách hay lộ dữ liệu không. Tài liệu Agents Companion mô tả nhiều cách so quỹ đạo: đúng chính xác, đúng thứ tự, có đủ công cụ hoặc chỉ cần một công cụ then chốt. Chọn cách đo phù hợp với nhiệm vụ, không áp cứng một chuẩn.\n\nĐầu ra cuối vẫn cần kiểm sự thật và ích lợi. Có thể dùng kiểm tự động cho schema, công thức hoặc quyền; người chấm cho sắc thái và tính phù hợp; LLM judge cho lọc sơ bộ nhưng phải hiệu chuẩn. Mỗi lỗi nên ghi nguồn gốc: mô hình chọn sai, công cụ trả sai, truy hồi thiếu, hay người giao việc mơ hồ.","activity":{"task":"Mở Agents Companion trang PDF 17–23. Viết một quỹ đạo đúng và một quỹ đạo sai cho cùng tác vụ, dù câu trả lời cuối giống nhau.","hint":"Đưa vào ít nhất một công cụ không được phép hoặc gọi thừa.","sample":"Cả hai trả đúng giá sản phẩm; quỹ đạo sai đã gọi công cụ sửa đơn hàng dù chỉ được hỏi giá."}},{"title":"Đánh giá trajectory & cách dùng công cụ","points":[["Trajectory là gì?","Trajectory là chuỗi hành động dẫn tới kết quả: đọc chính sách, tra hồ sơ, tạo bản nháp, gửi. Kiểm tra chuỗi này giúp phát hiện bỏ bước xác minh hoặc gọi công cụ thừa. Câu trả lời cuối đúng không bù cho việc gửi sai nơi hoặc cập nhật trái quyền."],["Các cách so","Exact match yêu cầu giống chuỗi tham chiếu. In-order cho phép thêm bước nhưng giữ thứ tự bước cần. Any-order chỉ yêu cầu có các bước cần, phù hợp khi thứ tự thực sự không quan trọng. Single-tool kiểm tra một hành động có xuất hiện không. Chọn phép so theo quy trình, không chấm cứng một đường duy nhất khi nhiều đường đều hợp lệ."],["Precision và recall","Precision đo tỷ lệ cuộc gọi liên quan trong cuộc gọi thực tế; recall đo phần bước cần đã được thực hiện. Cần định nghĩa khớp tên thôi hay cả tham số, và cách tính lặp. Chúng không tự phát hiện mọi vi phạm thứ tự; cần thêm điều kiện như đọc trước ghi."]],"prompt":"Đánh giá chuỗi tham chiếu [chuỗi] và thực tế [chuỗi]. Nêu bước thiếu/thừa, vi phạm thứ tự bắt buộc và tham số sai nếu có. Tính precision/recall với quy tắc khớp được nêu rõ. Báo riêng chất lượng kết quả cuối và chất lượng hành động; không dùng một điểm để che lỗi quyền hạn.","body":"Cách thực hiện: 1. Viết chuỗi tham chiếu và quan hệ bắt buộc. 2. Thu nhật ký có công cụ, tham số, trạng thái và thời gian. 3. Chọn phép so phù hợp rồi tính theo quy tắc đếm. 4. Phân tích bước thiếu/thừa và hậu quả.\n\nVì sao cách này hữu ích: Các chỉ số bổ trợ nhau và tách kết quả khỏi quá trình thực thi.\n\nChuyển sang lĩnh vực khác: Dùng cho mọi chuỗi thao tác có phụ thuộc: xuất bản nội dung, nghiên cứu, cập nhật hồ sơ hoặc xử lý dữ liệu.","activity":{"task":"Mở nguồn của phần này và làm thử: Chấm chuỗi hành động nhỏ. Dữ liệu: Tham chiếu: READ_POLICY, READ_RECORD, DRAFT. Thực tế: READ_RECORD, SEARCH_WEB, READ_POLICY, DRAFT. Giả định hai bước READ có thể đổi chỗ; DRAFT phải sau cả hai. Mỗi tên chỉ xuất hiện một lần. Bước đầu: Chấm exact, in-order theo chuỗi đã cho và any-order.","hint":"Có đủ ba bước cần nhưng thêm một bước, và thứ tự hai bước đầu khác chuỗi tham chiếu.","sample":"Exact: không đạt; in-order theo chuỗi đã cho: không đạt; any-order: đạt. Precision = 3/4 = 75%; recall = 3/3 = 100%. Quan hệ thực tế READ trước DRAFT vẫn đạt. SEARCH_WEB chưa có lý do cần thiết trong dữ liệu bài."}},{"title":"Con người, LLM-as-judge & đánh giá đa agent","points":[["LLM-as-judge","Một mô hình có thể chấm đầu ra theo rubric và bằng chứng. Cách này giúp mở rộng số mẫu nhưng có thể ưu ái câu dài, vị trí đáp án hoặc lỗi chung của mô hình. Điểm tự tin do mô hình tạo không phải xác suất đúng đã hiệu chuẩn."],["Con người trong vòng đánh giá","Người có chuyên môn kiểm tra sắc thái, bối cảnh và hậu quả. Có thể chấm trực tiếp, so cặp đầu ra hoặc cho người dùng thử. Hiệu chuẩn bằng cách cùng chấm một nhóm mẫu, thảo luận bất đồng và sửa mô tả tiêu chí trước khi chấm tiếp."],["Hệ nhiều agent","Chấm từng agent riêng và kết quả toàn hệ. Một agent làm đúng phần mình vẫn có thể tạo đầu ra không tương thích với agent sau. Kiểm tra phân công, phối hợp, chất lượng bàn giao, chi phí và độ trễ khi tăng số agent."]],"prompt":"Chấm đầu ra A và B theo rubric [tiêu chí], dựa trên nguồn [nguồn]. Với mỗi tiêu chí, nêu bằng chứng cụ thể và điều chưa đủ để chấm. Không thưởng chỉ vì câu dài. Tách lỗi định dạng, lỗi dữ kiện và sở thích trình bày. Kết quả sẽ được người có chuyên môn đối chiếu.","body":"Cách thực hiện: 1. Tạo một nhóm mẫu do người hiểu lĩnh vực xác nhận. 2. Cho mô hình chấm cùng rubric. 3. So bất đồng và kiểm tra thiên lệch về thứ tự/độ dài. 4. Kết hợp kiểm tra tự động cho định dạng và con người cho trường hợp quan trọng.\n\nVì sao cách này hữu ích: Yêu cầu bằng chứng và phân loại lỗi giúp kiểm tra người chấm thay vì tin điểm chung.\n\nChuyển sang lĩnh vực khác: Chọn vai trò người chấm theo kiến thức cần thiết, không chỉ theo mức quen dùng AI.","activity":{"task":"Mở nguồn của phần này và làm thử: Chấm hai câu trả lời. Dữ liệu: Nguồn: cuộc họp có 10 người. A: “Có 10 người tham gia.” B: “Cuộc họp thành công vang dội với 12 thành viên năng động.” Bước đầu: Chấm độ đúng nguồn và mức rõ ràng riêng.","hint":"B dài hơn nhưng đổi số và thêm đánh giá không có nguồn.","sample":"A đúng dữ kiện; B sai số 12 và thêm “thành công” không được chứng minh. Không có cơ sở cho B điểm cao hơn vì văn phong. Một phép thử này chỉ minh họa thiên lệch, chưa đánh giá đầy đủ bộ chấm."}},{"title":"AgentOps: từ bản thử đến vận hành","points":[["Các lớp vận hành","DevOps xử lý phần mềm, triển khai và vận hành. MLOps thêm dữ liệu và hành vi mô hình. PromptOps quản lý prompt, phiên bản và điểm đánh giá. RAGOps quản lý chuẩn bị nguồn, chỉ mục và truy xuất. AgentOps thêm công cụ, điều phối, trạng thái và bộ nhớ. Chúng bổ sung cho nhau, không thay các nguyên tắc phần mềm cơ bản."],["Metrics và trace","Metrics cho biết tổng thể: tỷ lệ hoàn thành, lỗi, chi phí, độ trễ và phản hồi người dùng. Trace ghi chuỗi bước của một lần chạy để tìm nguyên nhân. Log cần đủ để debug nhưng không lưu dữ liệu nhạy cảm không cần thiết. Đo cả kết quả công việc, không chỉ số lượt gọi mô hình."],["Triển khai có thể kiểm soát","Gắn phiên bản prompt, mô hình, công cụ và nguồn với kết quả. Thử offline, pilot nhỏ, giám sát rồi mở rộng. Khi chất lượng giảm, cần người chịu trách nhiệm, ngưỡng dừng và bản ổn định để quay lại. Không bỏ qua xác thực, quota, xử lý lỗi hoặc kiểm tra phần mềm chỉ vì đã có agent."]],"prompt":"Lập kế hoạch vận hành cho [agent]. Nêu chỉ số thành công, lỗi, chi phí và độ trễ; cách thu trace theo run_id; phiên bản prompt/mô hình/công cụ/nguồn; thông tin cần che khỏi log. Định nghĩa pilot, ngưỡng dừng, người xử lý và cách quay lại bản ổn định. Phân biệt dữ liệu đã đo với mục tiêu đề xuất.","body":"Cách thực hiện: 1. Định nghĩa mục tiêu và 3–5 chỉ số. 2. Thiết kế log/trace theo mã lần chạy. 3. Gắn phiên bản các thành phần để tái hiện lỗi. 4. Đặt ngưỡng dừng và kế hoạch rollback trước pilot.\n\nVì sao cách này hữu ích: Kế hoạch nối chất lượng, trách nhiệm và khả năng khôi phục trước khi mở rộng.\n\nChuyển sang lĩnh vực khác: Dù là công cụ cá nhân hay hệ thống tổ chức, giữ nhật ký phiên bản và lỗi giúp cải tiến có căn cứ.","activity":{"task":"Mở nguồn của phần này và làm thử: Thiết kế bảng giám sát. Dữ liệu: 100 tác vụ: 82 hoàn thành đúng, 8 sai, 10 chuyển người. Tổng chi phí giả định 50 đơn vị. Chưa có dữ liệu thời gian. Bước đầu: Tính tỷ lệ hoàn thành đúng và chi phí trên tác vụ đúng.","hint":"Chi phí trên tác vụ đúng không phải tổng chi phí chia 100.","sample":"Hoàn thành đúng 82%; chi phí/tác vụ đúng = 50/82 ≈ 0,61 đơn vị. Còn thiếu độ trễ, loại lỗi và tác động. Không coi ngưỡng đề xuất là chuẩn chung cho mọi ứng dụng."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"AgentOps là vận hành agent sau khi bản thử hoạt động: theo dõi trace, độ trễ, lỗi, chi phí, dữ liệu, phiên bản mô hình và phản hồi người dùng. FMOps liên quan quản trị mô hình nền tảng; PromptOps quản lý prompt và phép thử; RAGOps theo dõi nạp và truy hồi nguồn. Những nhãn này hữu ích khi gắn với trách nhiệm cụ thể, không cần biến thành sơ đồ phức tạp nếu nhóm nhỏ.\n\nKhi thay mô hình, prompt hoặc nguồn, chạy lại bộ ca chuẩn và ca lỗi đã từng gặp. Theo dõi trượt chất lượng theo thời gian. Một bản thử tốt trên 10 ca chưa đủ để tự động mở quyền rộng; mở rộng từng bước, giữ phương án quay lại và người xử lý khi hệ lỗi.","activity":{"task":"Tạo bảng theo dõi tuần đầu cho agent giả định: tỷ lệ đạt, lỗi quyền, lượt công cụ, phút xử lý và năm ca cần người duyệt.","hint":"Đặt ngưỡng dừng trước khi xem số liệu.","sample":"Nếu xuất hiện một hành động ghi không được phép thì dừng mở rộng dù điểm trả lời cao."}}],"cases":[{"domain":"Hành chính","situation":"Chấm chuỗi hành động nhỏ","input":"Tham chiếu: READ_POLICY, READ_RECORD, DRAFT. Thực tế: READ_RECORD, SEARCH_WEB, READ_POLICY, DRAFT. Giả định hai bước READ có thể đổi chỗ; DRAFT phải sau cả hai. Mỗi tên chỉ xuất hiện một lần.","steps":["Chấm exact, in-order theo chuỗi đã cho và any-order.","Tính precision/recall theo tên công cụ.","Nhận xét bước web có cần hay không theo phạm vi."],"result":"Exact: không đạt; in-order theo chuỗi đã cho: không đạt; any-order: đạt. Precision = 3/4 = 75%; recall = 3/3 = 100%. Quan hệ thực tế READ trước DRAFT vẫn đạt. SEARCH_WEB chưa có lý do cần thiết trong dữ liệu bài.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Phải kiểm tra người nhận trước gửi thông báo dù nội dung cuối đúng. Dùng cho mọi chuỗi thao tác có phụ thuộc: xuất bản nội dung, nghiên cứu, cập nhật hồ sơ hoặc xử lý dữ liệu."},{"domain":"Nghiên cứu","situation":"Thiết kế bảng giám sát","input":"100 tác vụ: 82 hoàn thành đúng, 8 sai, 10 chuyển người. Tổng chi phí giả định 50 đơn vị. Chưa có dữ liệu thời gian.","steps":["Tính tỷ lệ hoàn thành đúng và chi phí trên tác vụ đúng.","Nêu chỉ số còn thiếu.","Đề xuất ngưỡng pilot và ghi rõ đó là đề xuất."],"result":"Hoàn thành đúng 82%; chi phí/tác vụ đúng = 50/82 ≈ 0,61 đơn vị. Còn thiếu độ trễ, loại lỗi và tác động. Không coi ngưỡng đề xuất là chuẩn chung cho mọi ứng dụng.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Theo dõi nhận định có nguồn, nguồn lỗi thời và thời gian kiểm tra báo cáo. Dù là công cụ cá nhân hay hệ thống tổ chức, giữ nhật ký phiên bản và lỗi giúp cải tiến có căn cứ."}],"practice":{"basic":{"title":"Chấm chuỗi hành động nhỏ","task":"Tham chiếu: READ_POLICY, READ_RECORD, DRAFT. Thực tế: READ_RECORD, SEARCH_WEB, READ_POLICY, DRAFT. Giả định hai bước READ có thể đổi chỗ; DRAFT phải sau cả hai. Mỗi tên chỉ xuất hiện một lần.","steps":["Chấm exact, in-order theo chuỗi đã cho và any-order.","Tính precision/recall theo tên công cụ.","Nhận xét bước web có cần hay không theo phạm vi."],"hint":"Có đủ ba bước cần nhưng thêm một bước, và thứ tự hai bước đầu khác chuỗi tham chiếu.","solution":"Exact: không đạt; in-order theo chuỗi đã cho: không đạt; any-order: đạt. Precision = 3/4 = 75%; recall = 3/3 = 100%. Quan hệ thực tế READ trước DRAFT vẫn đạt. SEARCH_WEB chưa có lý do cần thiết trong dữ liệu bài."},"applied":{"title":"Thiết kế bảng giám sát","task":"100 tác vụ: 82 hoàn thành đúng, 8 sai, 10 chuyển người. Tổng chi phí giả định 50 đơn vị. Chưa có dữ liệu thời gian.","steps":["Tính tỷ lệ hoàn thành đúng và chi phí trên tác vụ đúng.","Nêu chỉ số còn thiếu.","Đề xuất ngưỡng pilot và ghi rõ đó là đề xuất."],"hint":"Chi phí trên tác vụ đúng không phải tổng chi phí chia 100.","solution":"Hoàn thành đúng 82%; chi phí/tác vụ đúng = 50/82 ≈ 0,61 đơn vị. Còn thiếu độ trễ, loại lỗi và tác động. Không coi ngưỡng đề xuất là chuẩn chung cho mọi ứng dụng."},"rubric":["Trace có hành động và kết quả công cụ.","Đầu ra và trajectory được chấm riêng.","Có ngưỡng dừng và quay lại.","Phiên bản thay đổi được kiểm lại."]},"pitfalls":["Any-order cho qua bước duyệt sau gửi.","Đếm tên công cụ đúng nhưng bỏ qua tham số sai.","Dùng cùng mô hình tự khen chính nó làm bằng chứng duy nhất.","Bỏ qua lỗi tại điểm bàn giao giữa agent.","Chỉ đo mức sử dụng mà bỏ chất lượng."]},{"number":23,"stage":5,"minutes":105,"title":"Ưu tiên cơ hội và thiết kế thử nghiệm giá trị","subtitle":"Ma trận tác động–nỗ lực, bản đồ quy trình và lợi ích ròng.","prerequisites":"Bài 2, 9 và 21–22.","refs":[["use-cases",5,9],["use-cases",25,28],["use-cases",5,5],["use-cases",23,32],["enterprise",16,22],["ai-classroom",223,247]],"objectives":["Chọn use case theo giá trị và khả năng triển khai.","Thiết kế pilot với baseline và điều kiện dừng.","Đo tác động người dùng, không chỉ số lần gọi AI."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Ý tưởng ứng dụng AI thường nhiều hơn năng lực triển khai. Tài liệu Identifying and Scaling AI Use Cases đề xuất nhìn từ công việc lặp, nút thắt kỹ năng, mơ hồ và sáu nhóm tác vụ; sau đó đặt lên ma trận tác động–nỗ lực. Tác động phải là kết quả người dùng quan tâm: thời gian ròng, sai sót giảm, chất lượng học hoặc dịch vụ cải thiện. Nỗ lực gồm dữ liệu, tích hợp, quyền, đào tạo và kiểm liên tục.\n\nMa trận chỉ là dụng cụ thảo luận, không phải phép tính khách quan tuyệt đối. Ghi giả định cho từng ô và độ chắc chắn. Một ý tưởng tác động cao nhưng không có dữ liệu hoặc người duyệt có thể chưa sẵn sàng. Chọn một pilot nhỏ, dễ đo, rồi học từ lỗi thực tế trước khi mở rộng.","activity":{"task":"Mở Identifying and Scaling AI Use Cases trang PDF 24–30. Đặt ba ý tưởng của bạn vào ma trận tác động–nỗ lực và ghi một giả định chưa chắc cho mỗi ý.","hint":"Tác động cần quy về người học hoặc người nhận công việc.","sample":"Tóm tắt họp: tác động vừa, nỗ lực thấp; giả định là biên bản đủ rõ để trích đầu việc."}},{"title":"Tìm cơ hội, ưu tiên & ước tính giá trị","points":[["Từ điểm đau đến use case","Thu thập việc lặp, điểm nghẽn kỹ năng và chỗ khó bắt đầu từ người trực tiếp làm. Ghi ai dùng, tần suất, dữ liệu, đầu ra và cách kiểm tra. Ý tưởng phải đủ cụ thể để có thể thử, không chỉ “AI cho marketing”."],["Ma trận bốn vùng","Tác động cao/công sức thấp là ứng viên ưu tiên. Công sức thấp/tác động thấp có thể là công cụ tự phục vụ. Tác động cao/công sức cao cần đầu tư và phạm vi rõ. Công sức cao/tác động thấp thường hoãn. Quyền dữ liệu và hậu quả sai có thể là điều kiện loại, không chỉ một điểm nhỏ được bù bởi lợi ích."],["Giá trị ròng","Thời gian tiết kiệm = thời gian cũ − thời gian tạo/kiểm tra/sửa mới, nhân số lần thực sự dùng. Trừ cả đào tạo và bảo trì khi xét thời kỳ. Ước tính cần khoảng và giả định; không mặc định mọi người đều sử dụng hoặc mọi phút tiết kiệm biến thành tiền thu về."]],"prompt":"Ưu tiên các use case [danh sách] theo tác động, công sức, dữ liệu sẵn có và hậu quả sai. Nêu bằng chứng hoặc giả định cho từng điểm. Tính thời gian tiết kiệm ròng gồm kiểm tra/sửa và tỷ lệ sử dụng thực tế. Đề xuất một pilot, baseline, người phụ trách và điều kiện dừng.","body":"Cách thực hiện: 1. Thu 5–10 ý tưởng từ công việc cụ thể. 2. Chấm tác động/công sức bằng cùng thang có mô tả. 3. Kiểm tra điều kiện dữ liệu và trách nhiệm. 4. Chọn pilot, ghi baseline và ngày đánh giá lại.\n\nVì sao cách này hữu ích: Ước tính giá trị có chi phí ẩn và tỷ lệ dùng thật giúp tránh kết luận quá lạc quan.\n\nChuyển sang lĩnh vực khác: Có thể dùng phút/tuần cho cá nhân hoặc chi phí và chất lượng cho tổ chức; không nhất thiết quy mọi lợi ích thành tiền.","activity":{"task":"Mở nguồn của phần này và làm thử: Tính tiết kiệm ròng. Dữ liệu: 40 báo cáo/tháng. Cách cũ 30 phút/báo cáo. Cách mới 5 phút tạo + 10 phút kiểm tra/sửa. Chỉ 75% báo cáo phù hợp dùng AI. Bảo trì mẫu 60 phút/tháng. Bước đầu: Tính số báo cáo phù hợp.","hint":"15 phút tiết kiệm chỉ áp dụng cho 30 báo cáo.","sample":"30 báo cáo × (30−15) = 450 phút; trừ bảo trì 60 còn 390 phút = 6,5 giờ/tháng. Cần đo thực tế thời gian sửa và tỷ lệ phù hợp, không coi 6,5 giờ là đảm bảo."}},{"title":"Triển khai thử, đào tạo & mở rộng sử dụng","points":[["Vai trò cùng tham gia","Quy trình GPT Lab trong nguồn có người dùng nghiệp vụ, chuyên gia chủ đề và người kỹ thuật. Người dùng xác định vấn đề; chuyên gia chuẩn bị nguồn/tiêu chí; kỹ thuật triển khai và kiểm thử. Lãnh đạo hỗ trợ nguồn lực, nhưng người làm trực tiếp cần tham gia thiết kế."],["Năm bước triển khai","Design xác định mục đích/phạm vi; prepare chuẩn bị dữ liệu; build/test tạo và đánh giá; launch đưa vào dùng kèm hướng dẫn; pivot/scale cải tiến hoặc đổi hướng theo phản hồi. Workshop, hackathon và học từ đồng nghiệp giúp thu ý tưởng, nhưng ý tưởng vẫn cần ưu tiên và kiểm tra."],["Mở rộng theo bằng chứng","Đo tỷ lệ sử dụng, hoàn thành đúng, thời gian ròng và phản hồi. Hướng dẫn người dùng khi nào nên dùng, khi nào chuyển người và cách báo lỗi. Đánh giá lại danh mục theo định kỳ vì công sức và nhu cầu thay đổi. Giữ phương án dừng/rollback khi chất lượng giảm."]],"prompt":"Lập pilot cho [use case] theo 5 bước design, prepare, build/test, launch, improve. Nêu người chịu trách nhiệm, dữ liệu, baseline, tiêu chí đạt, cách hướng dẫn và thu phản hồi. Định nghĩa điều kiện mở rộng, sửa hoặc dừng, cùng kế hoạch quay lại quy trình cũ. Ghi giả định chưa kiểm chứng.","body":"Cách thực hiện: 1. Viết brief ngắn và phân công ba vai. 2. Chọn dữ liệu thử cùng baseline. 3. Chạy pilot nhỏ, thu cả lỗi và phản hồi. 4. Quyết định tiếp tục, sửa, mở rộng hoặc dừng theo tiêu chí đã đặt.\n\nVì sao cách này hữu ích: Pilot có trách nhiệm và tiêu chí quyết định giúp học từ thực tế thay vì chỉ giới thiệu tính năng.\n\nChuyển sang lĩnh vực khác: Với cá nhân, ba vai có thể do một người đảm nhiệm ở các thời điểm khác nhau; vẫn cần tách lúc tạo và lúc kiểm tra.","activity":{"task":"Mở nguồn của phần này và làm thử: Pilot hai tuần. Dữ liệu: Nhóm 5 người, 20 tác vụ/tuần, hiện mất 15 phút/tác vụ. Mục tiêu đề xuất: giảm thời gian ròng ít nhất 20% mà không tăng lỗi nghiêm trọng. Chưa biết mức lỗi nền. Bước đầu: Lập kế hoạch đo baseline trước pilot.","hint":"Chưa có lỗi nền thì không thể khẳng định “không tăng lỗi”.","sample":"Đo nhóm tác vụ cũ bằng cùng định nghĩa lỗi trước khi so. Mục tiêu thời gian là tối đa 12 phút gồm kiểm tra/sửa. Nếu giảm thời gian nhưng lỗi nghiêm trọng tăng, chưa đạt tiêu chí mở rộng."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Thiết kế pilot cần người sở hữu, phạm vi, dữ liệu mẫu, chuẩn so sánh, bộ ca khó, quyền, thời gian và tiêu chí tiếp tục. Theo dõi lợi ích ròng: thời gian AI tiết kiệm trừ thời gian chuẩn bị, kiểm, sửa và xử lý lỗi. Nếu người dùng không tin hoặc không dùng kết quả, hiệu suất mô hình không chuyển thành giá trị tổ chức.\n\nKhi kết quả không đạt, phân loại nguyên nhân trước khi đổi công cụ: dữ liệu đầu vào kém, tác vụ không phù hợp, prompt mơ hồ, người dùng chưa được hướng dẫn hay quyền quá chặt. Đôi khi giải pháp tốt nhất là sửa quy trình hiện tại trước khi đưa AI vào.","activity":{"task":"Viết kế hoạch pilot 2 tuần cho ý tưởng ưu tiên: baseline, 10 ca thử, hai chỉ số và điều kiện dừng.","hint":"Một chỉ số chất lượng, một chỉ số lợi ích ròng.","sample":"Mục tiêu giảm 20% phút xử lý ròng và không tăng lỗi thiếu nguồn; dừng nếu có rò quyền."}}],"cases":[{"domain":"Nhóm học tập","situation":"Tính tiết kiệm ròng","input":"40 báo cáo/tháng. Cách cũ 30 phút/báo cáo. Cách mới 5 phút tạo + 10 phút kiểm tra/sửa. Chỉ 75% báo cáo phù hợp dùng AI. Bảo trì mẫu 60 phút/tháng.","steps":["Tính số báo cáo phù hợp.","Tính tiết kiệm trước và sau bảo trì.","Nêu một giả định cần đo trong pilot."],"result":"30 báo cáo × (30−15) = 450 phút; trừ bảo trì 60 còn 390 phút = 6,5 giờ/tháng. Cần đo thực tế thời gian sửa và tỷ lệ phù hợp, không coi 6,5 giờ là đảm bảo.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Ưu tiên tạo câu hỏi ôn từ ghi chú đã có thay vì làm hệ agent nhiều công cụ ngay. Có thể dùng phút/tuần cho cá nhân hoặc chi phí và chất lượng cho tổ chức; không nhất thiết quy mọi lợi ích thành tiền."},{"domain":"Vận hành","situation":"Pilot hai tuần","input":"Nhóm 5 người, 20 tác vụ/tuần, hiện mất 15 phút/tác vụ. Mục tiêu đề xuất: giảm thời gian ròng ít nhất 20% mà không tăng lỗi nghiêm trọng. Chưa biết mức lỗi nền.","steps":["Lập kế hoạch đo baseline trước pilot.","Nêu cách thu thời gian tạo, kiểm tra và sửa.","Đặt điều kiện kết thúc và quyết định mở rộng."],"result":"Đo nhóm tác vụ cũ bằng cùng định nghĩa lỗi trước khi so. Mục tiêu thời gian là tối đa 12 phút gồm kiểm tra/sửa. Nếu giảm thời gian nhưng lỗi nghiêm trọng tăng, chưa đạt tiêu chí mở rộng.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Thử tóm tắt phiếu hỗ trợ với một bộ phận, đo thời gian sửa và lỗi phân loại. Với cá nhân, ba vai có thể do một người đảm nhiệm ở các thời điểm khác nhau; vẫn cần tách lúc tạo và lúc kiểm tra."}],"practice":{"basic":{"title":"Tính tiết kiệm ròng","task":"40 báo cáo/tháng. Cách cũ 30 phút/báo cáo. Cách mới 5 phút tạo + 10 phút kiểm tra/sửa. Chỉ 75% báo cáo phù hợp dùng AI. Bảo trì mẫu 60 phút/tháng.","steps":["Tính số báo cáo phù hợp.","Tính tiết kiệm trước và sau bảo trì.","Nêu một giả định cần đo trong pilot."],"hint":"15 phút tiết kiệm chỉ áp dụng cho 30 báo cáo.","solution":"30 báo cáo × (30−15) = 450 phút; trừ bảo trì 60 còn 390 phút = 6,5 giờ/tháng. Cần đo thực tế thời gian sửa và tỷ lệ phù hợp, không coi 6,5 giờ là đảm bảo."},"applied":{"title":"Pilot hai tuần","task":"Nhóm 5 người, 20 tác vụ/tuần, hiện mất 15 phút/tác vụ. Mục tiêu đề xuất: giảm thời gian ròng ít nhất 20% mà không tăng lỗi nghiêm trọng. Chưa biết mức lỗi nền.","steps":["Lập kế hoạch đo baseline trước pilot.","Nêu cách thu thời gian tạo, kiểm tra và sửa.","Đặt điều kiện kết thúc và quyết định mở rộng."],"hint":"Chưa có lỗi nền thì không thể khẳng định “không tăng lỗi”.","solution":"Đo nhóm tác vụ cũ bằng cùng định nghĩa lỗi trước khi so. Mục tiêu thời gian là tối đa 12 phút gồm kiểm tra/sửa. Nếu giảm thời gian nhưng lỗi nghiêm trọng tăng, chưa đạt tiêu chí mở rộng."},"rubric":["Có tác động và nỗ lực giải thích được.","Baseline trước pilot.","Đo lợi ích ròng.","Có quyết định tiếp tục/dừng dựa bằng chứng."]},"pitfalls":["Bỏ thời gian kiểm tra kết quả.","Dùng số điểm chính xác giả khi dữ liệu còn rất ít.","Chỉ đếm tài khoản đăng ký.","Không có người nhận và xử lý báo lỗi."]},{"number":24,"stage":5,"minutes":105,"title":"Bài học từ triển khai AI trong tổ chức","subtitle":"Nguồn doanh nghiệp, nền tảng tri thức, tinh chỉnh và quản trị thay đổi.","prerequisites":"Bài 11, 19 và 21–23.","refs":[["agents-companion",38,45],["agents-companion",69,70],["enterprise",23,24],["enterprise",13,15],["agents-guide",8,8],["agents-companion",36,37],["agents-companion",69,71],["enterprise",3,22]],"objectives":["Đọc case study mà không suy rộng quá mức.","Chọn prompt, RAG hoặc fine-tuning theo lỗi cần sửa.","Thiết kế đào tạo và người chịu trách nhiệm khi mở rộng."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Tài liệu AI in the Enterprise trình bày nhiều trường hợp doanh nghiệp như hỗ trợ tri thức, cá nhân hóa, dịch vụ và nền tảng cho nhà phát triển. Mỗi trường hợp là một minh họa có bối cảnh, không phải bằng chứng mọi tổ chức sẽ có cùng hiệu quả. Khi đọc, ghi rõ mục tiêu, đầu vào, giải pháp, chỉ số được công bố, phần chưa biết và điều kiện khác với nơi bạn làm việc.\n\nChọn kỹ thuật theo loại thiếu hụt. Nếu yêu cầu chưa rõ hoặc định dạng bất ổn, sửa prompt và đánh giá trước. Nếu cần tri thức cập nhật từ tài liệu, cân nhắc truy hồi có quyền. Nếu cần hành vi chuyên biệt ổn định và có dữ liệu huấn luyện/đánh giá phù hợp, mới xem xét fine-tuning. Fine-tuning không tự cập nhật sự thật và không thay thế quản trị nguồn.","activity":{"task":"Mở AI in the Enterprise trang PDF 6–20. Chọn một trường hợp và điền bảng: mục tiêu, giải pháp, kết quả được nêu, dữ kiện còn thiếu để áp dụng ở nơi khác.","hint":"Phân biệt lời mô tả trong tài liệu và kết quả bạn tự đo.","sample":"Một case có thể nêu chất lượng tăng trong nội bộ, nhưng chưa cho biết chi phí kiểm hoặc cấu trúc dữ liệu của tổ chức khác."}},{"title":"Tri thức doanh nghiệp, nền tảng & quyền dữ liệu","points":[["Ba nhu cầu khác nhau","Trợ lý nghiên cứu nguồn giúp hỏi và tổng hợp tài liệu đã chọn. Tìm kiếm hợp nhất giúp truy cập nhiều kho dữ liệu. Nền tảng agent thêm công cụ hành động, runtime, trạng thái và quản trị. Các nhu cầu có thể kết hợp nhưng không đồng nhất."],["Từ sản phẩm sang yêu cầu","PDF mô tả NotebookLM Enterprise, Agentspace, Agent Builder/Engine và dịch vụ eval/search theo thời điểm 2025. Học các vai trò kiến trúc: kết nối, tìm kiếm, kiểm soát quyền, điều phối, đánh giá và vận hành. Tên, gói, API và khả năng hiện tại cần kiểm tra tài liệu chính thức trước lựa chọn hoặc mua; khóa học không coi mô tả cũ là thông số hiện hành."],["Quyền theo người và nguồn","SSO là đăng nhập tập trung; RBAC phân quyền theo vai trò; IAM quản lý danh tính/quyền. Kết quả tìm kiếm phải giữ quyền của người dùng, kể cả khi ghép nhiều nguồn. Cần biết dữ liệu lưu đâu, được dùng để làm gì, thời hạn lưu và cách xóa. Không suy chính sách doanh nghiệp trong PDF thành chính sách cho mọi tài khoản AI."]],"prompt":"Thiết kế yêu cầu cho hệ tra cứu [nguồn]. Lập bảng nhóm người, dữ liệu được đọc, hành động được phép và thời hạn cập nhật. Nêu cách giữ quyền khi truy xuất/tổng hợp, cách xóa dữ liệu và kiểm tra audit. Tách yêu cầu kiến trúc khỏi tên sản phẩm. Những thông số sản phẩm chưa kiểm tra hiện tại phải ghi chưa xác minh.","body":"Cách thực hiện: 1. Liệt kê nhu cầu và kho dữ liệu. 2. Lập bảng quyền người dùng theo từng nguồn. 3. Đặt yêu cầu cập nhật, xóa, audit và phục hồi. 4. So lựa chọn bằng bằng chứng tài liệu hiện tại khi triển khai thật.\n\nVì sao cách này hữu ích: Yêu cầu rõ giúp so nền tảng mà không dựa vào nhãn marketing hoặc đánh đổi quyền dữ liệu.\n\nChuyển sang lĩnh vực khác: Hệ tri thức cá nhân cũng cần phân biệt nguồn tin cậy, nguồn riêng và bản lỗi thời.","activity":{"task":"Mở nguồn của phần này và làm thử: Bảng quyền cho kho tri thức. Dữ liệu: Nguồn: hướng dẫn sản phẩm công khai; kế hoạch nội bộ chỉ nhân viên; hồ sơ lương chỉ HR. Người dùng: khách, nhân viên, HR. Bước đầu: Lập ma trận đọc.","hint":"Không chỉ chặn liên kết; nội dung tổng hợp cũng không được lộ phần không có quyền.","sample":"Khách đọc nguồn công khai; nhân viên thêm kế hoạch; HR đọc hồ sơ lương theo quyền được cấp. Câu hỏi vượt quyền phải không truy xuất hoặc tiết lộ nội dung, kể cả qua suy diễn tóm tắt."}},{"title":"Prompt, RAG, fine-tuning & build-or-buy","points":[["Ba cách can thiệp","Prompt thay hướng dẫn và ví dụ; RAG cung cấp tri thức được truy xuất tại lúc chạy; fine-tuning là huấn luyện thêm để thay hành vi mô hình theo dữ liệu. Thiếu thông tin mới thường cần nguồn/công cụ, không chỉ thêm ví dụ phong cách. Fine-tuning không tự bảo đảm đúng mọi dữ kiện hoặc luôn trích dẫn hợp lệ."],["Dữ liệu và eval trước","Trước tùy chỉnh, có bộ thử và phân tích lỗi. Nếu cân nhắc fine-tuning, cần dữ liệu đúng, quyền sử dụng, tách tập huấn luyện/đánh giá và đo so baseline. Nguồn nêu Lowe’s như trường hợp lịch sử; không phải chỉ dẫn chọn một dịch vụ hiện tại hoặc bảo đảm mức cải thiện tương tự."],["Tự xây hay dùng nền tảng","So khả năng cần, tích hợp, quyền dữ liệu, vận hành, chi phí chuyển đổi và tổng công sức. Dùng nền tảng có thể giảm phần hạ tầng; tự xây có thể tăng kiểm soát nhưng cũng tăng trách nhiệm. Đặt tiêu chí nghiệm thu cho cả hai."]],"prompt":"Phân tích lỗi [ví dụ lỗi] và so prompt, RAG, công cụ xác định, fine-tuning. Nêu mỗi phương án giải quyết phần nào, dữ liệu cần, eval và chi phí vận hành. Đề xuất thử nghiệm nhỏ nhất trước. Nếu cần nền tảng/API, đánh dấu các yêu cầu phải đối chiếu tài liệu hiện tại, không giả định dịch vụ trong PDF còn giữ nguyên.","body":"Cách thực hiện: 1. Phân loại lỗi: yêu cầu mơ hồ, thiếu nguồn, sai hành vi hay công cụ. 2. Thử thay đổi đơn giản nhất giải quyết lỗi. 3. So các phương án trên cùng bộ eval. 4. Tính công sức vận hành và kiểm tra khả dụng hiện tại trước triển khai.\n\nVì sao cách này hữu ích: Lựa chọn xuất phát từ lỗi và phép đo, tránh nâng cấp kiến trúc khi nguyên nhân đơn giản hơn.\n\nChuyển sang lĩnh vực khác: Dù lĩnh vực nào, hãy tìm nguyên nhân lỗi trước chọn giải pháp kỹ thuật.","activity":{"task":"Mở nguồn của phần này và làm thử: Chọn can thiệp phù hợp. Dữ liệu: A: báo sai giá vì bảng giá hôm qua. B: nội dung đúng nhưng sai giọng thương hiệu. C: phép cộng sai. D: mẫu tác vụ lặp lớn, prompt đã thử kỹ nhưng chưa đạt hành vi mong muốn. Bước đầu: Chọn bước đầu cho A/B/C.","hint":"Công cụ tính thường phù hợp hơn việc ép mô hình nhẩm lại nhiều lần.","sample":"A cần dữ liệu mới/truy xuất đúng phiên bản; B thử style guide và mẫu; C dùng tính toán xác định; D cần bộ dữ liệu, baseline, quyền và đánh giá độc lập trước cân nhắc huấn luyện. Không có lựa chọn đúng chỉ từ tên kỹ thuật."}},{"title":"Bảy bài học từ doanh nghiệp","points":[["Đo trước, tạo giá trị trong sản phẩm","Morgan Stanley minh họa bắt đầu bằng eval dịch, tóm tắt và chuyên gia chấm. Indeed minh họa giải thích lý do gợi ý để cải thiện trải nghiệm, rồi tối ưu tài nguyên. Bài học là chọn kết quả người dùng quan tâm và đo nó; các chỉ số PDF nêu thuộc trường hợp/thời điểm đó, không phải dự báo cho bạn."],["Lặp, tùy chỉnh và trao công cụ cho chuyên gia","Klarna minh họa cải tiến qua nhiều vòng và phổ biến sử dụng. Lowe’s minh họa tùy chỉnh cho dữ liệu sản phẩm. BBVA minh họa để người gần quy trình tìm use case cùng hỗ trợ quản trị. Không suy ra thay người hoàn toàn hay huấn luyện luôn là lựa chọn đầu tiên."],["Giảm nghẽn phát triển và tự động hóa quy trình","Mercado Libre minh họa nền tảng chung cho xây ứng dụng, dữ liệu và kiểm soát. OpenAI minh họa công cụ hỗ trợ nhân viên truy xuất, soạn phản hồi và thực hiện bước công việc. Điểm chung là kết hợp người, quy trình và công nghệ, tăng phạm vi theo bằng chứng."]],"prompt":"Phân tích trường hợp [tên, trang nguồn]. Lập bảng: vấn đề, can thiệp, kết quả nguồn báo cáo, điều kiện, thông tin còn thiếu. Phân biệt kết quả đã báo cáo và dự báo. Rút một nguyên tắc rồi đề xuất thử nghiệm cho bối cảnh [bối cảnh], không áp nguyên số liệu của công ty khác.","body":"Cách thực hiện: 1. Đọc một trường hợp trong PDF và ghi vấn đề ban đầu. 2. Tách can thiệp, chỉ số báo cáo và điều chưa được mô tả. 3. Rút một nguyên tắc có thể chuyển sang bối cảnh của bạn. 4. Thiết kế pilot riêng thay vì dùng chỉ số doanh nghiệp làm mục tiêu mặc định.\n\nVì sao cách này hữu ích: Khung giữ giá trị học từ tình huống mà không biến case study thành bằng chứng nhân quả hoặc lời hứa.\n\nChuyển sang lĩnh vực khác: Chuyển nguyên tắc như đo lường, thử nhỏ và chuyên gia tham gia; không chuyển nguyên KPI.","activity":{"task":"Mở nguồn của phần này và làm thử: Chuyển bài học eval sang việc của bạn. Dữ liệu: Chọn Morgan Stanley ở trang 6–8. Bối cảnh mới: nhóm 5 người muốn dùng AI tóm tắt biên bản họp, 20 biên bản/tháng. Bước đầu: Nêu ba tiêu chí tóm tắt cần kiểm tra.","hint":"Đủ việc, đúng người/hạn và không bịa trạng thái là tiêu chí gần tác vụ.","sample":"Có thể dùng 10 biên bản đã biết kết quả để chấm trước, rồi thử có kiểm tra trong một tháng. Không suy ra tỷ lệ tiết kiệm hoặc độ chính xác giống doanh nghiệp trong PDF; cần đo ở nhóm mình."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Triển khai không kết thúc khi mô hình trả lời được. Cần chủ dữ liệu, người duyệt, cập nhật tài liệu, hướng dẫn người dùng, ghi lỗi và quyết định khi tạm dừng. Một nền tảng tìm kiếm nội bộ phải giữ quyền tài liệu qua mọi bước; người dùng không được nhận đoạn chỉ vì nó gần về nghĩa. Đào tạo người dùng cần ví dụ sai và cách kiểm, không chỉ danh sách mẹo prompt.\n\nKhi mở rộng, giữ khả năng đo theo từng nhóm dùng. Nếu nhóm quen công cụ hưởng lợi còn nhóm ít kỹ năng bị bỏ lại, phải sửa thiết kế và hỗ trợ. Ghi quyết định thay đổi phiên bản và kiểm lại bộ ca cũ để tránh cải tiến ở một trường hợp làm hỏng trường hợp khác.","activity":{"task":"Thiết kế bản chuyển giao cho một use case: ai sở hữu nguồn, ai nhận báo lỗi, lịch cập nhật, cách đào tạo và phép đo sau một tháng.","hint":"Không giao hết trách nhiệm cho “đội AI” mơ hồ.","sample":"Chủ chính sách cập nhật tài liệu; đội sản phẩm kiểm quyền/truy hồi; người quản lý nghiệp vụ duyệt câu trả lời quan trọng."}}],"cases":[{"domain":"Trường học","situation":"Bảng quyền cho kho tri thức","input":"Nguồn: hướng dẫn sản phẩm công khai; kế hoạch nội bộ chỉ nhân viên; hồ sơ lương chỉ HR. Người dùng: khách, nhân viên, HR.","steps":["Lập ma trận đọc.","Mô tả câu trả lời khi nhân viên hỏi hồ sơ lương.","Thiết kế một test để phát hiện rò rỉ qua tóm tắt."],"result":"Khách đọc nguồn công khai; nhân viên thêm kế hoạch; HR đọc hồ sơ lương theo quyền được cấp. Câu hỏi vượt quyền phải không truy xuất hoặc tiết lộ nội dung, kể cả qua suy diễn tóm tắt.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Giảng viên và sinh viên có thể xem các bộ tài liệu khác nhau dù cùng một hệ tìm kiếm. Hệ tri thức cá nhân cũng cần phân biệt nguồn tin cậy, nguồn riêng và bản lỗi thời."},{"domain":"Nhóm nhỏ","situation":"Chuyển bài học eval sang việc của bạn","input":"Chọn Morgan Stanley ở trang 6–8. Bối cảnh mới: nhóm 5 người muốn dùng AI tóm tắt biên bản họp, 20 biên bản/tháng.","steps":["Nêu ba tiêu chí tóm tắt cần kiểm tra.","Thiết kế pilot có người chấm.","Ghi hai điều chưa thể suy từ case study."],"result":"Có thể dùng 10 biên bản đã biết kết quả để chấm trước, rồi thử có kiểm tra trong một tháng. Không suy ra tỷ lệ tiết kiệm hoặc độ chính xác giống doanh nghiệp trong PDF; cần đo ở nhóm mình.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Tạo thư viện mẫu chung và người phụ trách kiểm tra, thay vì mua hệ lớn ngay. Chuyển nguyên tắc như đo lường, thử nhỏ và chuyên gia tham gia; không chuyển nguyên KPI."}],"practice":{"basic":{"title":"Bảng quyền cho kho tri thức","task":"Nguồn: hướng dẫn sản phẩm công khai; kế hoạch nội bộ chỉ nhân viên; hồ sơ lương chỉ HR. Người dùng: khách, nhân viên, HR.","steps":["Lập ma trận đọc.","Mô tả câu trả lời khi nhân viên hỏi hồ sơ lương.","Thiết kế một test để phát hiện rò rỉ qua tóm tắt."],"hint":"Không chỉ chặn liên kết; nội dung tổng hợp cũng không được lộ phần không có quyền.","solution":"Khách đọc nguồn công khai; nhân viên thêm kế hoạch; HR đọc hồ sơ lương theo quyền được cấp. Câu hỏi vượt quyền phải không truy xuất hoặc tiết lộ nội dung, kể cả qua suy diễn tóm tắt."},"applied":{"title":"Chuyển bài học eval sang việc của bạn","task":"Chọn Morgan Stanley ở trang 6–8. Bối cảnh mới: nhóm 5 người muốn dùng AI tóm tắt biên bản họp, 20 biên bản/tháng.","steps":["Nêu ba tiêu chí tóm tắt cần kiểm tra.","Thiết kế pilot có người chấm.","Ghi hai điều chưa thể suy từ case study."],"hint":"Đủ việc, đúng người/hạn và không bịa trạng thái là tiêu chí gần tác vụ.","solution":"Có thể dùng 10 biên bản đã biết kết quả để chấm trước, rồi thử có kiểm tra trong một tháng. Không suy ra tỷ lệ tiết kiệm hoặc độ chính xác giống doanh nghiệp trong PDF; cần đo ở nhóm mình."},"rubric":["Case study được đọc theo bối cảnh.","Chọn kỹ thuật theo loại lỗi.","Có chủ sở hữu dữ liệu và vận hành.","Có đào tạo và đo theo người dùng."]},"pitfalls":["Cho rằng có connector là dữ liệu luôn mới.","Áp dụng chính sách một gói dịch vụ cho mọi gói.","Dùng fine-tuning để thay cơ chế cập nhật dữ liệu.","Chỉ so chi phí tạo bản demo.","Đọc dự báo như lợi nhuận đã đạt."]},{"number":25,"stage":6,"minutes":105,"title":"AI như gia sư: học bằng câu hỏi và phản hồi","subtitle":"Chẩn đoán nhẹ, gợi ý theo nấc và bài tự làm để đo tiến bộ.","prerequisites":"Bài 1, 9 và 13. Có một kỹ năng muốn học.","refs":[["use-cases",20,21],["prompt",21,28],["ai-classroom",91,154],["ai-classroom",19,44],["ai-classroom",91,126]],"objectives":["Thiết kế gia sư không đưa đáp án quá sớm.","Thích nghi mức khó dựa trên bằng chứng.","Đo khả năng chuyển giao sau khi AI rút lui."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"The AI Classroom mô tả khả năng đưa giải thích khác nhau cho người học khác nhau, nhưng cá nhân hóa không nên dựa trên phán đoán vội từ một câu trả lời. Bắt đầu bằng mục tiêu đo được và vài câu chẩn đoán. Nếu người học sai, hỏi họ đã thử gì và chọn gợi ý nhỏ nhất có thể giúp họ tự đi tiếp. Khi họ làm đúng, đổi bối cảnh để kiểm liệu họ hiểu nguyên tắc hay chỉ lặp mẫu.\n\nGia sư AI có xu hướng làm bài hộ nếu người học yêu cầu ngay đáp án; cảm giác hiểu khi đọc lời giải cũng có thể khác khả năng tự làm. Một chu kỳ hiệu quả là dự đoán → thử → nhận gợi ý → sửa → giải thích lại → làm bài mới không trợ giúp. Người dạy hoặc người học giữ quyền xác định mục tiêu và kiểm sai của AI.","activity":{"task":"Mở The AI Classroom trang PDF 91–126. Chọn một khái niệm bạn đang học và viết ba nấc gợi ý, từ nhắc nguyên tắc đến chỉ ra bước kế.","hint":"Nấc một không được làm hộ phép tính hoặc đáp án.","sample":"Nấc 1: hỏi công thức nào liên quan; nấc 2: nhắc điều kiện dùng; nấc 3: minh họa một bước tương tự nhưng khác số liệu."}},{"title":"Ý tưởng, chiến lược, học tập & nhập vai","points":[["Mở rộng rồi thu hẹp","Khi tạo ý tưởng, cần đa dạng theo giả định hoặc cách tiếp cận. Khi chọn chiến lược, cần mục tiêu, nguồn lực, phụ thuộc và phép thử. Không chọn ngay ý tưởng nghe hay nhất mà bỏ qua khả năng thực hiện."],["Nhập vai là mô phỏng","AI có thể đóng vai khách hàng, người phỏng vấn hoặc gia sư để bạn luyện. Phản ứng giả định không phải dữ liệu khảo sát thật, không đại diện phân bố người dùng. Dùng mô phỏng để chuẩn bị câu hỏi hoặc phát hiện giả thuyết, sau đó kiểm tra ngoài đời."],["Phản hồi giúp tự học","Yêu cầu một câu hỏi mỗi lượt, gợi ý theo mức và phản hồi vào lỗi cụ thể. Người học tự trả lời trước rồi viết lại. Trong nghiên cứu hay quản lý, có thể áp dụng cùng cách làm để phản biện giả định của kế hoạch."]],"prompt":"Mô phỏng [vai trò] trong bối cảnh [dữ liệu]. Mỗi lượt đặt một câu hỏi và chờ tôi trả lời. Sau câu trả lời, phản hồi theo [tiêu chí], chỉ ra tối đa hai điểm cần sửa. Thực hiện 5 lượt. Cuối cùng tách: điều đã luyện, giả thuyết mới và điều cần kiểm tra với người thật. Không xem phản hồi mô phỏng là kết quả khảo sát.","body":"Cách thực hiện: 1. Nêu mục tiêu thực hành hoặc quyết định. 2. Chọn vai trò và dữ kiện mà vai trò được biết. 3. Giới hạn số lượt và mức phản hồi. 4. Chốt điều đã học và việc cần kiểm tra với người thật.\n\nVì sao cách này hữu ích: Giới hạn và tiêu chí làm cho nhập vai thành buổi luyện tập có sản phẩm.\n\nChuyển sang lĩnh vực khác: Thay vai trò và rubric để luyện ngoại ngữ, thuyết trình, thương lượng hoặc phản biện học thuật.","activity":{"task":"Mở nguồn của phần này và làm thử: Luyện trình bày một ý tưởng. Dữ liệu: Ý tưởng: câu lạc bộ đọc sách 30 phút mỗi tuần. Người nghe giả định là bạn học bận rộn. Chưa có khảo sát nhu cầu. Bước đầu: Luyện năm lượt, tự trả lời.","hint":"Hỏi về hành vi và trở ngại thật, không chỉ “bạn có thích ý tưởng không?”.","sample":"Câu hỏi thực tế có thể hỏi lần gần nhất đọc sách, thời gian có thể tham gia và điều khiến bỏ buổi. Phản ứng của AI chỉ giúp chuẩn bị; chưa đủ dự đoán số người tham gia."}},{"title":"Gia sư AI thích nghi với người học","points":[["Cá nhân hóa có điều kiện","Sách nhấn mạnh khả năng đưa nhiều cách giải thích và bài luyện theo mức hiện tại. Bắt đầu bằng câu hỏi chẩn đoán ngắn và mục tiêu cụ thể; không suy năng lực lâu dài từ một đáp án. Giáo viên/người học giữ quyền quyết định mức và nội dung."],["Gợi ý theo nấc","Lượt đầu hỏi người học đã thử gì; nếu vướng, cho gợi ý nhỏ; sau đó phản hồi vào lập luận, không chỉ đáp án. Cuối vòng yêu cầu người học tự giải một bài tương tự hoặc giải thích lại. Người học khá cần bài thay đổi bối cảnh và yêu cầu suy luận, không chỉ nhiều câu hơn."],["Giới hạn","Gia sư AI có thể giải thích sai hoặc làm hộ. Với vấn đề tâm lý, an toàn, kết quả học tập quan trọng hoặc học sinh nhỏ, cần người có trách nhiệm xem xét. Đánh giá bằng việc người học tự làm được ở lần sau, không bằng mức hài lòng tức thời."]],"prompt":"Hãy làm gia sư cho [chủ đề]. Mục tiêu [năng lực]. Trước tiên hỏi tôi 2 câu chẩn đoán. Mỗi lượt chỉ hỏi một câu hoặc cho một gợi ý nhỏ dựa trên câu trả lời của tôi; không đưa đáp án đầy đủ trước khi tôi thử. Khi tôi làm đúng, cho một bài mới khác bối cảnh để kiểm tra tự làm.","body":"Cách thực hiện: 1. Chọn một mục tiêu học có bằng chứng đạt. 2. Đặt 2 câu chẩn đoán và quy tắc mức khó. 3. Thiết kế ba nấc gợi ý, cấm lộ đáp án trước nỗ lực. 4. Thử với người mới và người đã thành thạo. 5. Đánh giá qua bài chuyển giao không có trợ giúp.\n\nVì sao cách này hữu ích: Prompt bảo vệ thời gian tư duy của người học và đo được chuyển giao.\n\nChuyển sang lĩnh vực khác: Cùng phương pháp dùng khi đào tạo nhân viên, ôn chứng chỉ hoặc học kỹ năng cá nhân; người chịu trách nhiệm kiểm tra thay đổi theo bối cảnh.","activity":{"task":"Mở nguồn của phần này và làm thử: Gia sư cho khái niệm mới. Dữ liệu: Chọn một khái niệm bạn đang học. Người học giả định hiểu định nghĩa nhưng nhầm khi áp dụng. Bước đầu: Viết 2 câu chẩn đoán.","hint":"Gợi ý đầu nên nhắc nguyên tắc, chưa làm hộ phép tính.","sample":"Kịch bản tốt chẩn đoán sai lầm cụ thể, cho gợi ý theo nấc, yêu cầu người học tự giải và kiểm lại trên tình huống mới."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Cá nhân hóa có thể giúp người học vướng bắt kịp và người học khá gặp thử thách sâu hơn. Tuy nhiên “khó hơn” không chỉ là nhiều câu hơn; có thể là phản ví dụ, liên hệ ngành khác hoặc yêu cầu bảo vệ lựa chọn. Với người cần hỗ trợ, giữ mục tiêu cốt lõi nhưng giảm tải từ vựng và chia bước. Trong cả hai trường hợp, bài tự làm cuối phải đo cùng năng lực.\n\nTrong công việc, mô hình gia sư có thể dùng để đào tạo nhân viên mới: hỏi cách họ xử lý một ca, phản hồi theo quy trình chuẩn và cho ca mới. Không để AI tự kết luận năng lực nghề nghiệp cuối cùng từ vài lượt chat; người quản lý hoặc chuyên gia vẫn cần quan sát việc làm thật.","activity":{"task":"Thiết kế một bài chuyển giao khác ví dụ đã luyện và rubric ba tiêu chí để tự chấm.","hint":"Đổi ngữ cảnh nhưng giữ nguyên nguyên tắc.","sample":"Sau khi học phân tích một biểu đồ doanh số, tự phân tích biểu đồ tiến độ học theo cùng quy tắc trục, đơn vị và xu hướng."}}],"cases":[{"domain":"Tuyển dụng","situation":"Luyện trình bày một ý tưởng","input":"Ý tưởng: câu lạc bộ đọc sách 30 phút mỗi tuần. Người nghe giả định là bạn học bận rộn. Chưa có khảo sát nhu cầu.","steps":["Luyện năm lượt, tự trả lời.","Ghi ba giả định bị chất vấn.","Thiết kế ba câu hỏi ngắn để hỏi người thật sau buổi luyện."],"result":"Câu hỏi thực tế có thể hỏi lần gần nhất đọc sách, thời gian có thể tham gia và điều khiến bỏ buổi. Phản ứng của AI chỉ giúp chuẩn bị; chưa đủ dự đoán số người tham gia.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Luyện trả lời phỏng vấn theo mô tả công việc, tự trả lời rồi nhận phản hồi theo rubric. Thay vai trò và rubric để luyện ngoại ngữ, thuyết trình, thương lượng hoặc phản biện học thuật."},{"domain":"Ngoại ngữ","situation":"Gia sư cho khái niệm mới","input":"Chọn một khái niệm bạn đang học. Người học giả định hiểu định nghĩa nhưng nhầm khi áp dụng.","steps":["Viết 2 câu chẩn đoán.","Soạn 3 gợi ý tăng dần.","Tạo một bài chuyển giao và tiêu chí chấm."],"result":"Kịch bản tốt chẩn đoán sai lầm cụ thể, cho gợi ý theo nấc, yêu cầu người học tự giải và kiểm lại trên tình huống mới.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Cho phản hồi một lỗi giao tiếp mỗi lượt, rồi yêu cầu người học tự viết câu mới. Cùng phương pháp dùng khi đào tạo nhân viên, ôn chứng chỉ hoặc học kỹ năng cá nhân; người chịu trách nhiệm kiểm tra thay đổi theo bối cảnh."}],"practice":{"basic":{"title":"Luyện trình bày một ý tưởng","task":"Ý tưởng: câu lạc bộ đọc sách 30 phút mỗi tuần. Người nghe giả định là bạn học bận rộn. Chưa có khảo sát nhu cầu.","steps":["Luyện năm lượt, tự trả lời.","Ghi ba giả định bị chất vấn.","Thiết kế ba câu hỏi ngắn để hỏi người thật sau buổi luyện."],"hint":"Hỏi về hành vi và trở ngại thật, không chỉ “bạn có thích ý tưởng không?”.","solution":"Câu hỏi thực tế có thể hỏi lần gần nhất đọc sách, thời gian có thể tham gia và điều khiến bỏ buổi. Phản ứng của AI chỉ giúp chuẩn bị; chưa đủ dự đoán số người tham gia."},"applied":{"title":"Gia sư cho khái niệm mới","task":"Chọn một khái niệm bạn đang học. Người học giả định hiểu định nghĩa nhưng nhầm khi áp dụng.","steps":["Viết 2 câu chẩn đoán.","Soạn 3 gợi ý tăng dần.","Tạo một bài chuyển giao và tiêu chí chấm."],"hint":"Gợi ý đầu nên nhắc nguyên tắc, chưa làm hộ phép tính.","solution":"Kịch bản tốt chẩn đoán sai lầm cụ thể, cho gợi ý theo nấc, yêu cầu người học tự giải và kiểm lại trên tình huống mới."},"rubric":["Có chẩn đoán trước gợi ý.","Gợi ý tăng dần, không làm hộ sớm.","Có bài chuyển giao tự làm.","Không dùng chat làm kết luận năng lực cuối."]},"pitfalls":["Coi persona giả lập là khách hàng đại diện.","Để AI tự viết cả câu hỏi và câu trả lời của bạn.","Tăng số lượng bài nhưng không tăng chiều sâu.","Dùng câu trả lời AI như đánh giá năng lực cuối cùng."]},{"number":26,"stage":6,"minutes":105,"title":"Thiết kế bài học và đào tạo cùng AI","subtitle":"Mục tiêu, hoạt động, rubric và vai trò người hướng dẫn.","prerequisites":"Bài 2, 9 và 25. Có đối tượng người học cụ thể.","refs":[["ai-classroom",46,90],["ai-classroom",324,341],["ai-classroom",45,72],["ai-classroom",288,322]],"objectives":["Liên kết mục tiêu với hoạt động và bằng chứng đạt.","Viết rubric có mức quan sát được.","Phân vai AI và người hướng dẫn."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Một bài học không bắt đầu bằng câu hỏi “AI tạo được gì?”, mà bằng điều người học sẽ tự làm được sau buổi học. Viết mục tiêu bằng hành vi quan sát: giải thích, so sánh, chọn, tính, sửa hoặc tạo sản phẩm; nêu điều kiện và tiêu chí. Sau đó chọn hoạt động tạo cơ hội luyện đúng hành vi ấy và bài đánh giá đo cùng năng lực. Nếu mục tiêu là phân biệt dữ kiện với suy luận, chỉ nghe AI thuyết trình sẽ không đủ; người học phải tự phân loại và giải thích.\n\nAI có thể soạn phiên bản đầu của giáo án, ví dụ, câu hỏi và rubric. Người hướng dẫn kiểm đúng nội dung, phù hợp người học, điều kiện thiết bị và độ công bằng. Rubric tránh từ mơ hồ “hay, sáng tạo” nếu không mô tả dấu hiệu cụ thể. Có thể làm ngôn ngữ dễ hiểu hơn cho người mới nhưng không ngầm hạ mục tiêu cốt lõi.","activity":{"task":"Mở The AI Classroom trang PDF 63–90 và 324–341. Viết một mục tiêu học và rubric ba mức; thử với hai bài làm giả định.","hint":"Mỗi mức cần bằng chứng có thể chỉ ra trong bài làm.","sample":"Mức đạt: nêu hai dữ kiện có nguồn và tách một suy luận; mức cao: còn chỉ ra giới hạn của nguồn."}},{"title":"Thiết kế bài học, rubric & phản hồi cùng AI","points":[["Kế hoạch học từ mục tiêu","Sách đề cập AI giúp tạo giáo án, câu hỏi, tài liệu phân hóa và việc hành chính. Bắt đầu từ năng lực cần đạt, kiến thức trước, thời lượng, hoạt động và cách chứng minh học được. AI cung cấp bản nháp; người dạy xem lại nội dung, phù hợp lứa tuổi và điều kiện lớp."],["Rubric có tiêu chí quan sát","Rubric mô tả mức đạt bằng hành vi/sản phẩm, ví dụ “nêu luận điểm và 2 bằng chứng” thay vì “hay”. Có thể viết phiên bản ngôn ngữ đơn giản hơn để giúp người học hiểu nhưng giữ chuẩn kiến thức cốt lõi, tránh ngầm hạ tiêu chuẩn."],["Phản hồi theo chu kỳ","Phản hồi chỉ ra điều đã làm được, một chỗ cần sửa và bước tiếp theo. Với chấm điểm ảnh hưởng người học, người có trách nhiệm xác nhận; AI có thể bỏ sót ngữ cảnh. Không đưa dữ liệu cá nhân vào công cụ khi chưa có quyền và quy định phù hợp."]],"prompt":"Hỗ trợ phác thảo bài học [chủ đề] cho [đối tượng], thời lượng [T]. Mục tiêu đo được [M]; đầu vào đã biết [K]. Đề xuất hoạt động 3 phần và rubric 4 tiêu chí mô tả mức đạt bằng bằng chứng. Với bài làm mẫu, chỉ gợi ý phản hồi; không tự quyết điểm cuối. Đánh dấu nơi người dạy cần kiểm.","body":"Cách thực hiện: 1. Viết mục tiêu và bằng chứng đạt trước. 2. Tạo hoạt động mở đầu, luyện có hỗ trợ và tự làm. 3. Soạn rubric 3–4 tiêu chí có ví dụ mức đạt. 4. Dùng AI tạo phản hồi thử cho hai bài giả định. 5. Người dạy sửa sai lệch và kiểm tính công bằng.\n\nVì sao cách này hữu ích: Mục tiêu, hoạt động và đánh giá khớp nhau, có quyền duyệt rõ.\n\nChuyển sang lĩnh vực khác: Dùng cho trường học, onboarding, workshop, huấn luyện cộng đồng; thay người học và chuẩn nghề nghiệp.","activity":{"task":"Mở nguồn của phần này và làm thử: Bài học 30 phút có rubric. Dữ liệu: Chủ đề: phân biệt dữ kiện và suy luận trong một đoạn tin 120 chữ tự tạo. Bước đầu: Viết mục tiêu đo được.","hint":"Bài cuối yêu cầu học viên tự gạch dưới dữ kiện, không chỉ chọn đáp án.","sample":"Kế hoạch đạt khi hoạt động dẫn đến đúng mục tiêu, rubric đo bằng chứng và phản hồi nêu hành động sửa cụ thể. Điểm cuối do người có trách nhiệm xác nhận."}},{"title":"Con người thiết kế trải nghiệm học và dẫn dắt thử nghiệm","points":[["Vai trò người hướng dẫn","Sách xem người dạy như người thiết kế trải nghiệm, quan sát hiểu lầm, kết nối và điều chỉnh. Đây là định hướng sư phạm, không phải lời khẳng định mọi mô hình dạy truyền thống đều lỗi thời. AI có thể giảm thời gian soạn nháp; quan hệ, bối cảnh và trách nhiệm vẫn ở người thật."],["Thử nghiệm có chủ đích","Chọn một hoạt động nhỏ, nêu giả thuyết lợi ích, thời gian chuẩn bị, chất lượng học và rủi ro. Ghi baseline, thử với nhóm nhỏ, thu phản hồi của cả người học và người dạy. Nếu tiết kiệm thời gian nhưng giảm khả năng tự giải thích, cần đổi cách dùng."],["Phát triển nghề nghiệp","Huấn luyện thực hành gồm viết prompt, kiểm nguồn, thiết kế đánh giá, dữ liệu và xử lý lỗi. Tạo nhóm chia sẻ mẫu tốt/sai, không chỉ một buổi giới thiệu công cụ. Sách đưa viễn cảnh nghề giáo tương lai; coi đó là kịch bản để lập kế hoạch, không phải dự báo chắc chắn."]],"prompt":"Với hoạt động [X], hãy phân vai AI/người hướng dẫn/người học. Đề xuất thử nghiệm nhỏ: baseline, 3 thước đo, rủi ro và điểm dừng. AI chỉ soạn phương án; người thật duyệt nội dung, quan sát tương tác và quyết định sửa.","body":"Cách thực hiện: 1. Chọn một khâu gây tốn thời gian. 2. Nêu việc AI hỗ trợ, việc người thật quyết và thước đo. 3. Thử hai tuần hoặc vài lượt làm nhỏ. 4. Thu phản hồi cùng bài kiểm năng lực độc lập. 5. Điều chỉnh quy trình và tài liệu huấn luyện.\n\nVì sao cách này hữu ích: Lợi ích được đo cùng chất lượng học và vai trò con người.\n\nChuyển sang lĩnh vực khác: Áp dụng cho giáo dục, chăm sóc khách hàng, hỗ trợ sức khỏe không lâm sàng và đào tạo nghề; xác định rõ người chịu trách nhiệm.","activity":{"task":"Mở nguồn của phần này và làm thử: Kế hoạch thử nghiệm 2 tuần. Dữ liệu: Một nhóm mất 3 giờ/tuần chuẩn bị tài liệu học. Muốn dùng AI để giảm 1 giờ nhưng vẫn giữ chất lượng. Bước đầu: Viết baseline và mục tiêu.","hint":"Một chỉ số cần đo người học tự làm được, không chỉ thời gian soạn.","sample":"Kế hoạch đạt khi đo cả thời gian và chất lượng qua bài độc lập, có người duyệt tài liệu, ghi lỗi và quyết định tiếp tục/dừng dựa bằng chứng."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Người hướng dẫn tạo giá trị ở việc quan sát hiểu lầm, điều chỉnh nhịp, kết nối người học và quyết định khi nào cần tự luyện không AI. The AI Classroom nêu viễn cảnh giáo viên như người thiết kế trải nghiệm; coi đây là định hướng để thử và đo, không phải dự báo chắc chắn về mọi lớp học. Trong đào tạo công việc, chuyên gia cũng đóng vai trò tương tự khi chuyển kinh nghiệm khó viết thành quy tắc cho người mới.\n\nThử một hoạt động nhỏ trước: đo thời gian soạn, mức tham gia, kết quả bài tự làm và phản hồi người học. Nếu AI tiết kiệm 30 phút chuẩn bị nhưng khiến người học phụ thuộc đáp án, cần thay cách dùng. Đào tạo người hướng dẫn phải gồm tình huống AI sai và quy trình sửa, không chỉ giới thiệu nút bấm.","activity":{"task":"Lập kế hoạch thử một buổi 30 phút có AI: baseline, hoạt động, bài tự làm và người duyệt.","hint":"Đo kết quả học bên cạnh thời gian chuẩn bị.","sample":"AI gợi ba câu hỏi, người dạy chọn một; sau thảo luận, học viên tự giải ca mới 5 phút."}}],"cases":[{"domain":"Đào tạo công việc","situation":"Bài học 30 phút có rubric","input":"Chủ đề: phân biệt dữ kiện và suy luận trong một đoạn tin 120 chữ tự tạo.","steps":["Viết mục tiêu đo được.","Thiết kế 3 hoạt động với thời lượng.","Làm rubric 3 tiêu chí và hai ví dụ phản hồi."],"result":"Kế hoạch đạt khi hoạt động dẫn đến đúng mục tiêu, rubric đo bằng chứng và phản hồi nêu hành động sửa cụ thể. Điểm cuối do người có trách nhiệm xác nhận.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Bài học xử lý khiếu nại, rubric về xác nhận vấn đề và giải pháp rõ. Dùng cho trường học, onboarding, workshop, huấn luyện cộng đồng; thay người học và chuẩn nghề nghiệp."},{"domain":"Quản lý đội nhóm","situation":"Kế hoạch thử nghiệm 2 tuần","input":"Một nhóm mất 3 giờ/tuần chuẩn bị tài liệu học. Muốn dùng AI để giảm 1 giờ nhưng vẫn giữ chất lượng.","steps":["Viết baseline và mục tiêu.","Phân vai AI/người/nguồn.","Đặt 3 chỉ số và hai điều kiện dừng."],"result":"Kế hoạch đạt khi đo cả thời gian và chất lượng qua bài độc lập, có người duyệt tài liệu, ghi lỗi và quyết định tiếp tục/dừng dựa bằng chứng.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. AI soạn tài liệu onboarding; người quản lý hướng dẫn, lắng nghe và xác nhận năng lực. Áp dụng cho giáo dục, chăm sóc khách hàng, hỗ trợ sức khỏe không lâm sàng và đào tạo nghề; xác định rõ người chịu trách nhiệm."}],"practice":{"basic":{"title":"Bài học 30 phút có rubric","task":"Chủ đề: phân biệt dữ kiện và suy luận trong một đoạn tin 120 chữ tự tạo.","steps":["Viết mục tiêu đo được.","Thiết kế 3 hoạt động với thời lượng.","Làm rubric 3 tiêu chí và hai ví dụ phản hồi."],"hint":"Bài cuối yêu cầu học viên tự gạch dưới dữ kiện, không chỉ chọn đáp án.","solution":"Kế hoạch đạt khi hoạt động dẫn đến đúng mục tiêu, rubric đo bằng chứng và phản hồi nêu hành động sửa cụ thể. Điểm cuối do người có trách nhiệm xác nhận."},"applied":{"title":"Kế hoạch thử nghiệm 2 tuần","task":"Một nhóm mất 3 giờ/tuần chuẩn bị tài liệu học. Muốn dùng AI để giảm 1 giờ nhưng vẫn giữ chất lượng.","steps":["Viết baseline và mục tiêu.","Phân vai AI/người/nguồn.","Đặt 3 chỉ số và hai điều kiện dừng."],"hint":"Một chỉ số cần đo người học tự làm được, không chỉ thời gian soạn.","solution":"Kế hoạch đạt khi đo cả thời gian và chất lượng qua bài độc lập, có người duyệt tài liệu, ghi lỗi và quyết định tiếp tục/dừng dựa bằng chứng."},"rubric":["Mục tiêu đo được.","Hoạt động và đánh giá khớp mục tiêu.","Rubric có mức quan sát.","Vai trò con người và chỉ số thử rõ."]},"pitfalls":["Rubric dùng tính từ mơ hồ.","Phân hóa bằng cách bỏ mục tiêu cốt lõi.","Đo số phút tiết kiệm mà bỏ qua học tập.","Đào tạo một lần rồi coi người dùng đã thành thạo."]},{"number":27,"stage":6,"minutes":135,"title":"Đánh giá quá trình, công bằng và dữ liệu người học","subtitle":"Thấy người học nghĩ gì, ai được tiếp cận và thông tin nào được phép dùng.","prerequisites":"Bài 21 và 25–26.","refs":[["ai-classroom",127,185],["ai-classroom",186,222],["ai-classroom",342,350],["ai-classroom",223,247],["ai-classroom",248,287]],"objectives":["Thiết kế đánh giá quá trình song song sản phẩm.","Cho phương án học tương đương khi thiếu AI.","Kiểm thiên lệch và quyền riêng tư."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Khi AI có thể tạo một bài viết hoặc hình ảnh chỉ trong vài phút, sản phẩm cuối không còn cho thấy đầy đủ người học đã hiểu gì. The AI Classroom gợi đánh giá quá trình: bản nháp, lựa chọn, lý do sửa, phản hồi và bài tự giải thích. Điều này không có nghĩa bỏ chấm sản phẩm; cần cả chất lượng cuối và bằng chứng hình thành kỹ năng. Một bài chuyển giao ngắn không trợ giúp giúp kiểm điều người học tự làm được.\n\nQuy tắc dùng AI nên được công bố trước nhiệm vụ: phần nào được gợi ý, phần nào phải tự làm, cách khai báo hỗ trợ. Không thể dùng độ “giống AI” của văn bản làm bằng chứng duy nhất về gian lận. Hãy thiết kế việc học khiến suy nghĩ hiện ra, thay vì đoán nguồn gốc câu chữ sau khi nộp.","activity":{"task":"Mở The AI Classroom trang PDF 186–222. Viết quy tắc AI cho một bài bạn đang học: được phép, không được phép, và bằng chứng quá trình.","hint":"Quy tắc phải gắn với kỹ năng muốn đo.","sample":"Được nhờ AI góp ý dàn ý; người học tự chọn nguồn, viết lập luận và giải thích miệng một điểm."}},{"title":"Prompt literacy & sản phẩm học tập đa phương thức","points":[["Năng lực dùng prompt","Người học cần nói rõ mục tiêu, bối cảnh, dạng kết quả rồi đặt câu hỏi phản biện. Chất lượng học nằm ở quyết định chọn, sửa và giải thích; việc AI tạo bản nháp nhanh không chứng minh người học đã hiểu."],["Đa phương thức gắn với kiến thức","Sách đề xuất portfolio, hình, video và mô phỏng để diễn đạt hiểu biết. Trước khi chọn hình thức, xác định kiến thức cần thể hiện và phép kiểm. Một video đẹp nhưng sai chu trình khoa học là chưa đạt; một mô phỏng AI tạo ra cần so với quy luật và dữ kiện gốc."],["Nhật ký đóng góp","Lưu prompt chính, đầu ra, chỗ sai, quyết định sửa và phản tư. Có thể trình bày trên trang portfolio ngắn. Nếu công cụ hỗ trợ và chính sách cho phép, nêu phần nào do AI hỗ trợ; không cần ghi mọi câu lệnh vụn vặt."]],"prompt":"Tôi đang học [chủ đề] và muốn tạo [sản phẩm]. Mục tiêu hiểu [M]. Hãy giúp tôi viết brief, nêu 3 dữ kiện phải kiểm bằng [nguồn], đề xuất hai ý tưởng rồi đợi tôi chọn. Sau mỗi bản nháp, hỏi tôi điều tôi đã thay đổi và vì sao. Không viết phần phản tư thay tôi.","body":"Cách thực hiện: 1. Chọn một mục tiêu học và hình thức sản phẩm phù hợp. 2. Viết brief, nguồn và tiêu chí đúng. 3. Tạo bản nháp, chỉ ra ít nhất 2 lỗi hoặc chỗ chưa chắc. 4. Sửa, kiểm lại nội dung và ghi đóng góp của mình. 5. Yêu cầu người học giải thích sản phẩm mà không nhìn AI.\n\nVì sao cách này hữu ích: Prompt dùng AI để tạo lựa chọn và phản hồi nhưng giữ việc giải thích ở người học.\n\nChuyển sang lĩnh vực khác: Dùng trong học nghề, đào tạo công ty, truyền thông khoa học; mọi nơi cần sản phẩm và bằng chứng năng lực.","activity":{"task":"Mở nguồn của phần này và làm thử: Portfolio học tập một trang. Dữ liệu: Chọn chủ đề đơn giản bạn đã học, ví dụ một quy trình, quy tắc ngữ pháp hoặc biểu đồ. Bước đầu: Đặt mục tiêu và hình thức sản phẩm.","hint":"Nếu chưa có công cụ ảnh, storyboard bằng chữ vẫn đủ để đánh giá tư duy.","sample":"Portfolio đạt khi có nguồn, mục tiêu, phiên bản, sửa có lý do và người học tự giải thích được kiến thức. Hình đẹp không thay cho sự hiểu đúng."}},{"title":"Đánh giá quá trình & ranh giới dùng AI","points":[["Quá trình bên cạnh sản phẩm","Sách đề xuất lưu bản nháp, lý do sửa, phản hồi và phần tự giải thích. Sản phẩm cuối vẫn quan trọng nhưng chưa đủ để thấy kỹ năng nào thuộc người học. Một lần vấn đáp ngắn hoặc bài chuyển giao không trợ giúp có thể xác nhận hiểu biết."],["Chính sách theo nhiệm vụ","Có việc AI được gợi ý/soát lỗi, có việc cần tự làm để luyện cơ bản, có việc phải công bố mức hỗ trợ. Viết quy tắc trước khi giao bài, cùng ví dụ được phép và không được phép. Tránh dùng công cụ dò AI như bằng chứng duy nhất để kết luận vi phạm vì độ tin cậy phụ thuộc bối cảnh."],["Lớp học đảo ngược","Thông tin cơ bản có thể được chuẩn bị ở nhà với hỗ trợ phù hợp; thời gian gặp người dạy dùng để thảo luận, áp dụng và sửa hiểu lầm. Cần phương án cho người học không có thiết bị hoặc mạng tại nhà."]],"prompt":"Thiết kế đánh giá cho [năng lực]. Quy định rõ phần được dùng AI, phần phải tự làm, cách công bố hỗ trợ. Yêu cầu hai bản nháp, lý do sửa và một bài chuyển giao không trợ giúp. Tạo rubric đo quá trình, nội dung và khả năng giải thích; không suy kết luận vi phạm từ văn phong.","body":"Cách thực hiện: 1. Nêu năng lực cần tự thể hiện. 2. Chọn phần AI được dùng và cách khai báo. 3. Yêu cầu dấu vết 2 bản nháp, phản hồi và lý do sửa. 4. Thêm một bài hỏi miệng hoặc bài chuyển giao độc lập. 5. Chấm theo rubric quá trình và sản phẩm.\n\nVì sao cách này hữu ích: Quy tắc và bằng chứng được thiết kế từ đầu, bớt phụ thuộc suy đoán.\n\nChuyển sang lĩnh vực khác: Cách này áp dụng trong đào tạo nhân viên, tuyển dụng, học đại học hoặc tự học; mức AI cho phép tùy kỹ năng cần đo.","activity":{"task":"Mở nguồn của phần này và làm thử: Viết quy tắc dùng AI cho một bài. Dữ liệu: Bài tập: viết phân tích 300 chữ về hai nguồn. Mục tiêu đo là chọn bằng chứng và giải thích lập luận. Bước đầu: Liệt kê hai cách dùng AI được phép và hai cách không được phép.","hint":"Cho AI sửa lỗi chính tả có thể hợp lý; giao AI tự chọn toàn bộ bằng chứng sẽ che khuất kỹ năng đang đo.","sample":"Quy tắc đạt khi người học biết trước mức hỗ trợ, có minh chứng chọn nguồn/giải thích, và có phép kiểm độc lập ngắn. Kết luận vi phạm cần quy trình công bằng, không dựa một dấu hiệu máy."}},{"title":"Tiếp cận công bằng & thiết kế bao trùm","points":[["Khoảng cách tiếp cận","Sách nhấn mạnh sự chênh lệch về mạng, thiết bị, thời gian, hỗ trợ và khả năng tiếp cận. Một khóa học yêu cầu AI ở nhà sẽ bất lợi cho người không có mạng ổn định. “Có công cụ miễn phí” chưa giải quyết hết dữ liệu, kỹ năng và sự hỗ trợ cần thiết."],["Tương đương mục tiêu","Giữ cùng năng lực cần đạt, cho nhiều con đường: phòng máy, tài liệu in, nhóm làm chung, trợ giúp có lịch, hoặc bài không cần AI. Phương án thay thế cần đủ thời gian và chất lượng, không trở thành hình phạt."],["Đo theo nhóm","Trước thử nghiệm, ghi ai có thể dùng, ai bỏ cuộc, chi phí thời gian và kết quả học theo nhóm phù hợp. Bảo vệ quyền riêng tư khi thu thập. Nếu lợi ích chỉ tập trung vào nhóm đã thuận lợi, điều chỉnh phân bổ tài nguyên và thiết kế."]],"prompt":"Với hoạt động [X] và năng lực [M], hãy lập bảng rào cản về thiết bị, mạng, ngôn ngữ, hỗ trợ. Đề xuất hai phương án tương đương cho người có/không có truy cập AI ở nhà. Mỗi phương án cần bằng chứng đạt cùng mục tiêu, thời lượng và cách trợ giúp.","body":"Cách thực hiện: 1. Liệt kê yêu cầu thiết bị, mạng, ngôn ngữ, khả năng tiếp cận. 2. Khảo sát rào cản bằng câu hỏi ít xâm nhập. 3. Thiết kế hai cách hoàn thành cùng mục tiêu. 4. Thử với người dùng ở điều kiện khác nhau. 5. So chất lượng và thời gian, sửa chỗ bất lợi.\n\nVì sao cách này hữu ích: Yêu cầu chuyển từ sự sẵn có của công cụ sang cơ hội hoàn thành thật.\n\nChuyển sang lĩnh vực khác: Dùng cho dịch vụ công, chăm sóc khách hàng và đào tạo nội bộ; rào cản khác nhau nhưng nguyên tắc tương đương giữ nguyên.","activity":{"task":"Mở nguồn của phần này và làm thử: Hai đường học cùng một mục tiêu. Dữ liệu: Mục tiêu: người học so sánh hai bài báo có nguồn. Một nửa lớp có internet ở nhà, nửa còn lại chỉ dùng máy tại lớp. Bước đầu: Thiết kế đường có AI và đường không AI.","hint":"Cung cấp cùng hai bài báo ở dạng in hoặc tải trước.","sample":"Hai đường đều yêu cầu nêu điểm giống/khác và nguồn; AI có thể giúp đặt câu hỏi nhưng không quyết định thay. Cần bố trí thời gian thiết bị tại lớp nếu nhiệm vụ bắt buộc dùng AI."}},{"title":"Thiên lệch, quyền riêng tư & góc nhìn đa dạng","points":[["Thiên lệch trong nội dung","Hình ảnh và văn bản có thể lặp khuôn mẫu từ dữ liệu huấn luyện. Kiểm người/vai trò nào xuất hiện hoặc bị bỏ sót, ngôn ngữ nào được ưu ái và nguồn nào được coi là mặc định. Tăng đa dạng bằng tiêu chí rõ, rồi vẫn kiểm bằng người và tài liệu gốc."],["Quyền riêng tư","Trước khi đưa bài làm, thông tin học viên hoặc dữ liệu tổ chức vào AI, cần biết loại dữ liệu nào thu, lưu bao lâu, ai truy cập, mục đích xử lý, cách xóa và phương án thay thế. Điều kiện cụ thể phụ thuộc công cụ và quy định của tổ chức; không suy từ sách thành luật hiện hành."],["Bong bóng cá nhân hóa","Nếu chỉ luôn cho người học nội dung họ thích hoặc đã biết, họ có thể ít gặp góc nhìn khác. Chèn câu hỏi đối lập, nguồn khác đáng tin và bài chuyển giao mới, đồng thời tránh gây quá tải."]],"prompt":"Hãy rà đầu ra [X] theo ba lớp: dữ kiện có nguồn; nhóm/góc nhìn có thể bị bỏ sót; dữ liệu cá nhân không cần thiết. Đề xuất bản sửa với cùng mục tiêu. Chỉ dùng dữ liệu đã được phép; nếu quyền chưa rõ, dừng và hỏi.","body":"Cách thực hiện: 1. Chọn một đầu ra và liệt kê ai/vấn đề bị thiếu. 2. Đối chiếu 2 nguồn độc lập cho kết luận quan trọng. 3. Ẩn danh hoặc bỏ dữ liệu không cần trước khi thử công cụ. 4. Đặt câu hỏi về lưu trữ/quyền/xóa cho nhà cung cấp. 5. Thêm một góc nhìn phản biện vào thiết kế.\n\nVì sao cách này hữu ích: Prompt kết hợp kiểm nguồn, đại diện và quyền dữ liệu trước khi ứng dụng.\n\nChuyển sang lĩnh vực khác: Dùng cho tuyển dụng, y tế, truyền thông, giáo dục hoặc nghiên cứu; độ nhạy và trách nhiệm duyệt thay theo ngành.","activity":{"task":"Mở nguồn của phần này và làm thử: Rà một bộ câu hỏi học tập. Dữ liệu: Bộ 6 câu hỏi giả định chỉ dùng tên và bối cảnh của một nhóm học viên; một câu chứa tên đầy đủ và điểm cá nhân. Bước đầu: Nêu điểm mất cân bằng và thông tin nhạy cảm.","hint":"Không chỉ đổi tên nhân vật; thay bối cảnh và góc nhìn.","sample":"Bản sửa loại tên/điểm cá nhân khỏi prompt thử, mở rộng ví dụ một cách phù hợp, rồi nhờ người có trách nhiệm xem lại tính chính xác và bao trùm."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Công bằng tiếp cận yêu cầu xem ai có thiết bị, mạng, thời gian, ngôn ngữ và hỗ trợ. Một bài bắt buộc AI ở nhà có thể đặt người thiếu mạng vào thế bất lợi. Cung cấp đường khác tương đương mục tiêu: tài liệu in, thời gian dùng máy tại lớp, làm nhóm hoặc hoạt động không AI, với cùng rubric. Phương án thay thế không nên bị coi là mức học thấp hơn.\n\nQuyền riêng tư và thiên lệch đi kèm. Không cần tải hồ sơ cá nhân lên công cụ để tạo bài luyện; dùng dữ liệu giả định hoặc đã ẩn danh khi có thể. Kiểm các vai trò, nhóm và góc nhìn bị bỏ sót trong ví dụ AI tạo. Cá nhân hóa liên tục theo sở thích cũng có thể thu hẹp góc nhìn; thêm nguồn phản biện và câu hỏi chuyển bối cảnh.","activity":{"task":"Thiết kế hai đường hoàn thành cùng một mục tiêu: có AI ở nhà và không có AI ở nhà. So thời lượng, trợ giúp và rubric.","hint":"Bằng chứng đạt phải tương đương, không chỉ cùng tên bài.","sample":"Cùng phân tích hai nguồn; đường A dùng AI đặt câu hỏi, đường B dùng bảng câu hỏi in; cả hai nộp lý do chọn bằng chứng và bài tự làm."}}],"cases":[{"domain":"Khoa học","situation":"Portfolio học tập một trang","input":"Chọn chủ đề đơn giản bạn đã học, ví dụ một quy trình, quy tắc ngữ pháp hoặc biểu đồ.","steps":["Đặt mục tiêu và hình thức sản phẩm.","Tạo brief/prompt, ghi hai lỗi bản đầu.","Viết 150 chữ phản tư về sửa đổi và kiến thức đã hiểu."],"result":"Portfolio đạt khi có nguồn, mục tiêu, phiên bản, sửa có lý do và người học tự giải thích được kiến thức. Hình đẹp không thay cho sự hiểu đúng.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Sơ đồ vòng tuần hoàn nước có mũi tên được đối chiếu với sách. Dùng trong học nghề, đào tạo công ty, truyền thông khoa học; mọi nơi cần sản phẩm và bằng chứng năng lực."},{"domain":"Tuyển dụng","situation":"Rà một bộ câu hỏi học tập","input":"Bộ 6 câu hỏi giả định chỉ dùng tên và bối cảnh của một nhóm học viên; một câu chứa tên đầy đủ và điểm cá nhân.","steps":["Nêu điểm mất cân bằng và thông tin nhạy cảm.","Viết lại hai câu hỏi đa dạng hơn.","Đề xuất cách dùng dữ liệu mẫu thay dữ liệu thật."],"result":"Bản sửa loại tên/điểm cá nhân khỏi prompt thử, mở rộng ví dụ một cách phù hợp, rồi nhờ người có trách nhiệm xem lại tính chính xác và bao trùm.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Bản tóm tắt ứng viên không suy năng lực từ tên, ảnh hoặc trường học. Dùng cho tuyển dụng, y tế, truyền thông, giáo dục hoặc nghiên cứu; độ nhạy và trách nhiệm duyệt thay theo ngành."}],"practice":{"basic":{"title":"Portfolio học tập một trang","task":"Chọn chủ đề đơn giản bạn đã học, ví dụ một quy trình, quy tắc ngữ pháp hoặc biểu đồ.","steps":["Đặt mục tiêu và hình thức sản phẩm.","Tạo brief/prompt, ghi hai lỗi bản đầu.","Viết 150 chữ phản tư về sửa đổi và kiến thức đã hiểu."],"hint":"Nếu chưa có công cụ ảnh, storyboard bằng chữ vẫn đủ để đánh giá tư duy.","solution":"Portfolio đạt khi có nguồn, mục tiêu, phiên bản, sửa có lý do và người học tự giải thích được kiến thức. Hình đẹp không thay cho sự hiểu đúng."},"applied":{"title":"Rà một bộ câu hỏi học tập","task":"Bộ 6 câu hỏi giả định chỉ dùng tên và bối cảnh của một nhóm học viên; một câu chứa tên đầy đủ và điểm cá nhân.","steps":["Nêu điểm mất cân bằng và thông tin nhạy cảm.","Viết lại hai câu hỏi đa dạng hơn.","Đề xuất cách dùng dữ liệu mẫu thay dữ liệu thật."],"hint":"Không chỉ đổi tên nhân vật; thay bối cảnh và góc nhìn.","solution":"Bản sửa loại tên/điểm cá nhân khỏi prompt thử, mở rộng ví dụ một cách phù hợp, rồi nhờ người có trách nhiệm xem lại tính chính xác và bao trùm."},"rubric":["Có dấu vết quá trình và bài tự làm.","Quy tắc AI công bố trước.","Hai đường tiếp cận có cùng mục tiêu.","Dữ liệu cá nhân và thiên lệch được kiểm."]},"pitfalls":["Đánh giá kỹ xảo thay cho kiến thức.","Nộp sản phẩm mà không giải thích được nội dung.","Đòi nhật ký dài mà không liên hệ mục tiêu.","Chấm chỉ dựa trên độ trau chuốt của sản phẩm.","Đồng nhất công bằng với cho mọi người cùng một link."]},{"number":28,"stage":6,"minutes":180,"title":"Dự án cuối khóa: áp dụng và chứng minh giá trị","subtitle":"Từ vấn đề thật đến nguồn, prompt, thử nghiệm và năng lực chuyển giao.","prerequisites":"Các bài 1–27. Có thể làm dự án không cần lập trình.","refs":[["use-cases",29,32],["agents-guide",32,32],["agents-companion",70,73],["prompt",64,66],["prompt-book",22,97],["prompt-book",735,782],["ai-classroom",127,222],["ai-classroom",223,322]],"objectives":["Tích hợp mục tiêu, nguồn, prompt, eval và quyền.","Chứng minh kết quả bằng phép thử tái hiện được.","Chuyển phương pháp sang lĩnh vực thứ hai."],"sections":[{"title":"Vấn đề, cơ chế và phạm vi","body":"Chọn một tác vụ thật vừa sức trong học tập hoặc công việc: trợ lý đọc tài liệu, bản tin có nguồn, bộ câu hỏi ôn tập, phân tích phản hồi, quy trình soạn nháp hay gia sư AI. Viết brief một trang nêu người dùng, đầu vào, đầu ra, cách làm hiện tại và giá trị mong đợi. Chọn kỹ thuật tối giản đủ đáp ứng: prompt tốt có thể đủ, RAG chỉ khi cần nguồn dài/cập nhật, agent chỉ khi cần tự chọn bước và có công cụ thật.\n\nTạo bộ ca thử trước khi tối ưu: ít nhất 10 ca với dữ liệu thiếu, mâu thuẫn và một lỗi có hậu quả lớn. Giữ vài ca cuối chưa dùng để sửa. Thử hai phiên bản prompt hoặc quy trình, ghi kết quả, thời gian ròng, chi phí và lỗi. Nếu không có công cụ thật, mô phỏng và ghi rõ “mô phỏng”; không báo hành động chưa chạy như đã hoàn tất.","activity":{"task":"Mở Identifying and Scaling AI Use Cases trang PDF 24–32 và Prompt Engineering for Generative AI trang PDF 22–97. Viết brief một trang và ba ca thử cho dự án.","hint":"Một ca cần kiểm quyền hoặc nguồn.","sample":"Dự án tóm tắt chính sách: ca bình thường, ca bản cũ/mới mâu thuẫn, ca người hỏi không có quyền tài liệu."}},{"title":"Dự án cuối khóa: áp dụng vào lĩnh vực của bạn","points":[["Chọn phạm vi có thể hoàn thành","Chọn một việc lặp có dữ liệu và người kiểm tra. Có thể là trợ lý ôn tập, bản tin nghiên cứu, nội dung sản phẩm, phân tích báo cáo hoặc chuẩn bị công việc cá nhân. Không bắt buộc dùng agent; lựa chọn đơn giản nhất đủ đáp ứng là một phần của năng lực cuối khóa."],["Sản phẩm cần bằng chứng","Hồ sơ gồm brief, dữ liệu/nguồn, prompt có phiên bản, quy trình, bộ eval và kết quả thử. Nếu không chạy được công cụ, nộp thiết kế và ghi rõ phần mô phỏng. Không thay chứng cứ thực hiện bằng một báo cáo văn phong chắc chắn."],["Chuyển giao và phản biện","Thử cùng phương pháp trên một lĩnh vực thứ hai, thay tiêu chí và dữ liệu. Ghi phần dùng lại được và phần phải thay. Tự đánh giá theo độ đúng, kiểm chứng, khả năng dùng lại và tính khả thi; sửa lỗi lớn trước khi xem điểm tổng."]],"prompt":"Hỗ trợ dự án [mục tiêu] theo hợp đồng [phạm vi, nguồn, sản phẩm, tiêu chí]. Trước tiên rà dữ liệu và cách kiểm chứng. Xây baseline, ba phiên bản prompt và bộ eval 10 trường hợp có ngoại lệ. Chỉ dùng công cụ thật được cấp; ghi riêng phần mô phỏng. Cuối cùng đánh giá khả năng chuyển phương pháp sang [lĩnh vực thứ hai], nêu điều dùng lại và điều cần thay.","body":"Cách thực hiện: 1. Viết hợp đồng nhiệm vụ một trang và baseline. 2. Tạo nguồn mẫu cùng ít nhất 10 trường hợp eval, gồm 3 trường hợp khó. 3. Viết ba phiên bản prompt, chạy so sánh và chọn theo kết quả. 4. Thiết kế workflow và quyền; chỉ thêm agent nếu có lý do. 5. Thử chuyển sang lĩnh vực thứ hai, viết báo cáo ngắn và kế hoạch cải tiến.\n\nVì sao cách này hữu ích: Dự án đo khả năng chọn đúng phương pháp và kiểm chứng, không đo số kỹ thuật được nhồi vào.\n\nChuyển sang lĩnh vực khác: Đây là phép kiểm tra chuyển giao trực tiếp: thay lĩnh vực nhưng giữ tư duy dữ liệu–mục tiêu–kiểm chứng.","activity":{"task":"Mở nguồn của phần này và làm thử: Hồ sơ thực hành cuối khóa. Dữ liệu: Nếu chưa có dữ liệu thật: dùng 10 ghi chú cuộc họp tự biên soạn, trong đó 3 ghi chú thiếu người/hạn hoặc có thông tin mâu thuẫn. Lĩnh vực thứ hai: tóm tắt 3 đoạn sách do bạn có quyền sử dụng. Bước đầu: Tạo brief và nguồn mẫu có nhãn mô phỏng.","hint":"Mốc gợi ý là 80/100 và không còn lỗi lớn như bịa nguồn, vượt quyền hoặc đánh dấu chưa chạy thành đã chạy.","sample":"Không có một đáp án nội dung duy nhất. Hồ sơ đạt cần tái hiện được: ai dùng, đầu vào gì, prompt nào, đo bằng tiêu chí nào, kết quả thực tế ra sao và phần nào chưa đạt. Bản chuyển lĩnh vực phải nêu tiêu chí mới, không chỉ thay danh từ trong prompt."}},{"title":"Dự án chuyển giao: một hệ học AI có trách nhiệm","points":[["Phạm vi dự án","Chọn một kỹ năng bạn muốn dạy hoặc học: đọc tài liệu, viết báo cáo, giải quyết vấn đề, ngoại ngữ, kỹ thuật hoặc đào tạo công việc. Thiết kế một buổi học và sản phẩm nhỏ. Không cần dùng mọi kỹ thuật; chọn kỹ thuật phục vụ đúng mục tiêu."],["Hai lớp bằng chứng","Lớp thứ nhất là chất lượng hệ thống: prompt, nguồn, lỗi và phiên bản. Lớp thứ hai là học tập: người học tự làm được gì sau khi AI hỗ trợ. Hai lớp có thể khác nhau; đầu ra AI đẹp không chứng minh đã học."],["Chuyển giao và trách nhiệm","Chuyển cùng quy trình sang ngành thứ hai với dữ liệu và tiêu chí mới. Kiểm quyền dùng nguồn/ảnh, điều kiện tiếp cận, nơi cần người hướng dẫn, cách xử lý sai lệch và thông tin cá nhân. Ghi phần thực tế đã thử và phần mới là thiết kế."]],"prompt":"Hãy giúp tôi thiết kế một hoạt động học cho [đối tượng, kỹ năng]. Dùng nguồn [danh sách]. Nêu mục tiêu đo được, việc AI làm và việc người học tự làm, 3 nấc gợi ý, sản phẩm, rubric, 5 ca thử và cách kiểm nguồn. Thêm phương án cho người không truy cập AI ở nhà, quy tắc dữ liệu và một phép thử chuyển sang [lĩnh vực thứ hai]. Đánh dấu phần chưa thực thi.","body":"Cách thực hiện: 1. Viết mục tiêu học, đối tượng, nguồn và ranh giới AI. 2. Tạo brief theo 5 nguyên tắc và hai phiên bản prompt. 3. Thiết kế hoạt động có gợi ý theo nấc, sản phẩm và rubric. 4. Thử 5 ca gồm ngoại lệ, kiểm nguồn và bài tự làm. 5. Lập phương án tiếp cận thay thế và chuyển sang lĩnh vực thứ hai. 6. Tự đánh giá và ghi cải tiến tiếp theo.\n\nVì sao cách này hữu ích: Dự án kiểm cả chất lượng prompt, năng lực người học và điều kiện ứng dụng.\n\nChuyển sang lĩnh vực khác: Chính bước chuyển sang ngành thứ hai cho thấy yếu tố nào là nguyên tắc chung và yếu tố nào phải thiết kế lại.","activity":{"task":"Mở nguồn của phần này và làm thử: Hồ sơ học tập AI 2–4 trang. Dữ liệu: Nếu thiếu dữ liệu thật: tạo 5 mẫu bài làm giả định, trong đó 1 thiếu nguồn và 1 chứa dữ liệu cá nhân cần ẩn. Bước đầu: Viết brief, hai prompt và nguồn trang.","hint":"Hãy thử bài tự làm cuối; nếu người học chỉ chép AI thì cần đổi hoạt động.","sample":"Không có một đáp án nội dung duy nhất. Hồ sơ tốt tái hiện được nguồn, prompt, phép thử, vai trò người học, kết quả, lỗi, phương án tiếp cận và điều thay đổi khi chuyển lĩnh vực."}},{"title":"Phân biệt, kiểm chứng và quyết định áp dụng","body":"Báo cáo cuối nên cho người khác tái hiện: dữ liệu mẫu và nguồn trang, phiên bản prompt, kết quả từng ca, cách chấm, sai lầm đã sửa và quyết định tiếp tục/dừng. Điểm mạnh không phải số kỹ thuật đã dùng mà là sự phù hợp của kỹ thuật với mục tiêu và giới hạn. Nếu chất lượng cải thiện nhưng mất quá nhiều thời gian duyệt, kết luận phải phản ánh lợi ích ròng.\n\nChuyển cùng tư duy sang lĩnh vực thứ hai. Ví dụ cách kiểm nguồn trong báo cáo học thuật chuyển sang biên bản họp, nhưng rubric thay từ chất lượng lập luận sang người–việc–hạn. Ghi phần bất biến (mục tiêu, bằng chứng, phép thử) và phần cần đổi (dữ liệu, quyền, tiêu chí). Đây là phép kiểm hiểu sâu: người chỉ nhớ mẫu prompt sẽ khó chuyển; người hiểu cơ chế sẽ điều chỉnh được.","activity":{"task":"Viết bảng chuyển giao hai cột: nguyên tắc giữ và chi tiết phải thay khi chuyển dự án sang ngành khác.","hint":"Không chỉ thay danh từ trong prompt.","sample":"Giữ bảng nguồn và ca thử; thay loại nguồn, quyền dữ liệu, rubric và người duyệt."}}],"cases":[{"domain":"Học tập → quản lý","situation":"Hồ sơ thực hành cuối khóa","input":"Nếu chưa có dữ liệu thật: dùng 10 ghi chú cuộc họp tự biên soạn, trong đó 3 ghi chú thiếu người/hạn hoặc có thông tin mâu thuẫn. Lĩnh vực thứ hai: tóm tắt 3 đoạn sách do bạn có quyền sử dụng.","steps":["Tạo brief và nguồn mẫu có nhãn mô phỏng.","Chạy các phiên bản trên cùng bộ thử; giữ riêng dữ liệu kiểm tra cuối.","Nộp báo cáo 2–4 trang, bảng kết quả, prompt và một ví dụ chuyển lĩnh vực.","Tự chấm 100 điểm: đúng tác vụ 30, kiểm chứng 30, dùng lại/chuyển giao 20, khả thi/quyền 20."],"result":"Không có một đáp án nội dung duy nhất. Hồ sơ đạt cần tái hiện được: ai dùng, đầu vào gì, prompt nào, đo bằng tiêu chí nào, kết quả thực tế ra sao và phần nào chưa đạt. Bản chuyển lĩnh vực phải nêu tiêu chí mới, không chỉ thay danh từ trong prompt.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Tóm tắt chương sách có nguồn chuyển sang tóm tắt họp; thay tiêu chí kiến thức bằng đầu việc/người/hạn. Đây là phép kiểm tra chuyển giao trực tiếp: thay lĩnh vực nhưng giữ tư duy dữ liệu–mục tiêu–kiểm chứng."},{"domain":"Ngoại ngữ → doanh nghiệp","situation":"Hồ sơ học tập AI 2–4 trang","input":"Nếu thiếu dữ liệu thật: tạo 5 mẫu bài làm giả định, trong đó 1 thiếu nguồn và 1 chứa dữ liệu cá nhân cần ẩn.","steps":["Viết brief, hai prompt và nguồn trang.","Tạo hoạt động, rubric, 5 ca kiểm và một bài tự làm.","Lập phương án offline/quyền dữ liệu.","Chuyển mẫu sang ngành khác; tự chấm 100 điểm: đúng mục tiêu 25, bằng chứng 25, học tập 25, tiếp cận/quyền 25."],"result":"Không có một đáp án nội dung duy nhất. Hồ sơ tốt tái hiện được nguồn, prompt, phép thử, vai trò người học, kết quả, lỗi, phương án tiếp cận và điều thay đổi khi chuyển lĩnh vực.","analysis":"Tình huống minh họa dựa trên bài thực hành của nguồn. Luyện email B1 có phản hồi theo nấc; chuyển sang đào tạo viết email khách hàng. Chính bước chuyển sang ngành thứ hai cho thấy yếu tố nào là nguyên tắc chung và yếu tố nào phải thiết kế lại."}],"practice":{"basic":{"title":"Hồ sơ thực hành cuối khóa","task":"Nếu chưa có dữ liệu thật: dùng 10 ghi chú cuộc họp tự biên soạn, trong đó 3 ghi chú thiếu người/hạn hoặc có thông tin mâu thuẫn. Lĩnh vực thứ hai: tóm tắt 3 đoạn sách do bạn có quyền sử dụng.","steps":["Tạo brief và nguồn mẫu có nhãn mô phỏng.","Chạy các phiên bản trên cùng bộ thử; giữ riêng dữ liệu kiểm tra cuối.","Nộp báo cáo 2–4 trang, bảng kết quả, prompt và một ví dụ chuyển lĩnh vực.","Tự chấm 100 điểm: đúng tác vụ 30, kiểm chứng 30, dùng lại/chuyển giao 20, khả thi/quyền 20."],"hint":"Mốc gợi ý là 80/100 và không còn lỗi lớn như bịa nguồn, vượt quyền hoặc đánh dấu chưa chạy thành đã chạy.","solution":"Không có một đáp án nội dung duy nhất. Hồ sơ đạt cần tái hiện được: ai dùng, đầu vào gì, prompt nào, đo bằng tiêu chí nào, kết quả thực tế ra sao và phần nào chưa đạt. Bản chuyển lĩnh vực phải nêu tiêu chí mới, không chỉ thay danh từ trong prompt."},"applied":{"title":"Hồ sơ học tập AI 2–4 trang","task":"Nếu thiếu dữ liệu thật: tạo 5 mẫu bài làm giả định, trong đó 1 thiếu nguồn và 1 chứa dữ liệu cá nhân cần ẩn.","steps":["Viết brief, hai prompt và nguồn trang.","Tạo hoạt động, rubric, 5 ca kiểm và một bài tự làm.","Lập phương án offline/quyền dữ liệu.","Chuyển mẫu sang ngành khác; tự chấm 100 điểm: đúng mục tiêu 25, bằng chứng 25, học tập 25, tiếp cận/quyền 25."],"hint":"Hãy thử bài tự làm cuối; nếu người học chỉ chép AI thì cần đổi hoạt động.","solution":"Không có một đáp án nội dung duy nhất. Hồ sơ tốt tái hiện được nguồn, prompt, phép thử, vai trò người học, kết quả, lỗi, phương án tiếp cận và điều thay đổi khi chuyển lĩnh vực."},"rubric":["Có brief, baseline và nguồn.","Bộ ca có ngoại lệ, kết quả thật và lỗi nặng.","Có quyết định theo giá trị ròng.","Chuyển sang lĩnh vực hai với tiêu chí mới."]},"pitfalls":["Chọn phạm vi không có dữ liệu hoặc cách đánh giá.","Báo cáo tác vụ chưa chạy như đã hoàn tất.","Dùng nhiều công cụ mà không có phép đo học tập.","Tuyên bố triển khai thành công khi mới chỉ có mô phỏng."]}]);
